/* ChoTenEditor CraftEngine (CE) 字段提示数据库
 * 数据源: CraftEngine 官方 Wiki (docs/configuration + docs/reference 原文)
 * 结构: window.CEHints = { '<字段完整路径>': { zh: '中文原文', en: '英文原文' }, ... }
 * key 规则: 条目根字段用字段名 (如 'fuel_time'), 嵌套字段用路径 (如 'settings.tags', 'data.item-name')
 * 渲染: craftengine-interpreter.js 的 _sfHintIcon/_sfTipText 读取, label 右侧 ℹ 图标悬停显示
 * 富文本标记 (tooltip.js RichTooltip.md): **粗体** / `代码` / \n 换行 / §x 颜色码 (§c红 §a绿 §e黄 §b青 §d粉 §6橙 §9蓝 §7灰)
 */
(function () {
  var ROOT = typeof window !== 'undefined' ? window : globalThis;
  ROOT.CEHints = ROOT.CEHints || {};
  ROOT.CEHints = Object.assign(ROOT.CEHints, {
  "custom_model_data": {"zh":"附加在物品堆叠上。资源包模型 JSON 的 `overrides` 列表将该数字匹配到模型路径。","en":"Attached to the item stack. The resource pack's model JSON `overrides` list matches this number to a model path."},
  "item_model": {"zh":"直接指向 `assets/<ns>/items/<id>.json`。无需 override 查找。","en":"Points directly to `assets/<ns>/items/<id>.json`. No override lookup needed."},
  "texture": {"zh":"普通物品（`paper`、`diamond`、`gold_ingot` …）父模型为 `item/generated`。工具武器（`golden_axe`、`diamond_sword` …）为 `item/handheld`。一个 `texture` 即可。","en":"For plain items (`paper`, `diamond`, `gold_ingot`…) the parent is `item/generated`. For tools and weapons (`golden_axe`, `diamond_sword`…) it's `item/handheld`. A single `texture` is all you need."},
  "textures": {"zh":"你只有纹理 PNG，没有模型 JSON。给 CraftEngine 填入 `texture`（单个）或 `textures`（列表），它会自动生成模型文件并分配路径。这是最常见的场景——没有特殊需求就从这里开始。","en":"You have the PNGs but no model JSONs. Feed CraftEngine a `texture` (one) or `textures` (list) and it generates the model files automatically, assigning paths for you. This is the most common case — start here unless you have a reason not to."},
  "models": {"zh":"你已经在 BlockBench（或其他工具）中制作好了模型 JSON 文件。填入 `model` 或 `models` 字段，附带你的 JSON 路径。CraftEngine 原样使用，不做生成。位置顺序规则与 `textures` 相同。","en":"You already made model JSON files in BlockBench (or elsewhere). Drop the `model` or `models` field with the paths to your JSONs. CraftEngine uses them as-is with no generation. The positional order rules are the same as `textures`."},
  "blueprint": {"zh":"如果你更习惯在 Blockbench 里建模而不想手写 JSON，可以用 `blueprint` 为**每个模型槽位**指定一个 `.bbmodel` 文件——CraftEngine 会把每个文件转换成原版模型 JSON（含贴图），并组装出与纹理写法完全相同的模型树。","en":"If you'd rather model in Blockbench than write JSON, point `blueprint` at one `.bbmodel` file **per model slot** — CraftEngine converts each file into a vanilla model JSON (textures included) and builds the same model tree it would have built from textures."},
  "legacy_model": {"zh":"1.21.4 之前的兼容格式。CraftEngine 会自动将现代模型转换为旧版格式——你通常不需要手动处理。如果只面向 1.21.4+，完全跳过此部分。","en":"Pre-1.21.4 compatibility. CraftEngine auto-converts modern models to legacy format automatically — you should not need this. If you only target 1.21.4+, skip this entirely."},
  "model": {"zh":"自 1.21.4 起，Minecraft 使用**物品模型映射**控制物品渲染哪个模型。CraftEngine 将其封装为 YAML —— `model` 字段决定了物品的一切外观。模型是一棵树：每个节点有一个 `type`，分支类型（`condition`、`select`、`range_dispatch`、`composite`）可嵌套子模型。","en":"Since 1.21.4, Minecraft uses **items model definitions** to control which model renders for an item. CraftEngine wraps this into YAML — the `model` field on an item determines everything about how it looks. A model is a tree: each node has a `type`, and types that branch (`condition`, `select`, `range_dispatch`, `composite`) contain child models."},
  "hand_animation_on_swap": {"zh":"切换手持物品时是否播放第一人称交换动画","en":"Whether the first-person swap animation plays when the held item changes"},
  "oversized_in_gui": {"zh":"若为 `true`，取消 GUI 槽位裁剪——模型可渲染得比槽位更大","en":"If `true`, disables GUI slot clipping — the model can render larger than the slot"},
  "swap_animation_scale": {"zh":"交换动画速度倍率；越大越快","en":"Speed multiplier for the swap animation; larger = faster"},
  "client_bound_data": {"zh":"`client_bound_data` 则把纯展示用的数据搬到客户端去。这些数据不存服务端，而是通过网络包发给玩家，在渲染那一刻才解析。服务端的物品干干净净，不同玩家还能看到不同的东西。","en":"`client_bound_data` moves display-only information off the server. The data is sent through the network protocol and resolved on the client at render time. The server-side item stays lightweight, and different players can see different things."},
  "client_bound_material": {"zh":"更改客户端看到的**视觉**材质，同时保持服务端材质不变。","en":"Changes the visual material the client sees while keeping the server-side material unchanged."},
  "overwritable_lore": {"zh":"这些仅在物品尚未拥有对应数据时才生效——允许其他插件设置自己的值而不被覆盖。","en":"These only take effect when the item doesn't already have the corresponding data — allowing other plugins to set their own values without being overwritten."},
  "overwritable_item_name": {"zh":"这些仅在物品尚未拥有对应数据时才生效——允许其他插件设置自己的值而不被覆盖。","en":"These only take effect when the item doesn't already have the corresponding data — allowing other plugins to set their own values without being overwritten."},
  "overwritable_item_model": {"zh":"这些仅在物品尚未拥有对应数据时才生效——允许其他插件设置自己的值而不被覆盖。","en":"These only take effect when the item doesn't already have the corresponding data — allowing other plugins to set their own values without being overwritten."},
  "overwritable_custom_model_data": {"zh":"这些仅在物品尚未拥有对应数据时才生效——允许其他插件设置自己的值而不被覆盖。","en":"These only take effect when the item doesn't already have the corresponding data — allowing other plugins to set their own values without being overwritten."},
  "fuel_time": {"zh":"控制物品可燃烧的时间（或称燃料热值）。","en":"Determines how many ticks can be burned."},
  "settings.fuel_time": {"zh":"控制物品可燃烧的时间（燃料热值），单位为**刻**（20 刻 = 1 秒）。\n示例: §a`fuel_time: 100`§r 即可燃烧 100 刻（5 秒）。","en":"Determines how many ticks can be burned. Unit is game ticks (20 ticks = 1 second).\nExample: §a`fuel_time: 100`§r burns for 100 ticks (5 seconds)."},
  "tags": {"zh":"标签可以在用命令测试物品时以 `#<命名空间ID>` 的形式调用。也可以在配方中用 `#<命名空间ID>` 的格式使用。只要物品满足了该标签中定义的任何一个物品，测试就会通过。","en":"Tags used in recipes."},
  "settings.tags": {"zh":"物品标签。可以在用命令测试物品时以 `#<命名空间ID>` 的形式调用，也可以在配方中以 `#<命名空间ID>` 的格式使用。只要物品满足了该标签中定义的**任何一个**物品，测试就会通过。\n示例: §a`tags: [\"default:palm_logs\", \"minecraft:logs\"]`§r。","en":"Tags used in recipes. Reference items via `#<namespace:id>` in commands and recipes — as long as the item matches any of the items defined in the tag, the check passes.\nExample: §a`tags: [\"default:palm_logs\", \"minecraft:logs\"]`§r."},
  "equipment": {"zh":"将装备应用于此物品。","en":"Apply the equipment to this item."},
  "settings.equipment": {"zh":"将装备（equipment）应用于此物品。\n**必填参数**: §b`asset_id`§r（如 §a`default:topaz`§r）。\n可选参数: §b`client_bound_model`§r（默认为 config.yml 中的全局选项）。\n1.21.2+ 可选参数（需指定 `slot` 才能生效）: `slot`（head/chest/legs/feet/body/saddle）、`camera_overlay`、`dispensable`、`damage_on_hurt`、`swappable`；1.21.5+ 另有 `equip_on_interact`。","en":"Apply the equipment to this item.\n**Required argument**: §b`asset_id`§r (e.g. §a`default:topaz`§r).\nOptional: §b`client_bound_model`§r (defaults to the global option in config.yml).\nOptional on 1.21.2+ (requires `slot`): `slot` (head/chest/legs/feet/body/saddle), `camera_overlay`, `dispensable`, `damage_on_hurt`, `swappable`; plus `equip_on_interact` on 1.21.5+."},
  "repairable": {"zh":"控制物品是否可以通过工作台或铁砧修复。（默认值：true）","en":"Decides if the item can be repaired through crafting table/anvil. (Default: true)"},
  "settings.repairable": {"zh":"控制物品是否可以通过**工作台或铁砧**修复。（默认值: §etrue§r）\n可以是简单布尔值，也可以填写详细配置分别控制三种修复场景:\n§b`crafting_table`§r 工作台修复、§b`anvil_repair`§r 铁砧材料修复、§b`anvil_combine`§r 铁砧合并。\n详细配置会覆盖上方简单的布尔写法。\n示例: §a`repairable: {crafting_table: true, anvil_repair: false, anvil_combine: true}`§r。","en":"Decides if the item can be repaired through crafting table/anvil. (Default: §etrue§r)\nUse a simple boolean, or a detailed config covering three repair scenarios:\n§b`crafting_table`§r crafting-table repair, §b`anvil_repair`§r anvil material repair, §b`anvil_combine`§r anvil combining.\nThe detailed config overrides the simple boolean above.\nExample: §a`repairable: {crafting_table: true, anvil_repair: false, anvil_combine: true}`§r."},
  "anvil_repair_item": {"zh":"控制指定物品在铁砧修复时提供的耐久度。","en":"Determines how much durability a given item provides when repairing."},
  "settings.anvil_repair_item": {"zh":"控制指定物品在铁砧修复时提供的耐久度。\n配置为**列表**，列表中的每一项包含: §b`target`§r（物品 ID 或 `#标签`）与修复效果。\n两种修复效果二选一: §b`amount`§r 恢复固定耐久度，§b`percent`§r 恢复 n% 总耐久度。\n示例: §a`anvil_repair_item: [{target: \"#topaz_tools\", amount: 20}]`§r。","en":"Determines how much durability a given item provides when repairing.\nConfigured as a **list**; each entry has a §b`target`§r (item id or `#tag`) and a repair effect.\nTwo effects, pick one: §b`amount`§r restores fixed durability, §b`percent`§r restores n% of total durability.\nExample: §a`anvil_repair_item: [{target: \"#topaz_tools\", amount: 20}]`§r."},
  "renameable": {"zh":"控制物品是否可以在铁砧中重命名。（默认值: true）","en":"Determines if the item can be renamed in anvil. (Default: true)"},
  "settings.renameable": {"zh":"控制物品是否可以在铁砧中重命名。（默认值: §etrue§r）\n示例: §a`renameable: false`§r 禁止重命名。","en":"Determines if the item can be renamed in anvil. (Default: §etrue§r)\nExample: §a`renameable: false`§r forbids renaming."},
  "prevent_break": {"zh":"控制物品耐久耗尽时是否阻止其损毁。（默认值: false）","en":"Determines whether the item is prevented from breaking when its durability runs out. (Default: false)"},
  "settings.prevent_break": {"zh":"控制物品耐久耗尽时是否阻止其损毁。（默认值: §efalse§r）\n为 §a`true`§r 时物品保留最后 1 点耐久而不会被销毁。处于\"损坏\"状态的物品将无法使用: 攻击、挖掘、弓/弩射击以及右键使用（如斧削皮、锄地、举盾）都会被阻止，直到修复为止。穿在身上的护甲损坏时会自动脱下——优先放入玩家背包，背包已满则掉落在地上。","en":"Determines whether the item is prevented from breaking when its durability runs out. (Default: §efalse§r)\nWhen §a`true`§r, the item keeps its last point of durability instead of being destroyed. A \"broken\" item can no longer be used: attacking, mining, shooting bows/crossbows and right-click usages (e.g. stripping logs, hoeing dirt, raising a shield) are all blocked until it is repaired. Worn armor is automatically unequipped when it breaks — moved into the player's inventory, or dropped on the ground if the inventory is full."},
  "can_place": {"zh":"决定该物品材质对应的原版方块能否被放置。当你用方块类材质（如 `note_block`）作为非方块物品的基底时，将其设为 `false` 可防止玩家把它放置成方块。（默认值: false）","en":"Determines whether the vanilla block corresponding to this item's material can be placed. Set it to `false` when you use a block-like material (e.g. `note_block`) as the base for a non-block item, so players can't place it as a block. (Default: false)"},
  "settings.can_place": {"zh":"决定该物品材质对应的原版方块能否被放置。当你用方块类材质（如 `note_block`）作为非方块物品的基底时，将其设为 `false` 可防止玩家把它放置成方块。（默认值: false）","en":"Determines whether the vanilla block corresponding to this item's material can be placed. Set it to `false` when you use a block-like material (e.g. `note_block`) as the base for a non-block item, so players can't place it as a block. (Default: false)"},
  "allowed_projectiles": {"zh":"决定了什么弹药可以装在弩和弓上","en":"Determines which item can be loaded into crossbows and bows"},
  "settings.allowed_projectiles": {"zh":"决定了什么物品可以装在弩和弓上（作为弹药）。\n配置为物品 ID 列表，支持自定义物品。\n示例: §a`allowed_projectiles: [gun_world:gun_ammo, minecraft:ender_pearl]`§r。","en":"Determines which item can be loaded into crossbows and bows.\nA list of item ids; custom items supported.\nExample: §a`allowed_projectiles: [gun_world:gun_ammo, minecraft:ender_pearl]`§r."},
  "projectile": {"zh":"基于该物品创建一个自定义弹射物实体。支持 `trident`、`arrow`、`snowball` 等类型。","en":"Creates a custom projectile entity based on the item. It supports `trident`, `arrow`, `snowball` and more."},
  "settings.projectile": {"zh":"基于该物品创建一个自定义弹射物实体。支持 `trident`、`arrow`、`snowball` 等类型。\n子配置: §b`display`§r 显示（物品/位移/旋转/变换/缩放）、§b`sounds`§r 音效（抛出/命中实体/命中方块）、§b`ignore_infinity_enchantment`§r、§b`pickupable`§r、§b`remove_on_hit`§r、§b`gravity`§r、§b`velocity`§r、§b`damage`§r、§b`pierce_level`§r。\n示例: §a`projectile: {display: {item: default:topaz_trident, scale: 0.5}, damage: 10}`§r。","en":"Creates a custom projectile entity based on the item. It supports `trident`, `arrow`, `snowball` and more.\nSub-config: §b`display`§r (item/translation/rotation/transform/scale), §b`sounds`§r (throw/hit_entity/hit_block), §b`ignore_infinity_enchantment`§r, §b`pickupable`§r, §b`remove_on_hit`§r, §b`gravity`§r, §b`velocity`§r, §b`damage`§r, §b`pierce_level`§r.\nExample: §a`projectile: {display: {item: default:topaz_trident, scale: 0.5}, damage: 10}`§r."},
  "dyeable": {"zh":"控制物品是否可以在工作台中染色。（默认值：未定义）","en":"Decides if the item can be dyed in crafting tables. (Default: undefined)"},
  "settings.dyeable": {"zh":"控制物品是否可以在工作台中染色。（默认值: §e未定义§r）\n示例: §a`dyeable: true`§r 允许染色。","en":"Decides if the item can be dyed in crafting tables. (Default: §eundefined§r)\nExample: §a`dyeable: true`§r enables dyeing."},
  "food": {"zh":"基于插件的 food 组件替代实现方案。","en":"Plugin-based alternative implementation for the food component."},
  "settings.food": {"zh":"基于插件的 food 组件替代实现方案，让物品可食用。\n子配置: §b`nutrition`§r（0~20，整数）与 §b`saturation`§r（0~10，浮点数）。\n§6注意: §r建议在 1.20.5 及以上版本的服务器上使用原版 food 组件。","en":"Plugin-based alternative implementation for the food component, making the item edible.\nSub-config: §b`nutrition`§r (0~20, integer) and §b`saturation`§r (0~10, float).\n§6Caution: §rbetter to use the vanilla food component on a 1.20.5+ server."},
  "consume_replacement": {"zh":"控制物品消耗后返回的物品。例如，玩家喝完水瓶后，会返回空瓶。（默认值：null）","en":"Set the return item after consuming the item. For example, after the player drinks the water bottle, the empty bottle will be returned. (Default: null)"},
  "settings.consume_replacement": {"zh":"控制物品消耗后返回的物品。例如，玩家喝完水瓶后，会返回空瓶。（默认值：null）","en":"Set the return item after consuming the item. For example, after the player drinks the water bottle, the empty bottle will be returned. (Default: null)"},
  "craft_remainder": {"zh":"控制在合成配方完成后，物品是否应返还其他物品，或是对参与合成的物品进行一些特殊操作。","en":"Choose whether items should return other items when the crafting recipe is finished."},
  "settings.craft_remainder": {"zh":"控制在合成配方完成后，物品是否应返还其他物品，或是对参与合成的物品进行一些特殊操作。别名: `craft_remaining_item`。\n三种模式:\n1. §b`type: fixed`§r 返回固定物品（`item` + `count`）；\n2. §b`type: hurt_and_break`§r 消耗一定耐久度（`damage`）；\n3. §b`type: recipe_based`§r 根据配方选择剩余物品（`terms`）。\n也可直接简写为物品 ID，如 §a`craft_remainder: bucket`§r。","en":"Choose whether items should return other items when the crafting recipe is finished. Alias: `craft_remaining_item`.\nThree modes:\n1. §b`type: fixed`§r returns a fixed item (`item` + `count`);\n2. §b`type: hurt_and_break`§r consumes a certain amount of durability (`damage`);\n3. §b`type: recipe_based`§r selects the remainder according to the recipe (`terms`).\nCan also be written as a plain item id, e.g. §a`craft_remainder: bucket`§r."},
  "fuel_remainder": {"zh":"作为燃料消耗后会返还的物品，仅适用于堆叠数量为1的物品。","en":"Returned after being consumed as fuel. Only applies to items with a stack size of 1"},
  "settings.fuel_remainder": {"zh":"作为燃料消耗后会返还的物品。仅适用于堆叠数量为 1 的物品。\n示例: §a`fuel_remainder: paper`§r——烧炼后返还纸。","en":"Returned after being consumed as fuel. Only applies to items with a stack size of 1.\nExample: §a`fuel_remainder: paper`§r — paper is returned after smelting."},
  "enchantable": {"zh":"控制物品是否可在附魔台上被附魔。提示：将此项设置为 true 并不会神奇地让原本不可附魔的物品变得可附魔。（默认值：true）","en":"This option lets you block certain items from being used on the enchantment table. Tip: setting it to true won't magically make unenchantable items enchantable. (Default: true)"},
  "settings.enchantable": {"zh":"控制物品是否可在附魔台上被附魔。提示：将此项设置为 true 并不会神奇地让原本不可附魔的物品变得可附魔。（默认值：true）","en":"This option lets you block certain items from being used on the enchantment table. Tip: setting it to true won't magically make unenchantable items enchantable. (Default: true)"},
  "compost_probability": {"zh":"控制物品堆肥成功的几率（默认值：0.5）。","en":"This setting controls how likely it is for composting to succeed (Default: 0.5)."},
  "settings.compost_probability": {"zh":"控制物品堆肥成功的几率。（默认值: §e0.5§r）\n示例: §a`compost_probability: 0.5`§r，取值范围 0~1。","en":"This setting controls how likely it is for composting to succeed. (Default: §e0.5§r)\nExample: §a`compost_probability: 0.5`§r, value range 0~1."},
  "respect_repairable_component": {"zh":"控制物品在铁砧界面中是否允许被 repairable 组件中指定的物品修复。（默认值：false）","en":"This controls if the items listed in repairable component can fix this item in anvil gui. (Default: false)"},
  "settings.respect_repairable_component": {"zh":"控制物品在铁砧界面中是否允许被 repairable 组件中指定的物品修复。（默认值：false）","en":"This controls if the items listed in repairable component can fix this item in anvil gui. (Default: false)"},
  "dye_color": {"zh":"控制物品在染色配方中提供的颜色。","en":"This determines what color it provides in the dyeing recipe."},
  "settings.dye_color": {"zh":"控制物品在**染色配方**中提供的颜色。\n格式: RGB 三元组 `红,绿,蓝`。\n示例: §a`dye_color: 255,140,0`§r（橙色）。","en":"This determines what color it provides in the dyeing recipe.\nFormat: RGB triplet `red,green,blue`.\nExample: §a`dye_color: 255,140,0`§r (orange)."},
  "firework_color": {"zh":"控制物品在烟火之星配方中提供的颜色。","en":"This determines what color it provides in the firework star fade recipe."},
  "settings.firework_color": {"zh":"控制物品在**烟火之星**（firework star）配方中提供的颜色。\n格式: RGB 三元组 `红,绿,蓝`。\n示例: §a`firework_color: 255,140,0`§r。","en":"This determines what color it provides in the firework star fade recipe.\nFormat: RGB triplet `red,green,blue`.\nExample: §a`firework_color: 255,140,0`§r."},
  "ingredient_substitute": {"zh":"控制物品在合成配方中提供的替代物。","en":"This determines which vanilla items this item can serve as an equivalent substitute for within the recipe system."},
  "settings.ingredient_substitute": {"zh":"控制物品在合成配方中可作为哪些原版物品的**等价替代物**。\n配置为物品 ID 列表。\n示例: §a`ingredient_substitute: [minecraft:leather, minecraft:paper]`§r。","en":"This determines which vanilla items this item can serve as an equivalent substitute for within the recipe system.\nA list of item ids.\nExample: §a`ingredient_substitute: [minecraft:leather, minecraft:paper]`§r."},
  "hat_height": {"zh":"决定了这个帽子物品对玩家铭牌高度的影响","en":"This determines the impact of hat height on nametag height"},
  "settings.hat_height": {"zh":"决定这个帽子物品对玩家铭牌（nametag）高度的影响。（需要安装 **CustomNameplates** 插件）\n示例: §a`hat_height: 1.5`§r。","en":"This determines the impact of hat height on nametag height. (Requires **CustomNameplates**)\nExample: §a`hat_height: 1.5`§r."},
  "keep_on_death_chance": {"zh":"决定了死亡后保留此物品的概率","en":"Determines the probability of keeping this item after death."},
  "settings.keep_on_death_chance": {"zh":"决定死亡后**保留**此物品的概率，取值范围 §e0~1§r。\n示例: §a`keep_on_death_chance: 0.2`§r 即 20% 概率保留。","en":"Determines the probability of keeping this item after death, range §e0~1§r.\nExample: §a`keep_on_death_chance: 0.2`§r = 20% chance to keep."},
  "destroy_on_death_chance": {"zh":"决定了死亡后损毁此物品的概率","en":"Determines the probability of this item being destroyed upon death."},
  "settings.destroy_on_death_chance": {"zh":"决定死亡后**损毁**此物品的概率，取值范围 §e0~1§r。\n示例: §a`destroy_on_death_chance: 0.5`§r 即 50% 概率损毁。","en":"Determines the probability of this item being destroyed upon death, range §e0~1§r.\nExample: §a`destroy_on_death_chance: 0.5`§r = 50% chance to be destroyed."},
  "drop_display": {"zh":"用于控制物品实体是否显示名称，以及显示的内容","en":"Used to control whether the names of dropped items are displayed, as well as what content is shown."},
  "settings.drop_display": {"zh":"用于控制物品实体（掉落物）是否显示名称，以及显示的内容。\n三种写法:\n- §a`false`§r 不显示（若全局开启，可针对此物品单独关闭）；\n- §a`true`§r 根据物品名显示实体名；\n- 自定义字符串: §b`<arg:count>`§r 代表数量，§b`<name>`§r 代表物品名，如 §a`\"<arg:count>x <name>\"`§r。","en":"Used to control whether the names of dropped items are displayed, as well as what content is shown.\nThree forms:\n- §a`false`§r hides the name (can be individually disabled when globally enabled);\n- §a`true`§r displays the entity name based on the item name;\n- a custom string: §b`<arg:count>`§r represents the quantity, §b`<name>`§r the item name, e.g. §a`\"<arg:count>x <name>\"`§r."},
  "glow_color": {"zh":"使物品发光并显示颜色","en":"Make items glow and display colors."},
  "settings.glow_color": {"zh":"使物品发光并显示颜色。\n可选取值: §a`black`§r、`dark_blue`、`dark_green`、`dark_aqua`、`dark_red`、`dark_purple`、`gold`、`gray`、`dark_gray`、`blue`、`green`、`aqua`、`red`、`light_purple`、`yellow`、`white`。\n示例: §a`glow_color: white`§r。","en":"Make items glow and display colors.\nOptions: §a`black`§r, `dark_blue`, `dark_green`, `dark_aqua`, `dark_red`, `dark_purple`, `gold`, `gray`, `dark_gray`, `blue`, `green`, `aqua`, `red`, `light_purple`, `yellow`, `white`.\nExample: §a`glow_color: white`§r."},
  "data.item_name": {"zh":"物品的默认名称，默认存在于所有物品上。与 `custom_name` 不同，此名称不可被铁砧抹除，不带斜体，也不会显示在旗帜标记、物品展示框等特定标签中。别名：`display_name`。\n示例: §a`\"<!i><#FF8C00>Topaz Sword\"`§r（支持 MiniMessage 格式）。","en":"The item's default name, present on all items by default. Unlike `custom_name`, this cannot be erased by an anvil, is not italicized, and does not display in certain labels such as banner markers or item frames. Alias: `display_name`.\nExample: §a`\"<!i><#FF8C00>Topaz Sword\"`§r (MiniMessage formatting supported)."},
  "data.custom_name": {"zh":"玩家为物品指定的名称，通常通过铁砧设置。显示优先级最高，默认带斜体（可用 `<!i>` 关闭斜体）。\n示例: §a`\"<!i><#FF8C00>Topaz Sword\"`§r（支持 MiniMessage）。","en":"A player-assigned name for the item, typically set via an anvil. Has highest priority for display and appears italicized by default (disable with `<!i>`).\nExample: §a`\"<!i><#FF8C00>Topaz Sword\"`§r (MiniMessage supported)."},
  "data.lore": {"zh":"物品的描述文本行列表。\n支持高级格式：每条可含 `content`（文本）、`priority`（越低越靠前）、`operation`（`APPEND` 追加/`PREPEND` 前置）、`split_lines`（按换行分行）、`conditions`（条件行）。\n示例: §a`- \"What a shiny sword!\"`§r","en":"The item's description lines.\nAdvanced format per line: `content` (text), `priority` (lower = closer to top), `operation` (`APPEND`/`PREPEND`), `split_lines` (split on newlines), `conditions` (conditional lines).\nExample: §a`- \"What a shiny sword!\"`§r"},
  "data.insert_lore": {"zh":"在现有 lore 的指定位置插入行。\n字段: `position`（§b`HEAD`/`TAIL`/`BEFORE`/`AFTER`§r）、`pattern`（BEFORE/AFTER 用的正则）、`lore`（要插入的行）、`fallback`（未匹配时的回落）。\n示例: §a`position: AFTER`§r + §a`pattern: \"Match this\"`§r\n提示: 可在键后加 `#id` 多次应用同一处理器（如 `insert_lore#1`）。","en":"Inserts lines into existing lore at a specific position.\nFields: `position` (§b`HEAD`/`TAIL`/`BEFORE`/`AFTER`§r), `pattern` (regex for BEFORE/AFTER), `lore` (lines to insert), `fallback` (used when pattern doesn't match).\nExample: §a`position: AFTER`§r + §a`pattern: \"Match this\"`§r\nTip: append `#id` to a data key to apply the same processor multiple times (e.g. `insert_lore#1`)."},
  "data.remove_lore": {"zh":"按正则移除匹配的描述行。\n字符串简写: §a`remove_lore: \"Remove this line\"`§r\n也可用对象形式（`pattern` / `count` / `regex`）精细控制。","en":"Removes lines matching a regex.\nString shorthand: §a`remove_lore: \"Remove this line\"`§r\nAn object form (`pattern` / `count` / `regex`) is also available for finer control."},
  "data.tooltip_style": {"zh":"工具提示背景纹理。","en":"The tooltip background texture."},
  "data.hide_tooltip": {"zh":"隐藏特定组件的工具提示。封装了原版 `minecraft:tooltip_display`，支持跨版本（原 `HideFlags`）。","en":"Hides tooltips from specific components. Wraps vanilla `minecraft:tooltip_display` with cross-version support (formerly `HideFlags`)."},
  "data.dyed_color": {"zh":"可染色物品的颜色（皮革盔甲等）。\n字符串形式: §a`dyed_color: 255,128,64`§r（RGB）\n对象形式: `rgb` + `show_in_tooltip`。","en":"Color for dyeable items (leather armor, etc.).\nString form: §a`dyed_color: 255,128,64`§r (RGB)\nObject form: `rgb` + `show_in_tooltip`."},
  "data.trim": {"zh":"盔甲纹饰图案和材料。\n示例: §a`pattern: eye`§r、§a`material: iron`§r\n图案与材料均可使用自定义资源。","en":"Armor trim pattern and material.\nExample: §a`pattern: eye`§r, §a`material: iron`§r\nBoth pattern and material can be custom."},
  "data.custom_model_data": {"zh":"`data` 内的 `custom_model_data` 仅设置纯整数，**不会绑定模型**。要关联模型定义，请在物品根级配置。","en":"`custom_model_data` inside `data` only sets a plain integer and **does not bind models**. To link a value to a model definition, configure it at the item root level instead."},
  "data.item_model": {"zh":"`data` 内的 `item_model` 仅设置组件值，**不会生成模型**。要关联模型定义并触发生成，请在物品根级配置。","en":"`item_model` inside `data` only sets the component value and **does not generate models**. To link to a model definition and trigger model generation, configure it at the item root level instead."},
  "data.profile": {"zh":"设置玩家头颅皮肤。支持字符串（自动检测为名称、URL 或 base64）或 map 形式（1.20.5+，字段: `name` / `texture` / `url` / `base64`）。\n示例: §a`profile: XiaoMoMi`§r 或 §a`profile: http://textures.minecraft.net/...`§r","en":"Sets a player head skin. Accepts strings (auto-detected as name, URL, or base64) or a map (1.20.5+, fields: `name` / `texture` / `url` / `base64`).\nExample: §a`profile: XiaoMoMi`§r or §a`profile: http://textures.minecraft.net/...`§r"},
  "data.food": {"zh":"设置物品被消耗时应用的食物属性（1.20.5+）。§6物品还需要 `consumable` 组件才可食用。\n字段: `nutrition`（0~20）、`saturation`（0~10）、`can_always_eat`、`eat_seconds`、`using_converts_to`、`effects`（状态效果列表）。\n示例: §a`nutrition: 5`§r、§a`saturation: 3.5`§r","en":"Sets the food stats applied when this item is consumed (1.20.5+). §6The item must also have a `consumable` component to be edible.\nFields: `nutrition` (0~20), `saturation` (0~10), `can_always_eat`, `eat_seconds`, `using_converts_to`, `effects` (status effect list).\nExample: §a`nutrition: 5`§r, §a`saturation: 3.5`§r"},
  "data.equippable": {"zh":"使物品可穿戴在装备槽位中（1.21.2+）。\n字段: `slot`（§b`head`/`chest`/`legs`/`feet`/`body`/`mainhand`/`offhand`/`saddle`§r）、`asset_id`（装备模型，位于 `assets/<ns>/equipment/<id>.json`）、`camera_overlay`、`swappable`、`damage_on_hurt`、`dispensable`、`equip_on_interact`（1.21.5+）。","en":"Lets the item be worn in an equipment slot (1.21.2+).\nFields: `slot` (§b`head`/`chest`/`legs`/`feet`/`body`/`mainhand`/`offhand`/`saddle`§r), `asset_id` (equipment model at `assets/<ns>/equipment/<id>.json`), `camera_overlay`, `swappable`, `damage_on_hurt`, `dispensable`, `equip_on_interact` (1.21.5+)."},
  "data.use_remainder": {"zh":"物品堆叠数量在使用后减少时，将其替换为指定的剩余物（1.21.2+）。\n示例: §a`id: default:chicken_bone`§r、§a`count: 1`§r（可选，默认 1）。","en":"Replaces this item with the specified remainder when its stack count decreases after use (1.21.2+).\nExample: §a`id: default:chicken_bone`§r, §a`count: 1`§r (optional, default 1)."},
  "data.max_damage": {"zh":"物品的最大耐久度（1.20.5+）。\n示例: §a`max_damage: 100`§r\n§6注意: 需搭配有耐久的材质（如 `wooden_sword`）才有效。","en":"The item's maximum durability (1.20.5+).\nExample: §a`max_damage: 100`§r\n§6Note: pair it with a durable material (e.g. `wooden_sword`) for it to take effect."},
  "data.attribute_modifiers": {"zh":"为物品应用属性修饰符。别名: `attributes`。\n列表每一项: `type`（属性）、`amount`（数值）、`operation`（§b`add_value`/`add_multiplied_base`/`add_multiplied_total`§r）、`id`（可选）、`slot`（生效槽位）。\n示例: §a`type: attack_speed`§r、§a`amount: 1.0`§r、§a`slot: mainhand`§r","en":"Applies attribute modifiers to the item. Alias: `attributes`.\nEach list entry: `type` (attribute), `amount`, `operation` (§b`add_value`/`add_multiplied_base`/`add_multiplied_total`§r), `id` (optional), `slot`.\nExample: §a`type: attack_speed`§r, §a`amount: 1.0`§r, §a`slot: mainhand`§r"},
  "data.jukebox_playable": {"zh":"此物品放入唱片机时播放的唱片机曲目（1.21+）。\n字符串形式: §a`jukebox_playable: default:credits_music`§r\n对象形式: `song` + `show_in_tooltip`。","en":"The jukebox song to play when this item is inserted into a jukebox (1.21+).\nString form: §a`jukebox_playable: default:credits_music`§r\nObject form: `song` + `show_in_tooltip`."},
  "data.block_state": {"zh":"放置此物品为方块时应用的方块状态属性。同时能改善高延迟玩家的放置体验。别名: `blockstate`。\n两种形式：属性映射（§a`note: \"1\"`§r、`powered: \"false\"`）或简写 §a`default:palm_sapling[stage=0]`§r。\n§6注意: 材质必须视觉匹配，方块类物品用 `note_block`/`mushroom_stem` 而非 `paper`。","en":"Block state properties applied when placing this item as a block. Also improves placement responsiveness for high-latency players. Alias: `blockstate`.\nTwo forms: a property map (§a`note: \"1\"`§r, `powered: \"false\"`) or shorthand §a`default:palm_sapling[stage=0]`§r.\n§6Note: the material must visually match — use `note_block`/`mushroom_stem`, not `paper`, for block items."},
  "data.pdc": {"zh":"存储自定义键值数据供其他插件读取（持久数据容器）。\n示例: §a`key: \"value\"`§r、§a`number: 42`§r、§a`list: [1, 2]`§r。","en":"Stores custom key-value data for other plugins to read (Persistent Data Container).\nExample: §a`key: \"value\"`§r, §a`number: 42`§r, §a`list: [1, 2]`§r."},
  "data.tags": {"zh":"底层 NBT 访问。在物品上设置任意 NBT 标签。对键名使用 `@` 前缀可展平嵌套结构。","en":"Low-level NBT access. Sets arbitrary NBT tags on the item. Use `@` prefix on keys to flatten nested structures."},
  "data.nbt": {"zh":"底层 NBT 访问。在物品上设置任意 NBT 标签。对键名使用 `@` 前缀可展平嵌套结构。\n示例: §a`CustomTag: \"value\"`§r、§a`\"@nested.path\": 42`§r\n别名: `tags`。","en":"Low-level NBT access. Sets arbitrary NBT tags on the item. Use `@` prefix on keys to flatten nested structures.\nExample: §a`CustomTag: \"value\"`§r, §a`\"@nested.path\": 42`§r\nAlias: `tags`."},
  "data.written_book_content": {"zh":"设置成书的内容——标题、作者、版本与页面（1.20.5+）。需要物品材质为 `written_book`。\n字段: `title`（也支持 `raw`/`filtered` 对象形式）、`author`、`generation`（0 原著/1 副本/2 副本的副本/3 破烂）、`resolved`、`pages`。\n文本支持 MiniMessage，`<arg:...>` 占位符基于构建上下文解析。","en":"Sets the content of a written book — title, author, generation, and pages (1.20.5+). Apply it to an item whose material is `written_book`.\nFields: `title` (also accepts the `raw`/`filtered` map form), `author`, `generation` (0 original / 1 copy / 2 copy of copy / 3 tattered), `resolved`, `pages`.\nText supports MiniMessage; `<arg:...>` placeholders resolve against the build context."},
  "data.external": {"zh":"继承其他插件物品的数据。\n字段: `plugin`（如 §a`neigeitems`§r 或 `source`）、`id`（物品 ID）。\n支持的插件见\"外部物品来源\"文档。","en":"Inherit data from another plugin's item.\nFields: `plugin` (e.g. §a`neigeitems`§r or `source`) and `id` (the item id).\nSee \"External Item Sources\" for supported plugins."},
  "data.components": {"zh":"自定义组件（1.20.5+）——不由 CraftEngine 维护或进行版本检查，格式可能随 Minecraft 更新而变动。键为组件 ID。\n示例: §a`minecraft:max_damage: 128`§r、§a`minecraft:instrument: \"seek_goat_horn\"`§r\n组件仅需存在时写 §a`minecraft:unbreakable: {}`§r。","en":"Your own components (1.20.5+) — not maintained or version-checked by CraftEngine. Format may break across Minecraft updates. Key = component id.\nExample: §a`minecraft:max_damage: 128`§r, §a`minecraft:instrument: \"seek_goat_horn\"`§r\nPresence-only: §a`minecraft:unbreakable: {}`§r."},
  "data.conditional": {"zh":"基于条件的不同数据（§6付费版专属§r）。\n每个 `conditional#<id>` 项含 `conditions`（条件列表，如 `type: permission`）与 `data`（满足条件时应用的数据）。\n示例: §a`conditional#1`§r + §a`conditions: - type: permission`§r","en":"Different data based on conditions (§6premium exclusive§r).\nEach `conditional#<id>` entry has `conditions` (e.g. `type: permission`) and `data` (applied when the conditions match).\nExample: §a`conditional#1`§r + §a`conditions: - type: permission`§r"},
  "model.model": {"zh":"渲染一个模型 JSON 文件（位于 `assets/<命名空间>/models/`）。`type` §e默认为 `minecraft:model`§r，可省略。\n参数:\n§b`path`§r - 必填*；模型 JSON 的命名空间路径（如 `demo:item/sword`）；*设置 `blueprint` 时可选，此时作为生成模型的输出路径\n§b`generation`§r - 可选；从父模板自动生成模型 JSON（§e`parent` 为唯一必填项§r，支持 `textures`/`display`/`gui_light`）\n§b`blueprint`§r - 可选；Blockbench `.bbmodel` 文件（实验性），自动转换为模型 JSON\n§b`tints`§r - 可选；着色来源列表，按 `tintindex` 顺序（第一个条目对应 `tintindex: 0`）\n§b`transformation`§r - 可选（26.1+）；显示变换覆盖\n§a示例§r:\n`model:`\n`  path: minecraft:item/custom/sword`","en":"Renders a single model file from `assets/<namespace>/models/`. `type` defaults to `minecraft:model` — can be omitted.\nParameters:\n§b`path`§r - required*; namespaced path to the model JSON (e.g. `demo:item/sword`); *optional when `blueprint` is set — then used as the output path of the generated model\n§b`generation`§r - optional; auto-generate the model JSON from a parent template (`parent` is the only required field; supports `textures`/`display`/`gui_light`)\n§b`blueprint`§r - optional; Blockbench `.bbmodel` file (experimental) converted into the model JSON\n§b`tints`§r - optional; tint sources, ordered by `tintindex` (first entry → `tintindex: 0`)\n§b`transformation`§r - optional (26.1+); display transform overlay\n§aExample§r:\n`model:`\n`  path: minecraft:item/custom/sword`"},
  "model.model.type": {"zh":"模型类型标识。§e默认 `minecraft:model`§r，`minecraft:` 前缀可省略。\n分支类型: §b`condition`、`select`、`range_dispatch`、`composite`、`special`、`empty`、`bundle/selected_item`§r","en":"Model type identifier. Defaults to `minecraft:model`; the `minecraft:` prefix is optional.\nBranch types: §b`condition`, `select`, `range_dispatch`, `composite`, `special`, `empty`, `bundle/selected_item`§r"},
  "model.model.path": {"zh":"模型 JSON 的命名空间路径（如 `demo:item/sword`）。*设置 `blueprint` 时可选——此时作为生成模型的输出路径","en":"Namespaced path to the model JSON (e.g. `demo:item/sword`). *Optional when `blueprint` is set — then used as the output path for the generated model"},
  "model.model.generation": {"zh":"从父模板自动生成模型 JSON——无需提供模型文件。§e`parent` 为唯一必填项§r。\n参数:\n§b`parent`§r - 必填；继承的父模型（如 `minecraft:item/generated`）\n§b`textures`§r - 纹理变量覆盖（`layer0`、`layer1` …）\n§b`display`§r - 各上下文显示变换（`thirdperson_righthand`、`gui`、`ground`、`fixed`、`head` …）\n§b`gui_light`§r - `front` 或 `side`\n§6注意§r: 与 `blueprint` 不可混用。","en":"Auto-generates the model JSON from a parent template — no model file needed. `parent` is the only required field.\nParameters:\n§b`parent`§r - required; parent model to inherit (e.g. `minecraft:item/generated`)\n§b`textures`§r - texture variable overrides (`layer0`, `layer1`, …)\n§b`display`§r - per-context display transforms (`thirdperson_righthand`, `gui`, `ground`, `fixed`, `head`, …)\n§b`gui_light`§r - `front` or `side`\n§6Note§r: cannot be combined with `blueprint`."},
  "model.model.blueprint": {"zh":"指向 Blockbench `.bbmodel` 文件，生成资源包时自动转换为原版模型 JSON（含几何、显示变换、GUI 光照与内嵌贴图）。§6实验性§r。\n`blueprint` 文件夹与 `configuration`/`resourcepack` 同级；路径相对它，后缀可省略。\n§a示例§r:\n`model:`\n`  blueprint: rocket`\n§e`tints`/`transformation` 可与其同用，`generation` 不可§r。","en":"Points at a Blockbench `.bbmodel` file, converted into a vanilla model JSON at pack generation (geometry, display transforms, GUI lighting and embedded textures included). Experimental.\nThe `blueprint` folder is a sibling of `configuration` and `resourcepack`; paths are relative to it, extension optional.\n§aExample§r:\n`model:`\n`  blueprint: rocket`\n`tints`/`transformation` can be combined with it; `generation` cannot."},
  "model.model.tints": {"zh":"指定各着色索引（`tintindex`）使用的颜色来源。列表顺序 = `tintindex` 顺序（第一个条目对应 `tintindex: 0`）。\n颜色值格式: §e`16711680`§r（十进制）/ §e`255,0,0`§r（RGB 0-255）/ §e`1.0,0.0,0.0`§r（RGB 0.0-1.0）\n类型: §b`minecraft:constant`（固定色）、`dye`（dyed_color 组件）、`firework`、`grass`（气候采样）、`map_color`、`potion`、`team`、`custom_model_data`§r\n§a示例§r:\n`tints:`\n`  - type: minecraft:dye`\n`    default: 16777215`","en":"Specifies the color source for each tint index (`tintindex`). List order = `tintindex` order (first entry → `tintindex: 0`).\nColor formats: §e`16711680`§r (decimal) / §e`255,0,0`§r (RGB 0-255) / §e`1.0,0.0,0.0`§r (RGB 0.0-1.0)\nTypes: §b`minecraft:constant` (fixed color), `dye` (dyed_color component), `firework`, `grass` (climate sampling), `map_color`, `potion`, `team`, `custom_model_data`§r\n§aExample§r:\n`tints:`\n`  - type: minecraft:dye`\n`    default: 16777215`"},
  "model.model.transformation": {"zh":"物品模型变换（26.1+）","en":"Display transform overlay (26.1+)"},
  "model.composite": {"zh":"将多个子模型**叠加在同一个空间**中渲染，从后向前依次渲染——靠前的条目出现在上层。\n参数:\n§b`models`§r - 必填；子模型列表\n§b`transformation`§r - 可选（26.1+）；显示变换覆盖，叠加在子节点变换之上\n§a示例§r:\n`type: minecraft:composite`\n`models:`\n`  - type: minecraft:model`\n`    path: minecraft:item/custom/gem_glow`\n`  - type: minecraft:model`\n`    path: minecraft:item/custom/gem_base`","en":"Renders multiple child models **layered on top of each other** in the same space, rendered from last to first — earlier entries appear on top.\nParameters:\n§b`models`§r - required; list of child models\n§b`transformation`§r - optional (26.1+); display transform overlay, composed with child transforms\n§aExample§r:\n`type: minecraft:composite`\n`models:`\n`  - type: minecraft:model`\n`    path: minecraft:item/custom/gem_glow`\n`  - type: minecraft:model`\n`    path: minecraft:item/custom/gem_base`"},
  "model.composite.models": {"zh":"从后向前依次渲染的物品模型映射","en":"List of child item models to render in order"},
  "model.condition": {"zh":"根据**布尔属性**在两个子模型间切换：属性为 `true` 用 `on_true`，否则用 `on_false`。\n参数:\n§b`property`§r - 必填；布尔属性（如 `minecraft:using_item`、`damaged`、`selected`、`broken`、`carried`、`extended_view`、`fishing_rod/cast`、`has_component`、`keybind_down`、`custom_model_data`…）\n§b`on_true`§r - 必填；为 true 时的模型\n§b`on_false`§r - 必填；为 false 时的模型\n§b`transformation`§r - 可选（26.1+）\n§a示例§r:\n`type: minecraft:condition`\n`property: minecraft:using_item`\n`on_true:`\n`  type: minecraft:model`\n`  path: minecraft:item/custom/bow_pull`\n`on_false:`\n`  type: minecraft:model`\n`  path: minecraft:item/custom/bow`","en":"Switches between two child models based on a **boolean property**: `true` uses `on_true`, otherwise `on_false`.\nParameters:\n§b`property`§r - required; boolean property (e.g. `minecraft:using_item`, `damaged`, `selected`, `broken`, `carried`, `extended_view`, `fishing_rod/cast`, `has_component`, `keybind_down`, `custom_model_data`, …)\n§b`on_true`§r - required; model when the property is `true`\n§b`on_false`§r - required; model when the property is `false`\n§b`transformation`§r - optional (26.1+)\n§aExample§r:\n`type: minecraft:condition`\n`property: minecraft:using_item`\n`on_true:`\n`  type: minecraft:model`\n`  path: minecraft:item/custom/bow_pull`\n`on_false:`\n`  type: minecraft:model`\n`  path: minecraft:item/custom/bow`"},
  "model.condition.property": {"zh":"布尔谓词类型（见下方）","en":"Boolean property type (see below)"},
  "model.condition.on_true": {"zh":"谓词为真时使用的模型","en":"Model when property is `true`"},
  "model.condition.on_false": {"zh":"谓词为假时使用的模型","en":"Model when property is `false`"},
  "model.select": {"zh":"按**离散（字符串/枚举）属性**匹配子模型。无案例匹配时用 `fallback`；未提供 fallback 则渲染为 `empty`。\n参数:\n§b`property`§r - 必填；枚举属性（如 `minecraft:charge_type`、`display_context`、`main_hand`、`trim_material`、`context_dimension`、`context_entity_type`、`local_time`…）\n§b`cases`§r - 必填；`{when, model}` 列表，`when` 为值或值列表（**区分大小写**）\n§b`fallback`§r - 可选；无匹配时使用的模型\n§b`transformation`§r - 可选（26.1+）\n§a示例§r:\n`type: minecraft:select`\n`property: minecraft:charge_type`\n`cases:`\n`  - when: arrow`\n`    model:`\n`      type: minecraft:model`\n`      path: minecraft:item/custom/crossbow_arrow`\n`  - when: rocket`\n`    model:`\n`      type: minecraft:model`\n`      path: minecraft:item/custom/crossbow_firework`","en":"Chooses a child model by matching a **discrete (string/enum) property** against a list of cases. If no case matches, `fallback` is used; without a fallback it renders as `empty`.\nParameters:\n§b`property`§r - required; select property (e.g. `minecraft:charge_type`, `display_context`, `main_hand`, `trim_material`, `context_dimension`, `context_entity_type`, `local_time`, …)\n§b`cases`§r - required; list of `{when, model}` pairs; `when` is a value or list of values (**case-sensitive**)\n§b`fallback`§r - optional; model used when no case matches\n§b`transformation`§r - optional (26.1+)\n§aExample§r:\n`type: minecraft:select`\n`property: minecraft:charge_type`\n`cases:`\n`  - when: arrow`\n`    model:`\n`      type: minecraft:model`\n`      path: minecraft:item/custom/crossbow_arrow`\n`  - when: rocket`\n`    model:`\n`      type: minecraft:model`\n`      path: minecraft:item/custom/crossbow_firework`"},
  "model.select.property": {"zh":"枚举属性类型（见下方）","en":"Select property type (see below)"},
  "model.select.cases": {"zh":"`{when, model}` 配对的列表","en":"List of `{when, model}` pairs"},
  "model.select.when": {"zh":"要匹配的值（区分大小写）","en":"Value(s) to match (case-sensitive)"},
  "model.select.fallback": {"zh":"回落物品模型映射，无匹配时使用","en":"Model used when no case matches"},
  "model.range_dispatch": {"zh":"按**数值属性**与阈值条目比较选模型：选中最后一个 `threshold` ≤ 属性值的条目；属性小于所有阈值时用 `fallback`，无 fallback 则渲染 `empty`。\n参数:\n§b`property`§r - 必填；数值属性（如 `minecraft:damage`、`count`、`cooldown`、`use_cycle`、`compass`、`time`、`use_duration`…）\n§b`scale`§r - §e默认 1.0§r；比较前与属性值相乘的系数\n§b`entries`§r - 必填；`{threshold, model}` 列表（threshold 从小到大排列）\n§b`fallback`§r - 可选；属性小于所有阈值时使用\n§b`transformation`§r - 可选（26.1+）\n§a示例§r（盾牌破损）:\n`type: minecraft:range_dispatch`\n`property: minecraft:damage`\n`scale: 1.0`\n`entries:`\n`  - threshold: 0.0`\n`    model:`\n`      type: minecraft:model`\n`      path: minecraft:item/custom/shield_full`\n`  - threshold: 0.5`\n`    model:`\n`      type: minecraft:model`\n`      path: minecraft:item/custom/shield_cracked`","en":"Selects a child model by comparing a **numeric property** against threshold entries: the last entry whose `threshold` ≤ the property value wins. If no threshold matches, `fallback` is used; without a fallback it renders as `empty`.\nParameters:\n§b`property`§r - required; numeric property (e.g. `minecraft:damage`, `count`, `cooldown`, `use_cycle`, `compass`, `time`, `use_duration`, …)\n§b`scale`§r - default `1.0`; multiplier applied to the property before comparing\n§b`entries`§r - required; list of `{threshold, model}` pairs (thresholds in ascending order)\n§b`fallback`§r - optional; model used when the property is below all thresholds\n§b`transformation`§r - optional (26.1+)\n§aExample§r (damaged shield):\n`type: minecraft:range_dispatch`\n`property: minecraft:damage`\n`scale: 1.0`\n`entries:`\n`  - threshold: 0.0`\n`    model:`\n`      type: minecraft:model`\n`      path: minecraft:item/custom/shield_full`\n`  - threshold: 0.5`\n`    model:`\n`      type: minecraft:model`\n`      path: minecraft:item/custom/shield_cracked`"},
  "model.range_dispatch.property": {"zh":"数值属性类型（见下方）","en":"Numeric property type (see below)"},
  "model.range_dispatch.scale": {"zh":"比较前与属性值相乘的系数","en":"Multiplier applied to the property value before comparing"},
  "model.range_dispatch.entries": {"zh":"`{threshold, model}` 配对的列表","en":"List of `{threshold, model}` pairs"},
  "model.range_dispatch.threshold": {"zh":"使用此模型的最小属性值","en":"Minimum property value for this model"},
  "model.range_dispatch.fallback": {"zh":"回落物品模型映射，检查数值小于所有阈值时使用","en":"Model used when property < all thresholds"},
  "model.special": {"zh":"渲染**硬编码特殊模型**——Minecraft 原生绘制的内容（头颅、箱子、盾牌、旗帜等）。每种特殊类型有自己的字段。\n参数:\n§b`base`§r - 必填*；提供变换参考、粒子纹理和 GUI 光照的模型路径；*设置 `blueprint` 时可选\n§b`model`§r - 必填；特殊模型对象，`type` 为 §e`minecraft:head`、`player_head`、`chest`、`shulker_box`、`shield`、`banner`、`trident`、`conduit`、`decorated_pot`、`bell`、`book`、`end_cube`、`copper_golem_statue`§r 之一\n§b`transformation`§r - 可选（26.1+）\n§a示例§r:\n`type: minecraft:special`\n`base: minecraft:item/custom/head_base`\n`model:`\n`  type: minecraft:head`\n`  kind: skeleton`\n`  texture: minecraft:custom/heads/wizard`","en":"Renders a **hardcoded special model** — things Minecraft knows how to draw natively (heads, chests, shields, banners, etc.). Each special type has its own fields.\nParameters:\n§b`base`§r - required*; model path providing the transform reference, particle texture and GUI light; *optional when `blueprint` is set\n§b`model`§r - required; special model object whose `type` is one of §e`minecraft:head`, `player_head`, `chest`, `shulker_box`, `shield`, `banner`, `trident`, `conduit`, `decorated_pot`, `bell`, `book`, `end_cube`, `copper_golem_statue`§r\n§b`transformation`§r - optional (26.1+)\n§aExample§r:\n`type: minecraft:special`\n`base: minecraft:item/custom/head_base`\n`model:`\n`  type: minecraft:head`\n`  kind: skeleton`\n`  texture: minecraft:custom/heads/wizard`"},
  "model.special.base": {"zh":"用于变换、粒子纹理和 GUI 光照的模型路径。*设置 `blueprint` 时可选——此时作为生成模型的输出路径","en":"Namespaced model path for transforms, particle texture, and GUI light. *Optional when `blueprint` is set — becomes the output path of the generated model"},
  "model.special.model": {"zh":"特殊模型对象，带有自己的 `type`（见下方）","en":"Special model object with its own `type` (see below)"},
  "model.empty": {"zh":"**不渲染任何内容**。适合作为选择类模型的 fallback，让某些属性值不显示模型。\n参数:\n§b`type`§r - 必填；`minecraft:empty`\n§c注意§r: `empty` **不支持** `transformation`。\n§a示例§r:\n`type: minecraft:empty`","en":"Renders **nothing**. Useful as a fallback for selection models when you want certain property values to show no item model.\nParameters:\n§b`type`§r - required; `minecraft:empty`\n§cNote§r: `transformation` is **not** supported on `empty`.\n§aExample§r:\n`type: minecraft:empty`"},
  "model.bundle_selected_item": {"zh":"渲染收纳袋 GUI 中**选中的物品堆叠**；无选中物品或没有 `bundle_contents` 组件时渲染空。\n参数:\n§b`type`§r - 必填；`minecraft:bundle/selected_item`\n§c注意§r: 不支持 `transformation`。\n§a示例§r:\n`type: minecraft:bundle/selected_item`","en":"Renders the selected item stack inside a bundle when the bundle is \"open\" in the GUI. If the bundle has no selected item, renders nothing.\nParameters:\n§b`type`§r - required; `minecraft:bundle/selected_item`\n§cNote§r: `transformation` is **not** supported.\n§aExample§r:\n`type: minecraft:bundle/selected_item`"},
  "model.transformation": {"zh":"`transformation` 可以额外指定展示实体使用的物品模型变换。除 `empty` 和 `bundle/selected_item` 外所有类型均可指定。","en":"`transformation` specifies an extra display transform. Available on all types except `empty` and `bundle/selected_item`."},
  "behavior": {"zh":"物品行为定义了玩家与物品交互时发生的事情——放置方块、放置家具、范围挖掘或堆肥。没有行为，自定义物品只具有其原版材质的交互逻辑，没有特殊行为。","en":"An item behavior defines what happens when a player interacts with the item — placing a block, placing furniture, mining an area, or composting. Without a behavior, a custom item only has the interaction logic of its vanilla material."},
  "behavior.block_item": {"zh":"右键点击有效表面时放置方块。","en":"Places a block when right-clicking on any valid surface."},
  "behavior.ceiling_block_item": {"zh":"与 block_item 类似，但只能放置在方块的**底部**（如吊灯、悬挂灯笼）。","en":"Like block_item, but only places on the **bottom** of a block (e.g., hanging lanterns, chandeliers)."},
  "behavior.compostable_item": {"zh":"让不可堆肥的物品变为可堆肥。","en":"Make non-compostable items compostable"},
  "behavior.double_high_block_item": {"zh":"与 block_item 类似，但专为**两格高**的方块设计（如门）。修复标准 `block_item` 放置时的偏移问题。","en":"Like block_item, but designed for **two-block-tall** blocks (e.g., doors). Fixes placement offsets that occur with standard `block_item`."},
  "behavior.furniture_item": {"zh":"右键点击有效表面时放置家具。","en":"Places a furniture when right-clicking on any valid surface."},
  "behavior.furniture_item.rules": {"zh":"`rules` 将每个家具变体映射到放置约束：","en":"`rules` maps each furniture variant to placement constraints:"},
  "behavior.furniture_item.rules.rotation": {"zh":"家具可朝向的方向数。对 wall 变体无效。","en":"How many directions the furniture can face. Has no effect on wall variants."},
  "behavior.furniture_item.rules.alignment": {"zh":"家具在方块网格上的对齐方式。","en":"How the furniture aligns to the block grid."},
  "behavior.ground_block_item": {"zh":"与 block_item 类似，但只能放置在方块的**顶部**（如树苗、花朵）。","en":"Like block_item, but only places on the **top** of a block (e.g., saplings, flowers)."},
  "behavior.liquid_collision_block_item": {"zh":"与 block_item 类似，但允许放置在**液体表面**（水或熔岩）。使用 `offset_y` 调整相对于液面的放置高度。","en":"Like block_item, but allows placement on **liquid surfaces** (water or lava). Use `offset_y` to adjust the placement height relative to the liquid."},
  "behavior.liquid_collision_furniture_item": {"zh":"与 furniture_item 类似，但允许放置在**液体表面**。","en":"Like furniture_item, but allows placement on **liquid surfaces**."},
  "behavior.multi_high_block_item": {"zh":"与 block_item 类似，但专为**三格及以上**的方块设计。修复标准 `block_item` 放置时的偏移问题。","en":"Like block_item, but designed for blocks **three or more blocks tall**. Fixes placement offsets that occur with standard `block_item`."},
  "behavior.range_mining_item": {"zh":"在破坏方块时同时挖掘可配置区域内的多个方块。范围会根据朝向自动旋转。","en":"Mines multiple blocks in a configurable area when breaking a block. The range automatically rotates to match the direction you are facing."},
  "behavior.range_mining_item.range": {"zh":"`range` 中每条是 `宽,高,深` 偏移。","en":"Each entry in `range` is a `width,height,depth` offset."},
  "behavior.wall_block_item": {"zh":"与 block_item 类似，但只能放置在方块的**侧面**（如墙上的火把、按钮）。","en":"Like block_item, but only places on the **side** of a block (e.g., wall torches, buttons)."},
  "template-type": {"zh":"槽位1（可选）","en":"slot 1 (Optional)"},
  "base": {"zh":"槽位2（必填）","en":"slot 2 (Required)"},
  "addition": {"zh":"槽位3（可选）","en":"slot 3 (Optional)"},
  "merge_components": {"zh":"是否将源物品的组件合并到结果中","en":"merge the source item's components into the result"},
  "post_processors": {"zh":"**结果后处理器**是为解决配方多样化需求引入的概念。例如，如果你想制作一把镐子，但希望输出的镐带有魔咒，那么为每个已附魔的物品都创建一个单独的配方是不切实际的。\n格式: 处理器列表，每项含 `type` 与对应参数（`data` 与物品 data 格式相同）。\n示例: §a`post_processors:\\n- type: apply_data\\n  data:\\n    enchantment:\\n      minecraft:efficiency: 5`§r\n§6目前只有 apply_data 类型，可通过 API 注册新的。§r","en":"The **Result Post Processor** diversifies results — e.g. an enchanted pickaxe, instead of a recipe per item.\nFormat: a list of processors, each with a `type` and params (`data` = item data format).\nExample: §a`post_processors:\\n- type: apply_data\\n  data: ...`§r\n§6Only apply_data exists.§r"},
  "transform_processors": {"zh":"转化处理器用于转换配方（`smithing_transform`、`shaped_transform` 和 `shapeless_transform`），控制源物品的数据如何合并到结果中。\n可用类型: §b`apply_data`§r（应用物品数据）、§b`merge_enchantments`§r（合并魔咒）、§b`keep_custom_data`§r（保留 custom_data 特定路径，1.20.5+）、§b`keep_components`§r（保留指定组件，1.20.5+）、§b`keep_tags`§r（保留指定 NBT 标签，1.20-1.20.4）。","en":"Transform recipes (`smithing_transform`, `shaped_transform`, `shapeless_transform`) control how the source item's data merges into the result.\nTypes: §b`apply_data`§r, §b`merge_enchantments`§r, §b`keep_custom_data`§r, §b`keep_components`§r, §b`keep_tags`§r (1.20.5+; keep_tags: 1.20-1.20.4)."},
  "visual_result": {"zh":"视觉结果功能能够防止玩家提前预知合成/锻造配方的结果。这对于包含随机化物品的配方特别有用。","en":"The visual-result feature prevents players from directly anticipating the outcome of **crafting/smithing** recipes. This is particularly useful for recipes involving randomized items."},
  "functions": {"zh":"当物品成功合成/锻造时，可利用函数执行特定操作。","en":"Functions can be used to run specific functions when an item is successfully crafted/smithed."},
  "conditions": {"zh":"可选；生成战利品前检查的附加条件。","en":"Optional; extra conditions checked before the loot is generated."},
  "unlock_on_ingredient_obtained": {"zh":"如果玩家拥有了该配方的所有原料且满足此配方的条件，则自动为玩家解锁该配方。","en":"If the player has all the ingredients for a recipe and meets its conditions, the recipe will be automatically unlocked for the player."},
  "unlock_on_join": {"zh":"设为 `true` 时，玩家进服后会自动解锁该配方，无需先获取原料。","en":"When set to `true`, the recipe is automatically unlocked for the player when they join the server, regardless of whether they have obtained the ingredients."},
  "category": {"zh":"`category` 决定该配方在配方书中所属的标签栏，可选类型有限。\n烧炼配方可选: §a`food`§r、§a`blocks`§r、§a`misc`§r。\n合成配方可选: §a`building`§r、§a`redstone`§r、§a`equipment`§r、§a`misc`§r。","en":"The `category` determines which tab this recipe is located in within the recipe book. The `category` type is limited.\nFor cooking-type recipes: §a`food`§r, §a`blocks`§r, §a`misc`§r.\nFor crafting-type recipes: §a`building`§r, §a`redstone`§r, §a`equipment`§r, §a`misc`§r."},
  "group": {"zh":"`group` 决定该配方在客户端解锁后所属的分组名称。分组名可自由定义，但请避免使用非法字符。","en":"The `group` determines which group this recipe belongs to after it is unlocked on the client side. The `group` can be any name you choose freely. However, please avoid using illegal characters."},
  "updater": {"zh":"物品更新器用于在配置变更后修补玩家背包中已存在的物品。与 `client_bound_data` 只改外观不同，更新器直接修改物品在服务端的实际数据。","en":"The item updater patches existing items in players' inventories when you change a config. Unlike `client_bound_data` which only updates visuals, the updater modifies the item's actual data on the server."},
  "updater.apply_data": {"zh":"应用 CraftEngine 支持的任何物品数据，格式与 物品数据 相同：","en":"Apply any item data using the same format as Item Data:"},
  "updater.transmute": {"zh":"替换基础材质，保留所有组件和 NBT：","en":"Replace the base material while preserving all components and NBT:"},
  "updater.reset": {"zh":"用最新配置从零重建物品，只保留指定的数据：","en":"Rebuild the item from scratch using the latest config, keeping only specified data:"},
  "settings.hardness": {"zh":"决定了挖掘这个方块需要的挖掘时间。属于方块的**材质档案**，与行为（behavior）无关。（默认值: §e2.0§r）\n示例: §a`hardness: 0.5`§r","en":"Determines how long it takes the player to destroy this block. Part of the block's \"material profile\", independent of any behavior. (Default: §e2.0§r)\nExample: §a`hardness: 0.5`§r"},
  "settings.resistance": {"zh":"决定了方块在爆炸中吸收和阻止爆炸破坏方块传播的强度。（默认值: §e2.0§r）\n示例: §a`resistance: 0.5`§r","en":"Determines the probability of the block surviving the explosion. (Default: §e2.0§r)\nExample: §a`resistance: 0.5`§r"},
  "settings.push_reaction": {"zh":"决定方块在受到活塞推动时的反应。§c请注意，由于客户端视觉同步问题，某些反应可能与某些方块类型不兼容，这个问题将在未来版本中得到修复。（默认值: §eNORMAL§r）\n可选取值:\n- §bNORMAL§r 可推动，可拉动\n- §bDESTROY§r 被推动破坏，不可拉动\n- §bBLOCK§r 不可推动，不可拉动\n- §bIGNORE§r 似乎像 PUSH_ONLY 一样工作，但可以粘附在粘性方块上\n- §bPUSH_ONLY§r 可推动，不可拉动，不粘附在粘性方块上\n示例: §a`push_reaction: NORMAL`§r","en":"Determines how the block reacts to piston pushes. §cSome reactions may not work well with certain block types due to client visual sync issues; this will be fixed in future versions. (Default: §eNORMAL§r)\nValid values:\n- §bNORMAL§r Pistons can push and pull this block normally\n- §bDESTROY§r Blocks pushed by pistons are destroyed instantly\n- §bBLOCK§r Pistons cannot move this block\n- §bIGNORE§r Behaves like PUSH_ONLY but can stick to sticky blocks\n- §bPUSH_ONLY§r Can be pushed but not retracted; does not stick to sticky blocks\nExample: §a`push_reaction: NORMAL`§r"},
  "settings.map_color": {"zh":"决定了地图在表示此方块时会使用的颜色的基色。可用颜色可以在地图存储格式页面查找（https://minecraft.wiki/w/Map_item_format）。（默认值: §e0§r）\n示例: §a`map_color: 36`§r","en":"Determines what color the block is displayed on the map. Available colors can be found on https://minecraft.wiki/w/Map_item_format. (Default: §e0§r)\nExample: §a`map_color: 36`§r"},
  "settings.burnable": {"zh":"决定了熔岩是否可以在该方块上生成火。开启后可与 `fire_spread_chance`（烧毁几率）、`burn_chance`（引燃几率）配合控制火的传播。（默认值: §efalse§r）\n示例: §a`burnable: true`§r","en":"Determines whether this block can be ignited by the environment. When enabled, combine with `fire_spread_chance` and `burn_chance` to control fire behavior. (Default: §efalse§r)\nExample: §a`burnable: true`§r"},
  "settings.fire_spread_chance": {"zh":"影响火与其相邻时破坏该方块的几率和速率。方块烧毁几率为正数时，其所有表面均可燃烧，否则只有其完整的上表面可以燃烧。取值范围 0-100。（默认值: §e0§r）\n示例: §a`fire_spread_chance: 100`§r","en":"Determines how long the block can burn. A longer burn time means a greater chance of spreading fire to surrounding blocks. Range 0-100. (Default: §e0§r)\nExample: §a`fire_spread_chance: 100`§r"},
  "settings.burn_chance": {"zh":"影响火在其附近时传播到该方块表面上的几率和速率。引燃几率为正数的方块被称为可燃方块。取值范围 0-100。（默认值: §e0§r）\n示例: §a`burn_chance: 30`§r","en":"Determines the probability of being ignited. Range 0-100. (Default: §e0§r)\nExample: §a`burn_chance: 30`§r"},
  "settings.item": {"zh":"决定方块对应的物品是什么。通常用于使用鼠标中键点击来选取物品。（默认值: §enull§r）\n示例: §a`item: default:xxx_block_item`§r","en":"Determines the item that this block corresponds to. This is usually used to get blocks in creative mode with middle click. (Default: §enull§r)\nExample: §a`item: default:xxx_block_item`§r"},
  "settings.replaceable": {"zh":"决定了方块是否可以被其他方块通过放置被直接替代掉，影响方块物品放置出方块的方式。（默认值: §efalse§r）\n示例: §a`replaceable: false`§r","en":"Determines whether to replace the block at its original location when the player uses a block to interact with this block. (Default: §efalse§r)\nExample: §a`replaceable: false`§r"},
  "settings.is_redstone_conductor": {"zh":"决定了方块在红石信号传播中的影响。具有红石导体属性的方块被称为红石导体。（默认值: §e未定义§r）\n示例: §a`is_redstone_conductor: true`§r","en":"Determines whether this block is a redstone signal conductor. (Default: §eUNDEFINED§r)\nExample: §a`is_redstone_conductor: true`§r"},
  "settings.is_suffocating": {"zh":"决定了生物视平线处于其中时会发生窒息的方块。（默认值: §e未定义§r）\n示例: §a`is_suffocating: true`§r","en":"Determines whether the player will take suffocation damage. (Default: §eUNDEFINED§r)\nExample: §a`is_suffocating: true`§r"},
  "settings.is_view_blocking": {"zh":"会使视平线处于其中的非旁观模式玩家渲染阻挡视线的效果。绝大多数窒息方块都是视野阻挡方块。但是，此选项对玩家毫无用处，它将影响服务器上的某些实体机制。（默认值: §e未定义§r）\n示例: §a`is_view_blocking: true`§r","en":"Whether to block the line of sight. However, this option is useless for players, but it will affect some entity mechanisms on the server. (Default: §eUNDEFINED§r)\nExample: §a`is_view_blocking: true`§r"},
  "settings.sounds": {"zh":"决定方块在各种情况下的音效。（默认值: §enull§r）\n子键:\n- §bbreak§r 当玩家破坏方块时\n- §bstep§r 当玩家在方块上行走时\n- §bplace§r 当玩家放置方块时\n- §bhit§r 当玩家挖掘方块时\n- §bfall§r 当玩家坠落在方块上时\n§6也可以配置为 `id` + `pitch` + `volume` 形式精确控制音量和音高，`volume` 支持范围值（如 `0.25~0.3`）。\n示例: §a`sounds:\n  break: minecraft:block.deepslate.break`§r","en":"Determines the sound of the block in various situations. (Default: §enull§r)\nSub-keys:\n- §bbreak§r when the player breaks this block\n- §bstep§r when the player walks on this block\n- §bplace§r when the player places this block\n- §bhit§r when the player digs this block\n- §bfall§r when the player falls on this block\n§6A config block with `id` + `pitch` + `volume` precisely controls volume and pitch; ranged values (e.g. `0.25~0.3`) are supported for volume.\nExample: §a`sounds:\n  break: minecraft:block.deepslate.break`§r"},
  "settings.require_correct_tools": {"zh":"决定了是否需要合适挖掘工具才能有效挖掘这个方块。（默认值: §efalse§r）\n§6提示：如果设置了 `correct_tools`，那么 `require_correct_tools` 默认为 `true`。\n示例: §a`require_correct_tools: true`§r","en":"Determines if the correct tool is required for the drops. (Default: §efalse§r)\n§6Tip: if `correct_tools` is set, `require_correct_tools` becomes `true`.\nExample: §a`require_correct_tools: true`§r"},
  "settings.respect_tool_component": {"zh":"决定 `minecraft:tool` 组件的 `correct_for_drops` 选项是否应像 `correct_tools` 一样工作。（默认值: §efalse§r）\n示例: §a`respect_tool_component: false`§r","en":"Decides if the `minecraft:tool` component's `correct_for_drops` option should work as `correct_tools` below. (Default: §efalse§r)\nExample: §a`respect_tool_component: false`§r"},
  "settings.correct_tools": {"zh":"决定了什么物品可以有效地挖掘这个方块，否则不会掉落任何物品。（默认值: §enull§r）\n§6提示：设置了 `correct_tools` 时，`require_correct_tools` 默认为 `true`。\n示例: §a`correct_tools:\n  - minecraft:wooden_pickaxe\n  - minecraft:stone_pickaxe\n  - minecraft:iron_pickaxe`§r","en":"Determines the correct tool required to mine this block, otherwise no item will be dropped. (Default: §enull§r)\n§6Tip: setting `correct_tools` makes `require_correct_tools` default to `true`.\nExample: §a`correct_tools:\n  - minecraft:wooden_pickaxe\n  - minecraft:stone_pickaxe`§r"},
  "settings.incorrect_tool_dig_speed": {"zh":"决定了不使用合适挖掘工具时的挖掘速度是正常的多少倍。取值范围 0~1。（默认值: §e0.3§r）\n示例: §a`incorrect_tool_dig_speed: 0.3`§r","en":"Slows down the dig speed if the tool is incorrect. Range 0~1. (Default: §e0.3§r)\nExample: §a`incorrect_tool_dig_speed: 0.3`§r"},
  "settings.client_bound_tags": {"zh":"客户端侧标签。§6仅适用于原版方块。\n示例: §a`client_bound_tags:\n  - minecraft:beacon_base_blocks`§r","en":"Client-side tags. §6This would only work for vanilla blocks.\nExample: §a`client_bound_tags:\n  - minecraft:beacon_base_blocks`§r"},
  "settings.instrument": {"zh":"决定了方块被放在音符盒下时，音符盒使用的乐器类型。（默认值: §eharp§r）\n示例: §a`instrument: basedrum`§r","en":"Determines what instrument the note block will play when it is above this block. (Default: §eharp§r)\nExample: §a`instrument: BASEDRUM`§r"},
  "settings.fluid_state": {"zh":"决定了方块状态包含的流体状态。可选取值: §bempty§r / §bwater§r。（默认值: §eempty§r）\n示例: §a`fluid_state: water`§r","en":"Decides the fluid state of this block state. Valid values: §bempty§r / §bwater§r. (Default: §eempty§r)\nExample: §a`fluid_state: water`§r"},
  "settings.support_shape": {"zh":"决定了方块提供的**支撑形状**。默认情况下，自定义方块会使用其对应视觉状态的支撑形状。但是，你可以在这里手动指定一个原版方块的支撑形状来代替。\n示例: §a`support_shape: minecraft:stone`§r","en":"Determines the **support shape** provided by the block. By default, custom blocks use the support shape of their corresponding visual state. You can manually specify the support shape of a vanilla block here instead.\nExample: §a`support_shape: minecraft:stone`§r"},
  "settings.destroy_stages": {"zh":"决定了方块被挖掘时显示的**裂纹**。你可以指定若干自定义物品来替换原版的裂纹，并且可以自定义其偏移、旋转和缩放等变换。\n子键: §bitems§r、§btranslation§r（偏移量，推荐）、§bposition§r、§bscale§r、§byaw§r、§bpitch§r、§brotation§r、§bdisplay_transform§r、§bbillboard§r、§bview_range§r、§bbrightness§r\n示例: §a`destroy_stages:\n  items:\n    - minecraft:destroy_stage_0`§r","en":"Determines the destroy stages style displayed when the block is being mined. You can specify a number of custom items to replace the vanilla crack textures, and customize their offset, rotation, scaling, and other transformations.\nSub-keys: §bitems§r, §btranslation§r (offset, recommended), §bposition§r, §bscale§r, §byaw§r, §bpitch§r, §brotation§r, §bdisplay_transform§r, §bbillboard§r, §bview_range§r, §bbrightness§r\nExample: §a`destroy_stages:\n  items:\n    - minecraft:destroy_stage_0`§r"},
  "settings.bounce_restitution": {"zh":"决定了生物下落到方块上后可以反弹多高。绝大多数方块的弹性碰撞系数为0，黏液块的弹性碰撞系数为1，床的弹性碰撞系数为0.75。如果是非生物实体下落导致的碰撞，则计算使用的弹性碰撞系数会额外乘上0.8。","en":"Determines how high a creature can bounce after landing on a block. (Default: 0.0, Slime Block: 1.0, Bed: 0.75)"},
  "settings.friction": {"zh":"决定了方块与站在其上方的生物的\"摩擦力\"，影响生物的加速度并决定稳定移动速度。绝大多数方块的阻力系数为0.6，黏液块的阻力系数为0.8，冰、浮冰、霜冰的阻力系数为0.98，蓝冰的阻力系数为0.989。","en":"It affects how quickly an item slows down when sliding on a block. (Default: 0.6, Ice: 0.98, Blue Ice: 0.989)"},
  "settings.luminance": {"zh":"决定方块的光照等级。（默认值: §e0§r）\n示例: §a`luminance: 15`§r\n§6注意：属于光照系统的设置——`block_light` 和 `can_occlude` 仅影响方块自身发出的光，不影响天空光照（天空光照遮挡完全由客户端决定，无法通过服务器数据包修复）。","en":"Determines the light intensity of the block. (Default: §e0§r)\nExample: §a`luminance: 15`§r\n§6Note: this belongs to the light system — `block_light` and `can_occlude` only affect block-emitted light, not skylight (skylight occlusion is decided entirely by the client and cannot be fixed via packets)."},
  "settings.can_occlude": {"zh":"决定方块是否能阻挡光线。这也会决定该方块是否能将下方的方块转换为另一种类型（例如，草方块变为泥土）。（默认值: §e未定义§r）\n示例: §a`can_occlude: false`§r\n§6注意：仅影响方块自身发出的光，不影响天空光照。","en":"Determines whether this block can block light. This also determines whether the block can turn the block below into another type (e.g. grass_block -> dirt). (Default: §eundefined§r)\nExample: §a`can_occlude: false`§r\n§6Note: only affects block-emitted light, not skylight."},
  "settings.block_light": {"zh":"决定光线穿过此方块后降低的光照等级。（默认值: §e未定义§r）\n示例: §a`block_light: 0`§r（文档示例图片依次为 15 / 7 / 0）\n§6注意：仅影响方块自身发出的光，不影响天空光照。","en":"Determines how much light level is reduced after passing through this block. (Default: §eundefined§r)\nExample: §a`block_light: 0`§r (docs example images show 15 / 7 / 0)\n§6Note: only affects block-emitted light, not skylight."},
  "settings.propagate_skylight": {"zh":"决定天空光照能否穿过该方块。\n示例: §a`propagate_skylight: true`§r\n§6注意：属于光照系统设置；方块对天空光照的遮挡完全由客户端决定，无法通过服务器数据包修复。","en":"Determines whether natural light can pass through this block.\nExample: §a`propagate_skylight: true`§r\n§6Note: this belongs to the light system; skylight occlusion is decided entirely by the client and cannot be fixed via packets."},
  "settings.hit_times": {"zh":"决定玩家需要击打多少次才能破坏此家具。（默认值: §e0§r，即第一次击打即刻破坏）\n§6如果玩家停止击打超过 2 秒，或去击打其他家具，则击打计数会重置。\n示例: §a`hit_times: 3`§r","en":"Determines how many times the player needs to hit the furniture to destroy it. (Default: §e0§r, meaning the furniture breaks instantly on the first hit)\n§6If a player stops hitting for more than 2 seconds or switches to hitting a different piece of furniture, the hit counter resets.\nExample: §a`hit_times: 3`§r"},
  "settings.adventure_mode_breaking": {"zh":"是否允许冒险模式的玩家破坏家具。（默认值: §efalse§r）\n示例: §a`adventure_mode_breaking: true`§r","en":"Whether to allow players in adventure mode to break the furniture. (Default: §efalse§r)\nExample: §a`adventure_mode_breaking: true`§r"},
  "state": {"zh":"当方块只有一种内部状态时，使用 `state` 配置部分。它的本质就是 **视觉状态** + **模型** 的组合：视觉状态决定用哪个原版方块作为载体，模型决定渲染成什么样子。","en":"When a block has only one internal state, use the `state` config section. Its core is the **visual state** + **model** combination: the visual state determines \"which vanilla block to use as the carrier,\" and the model determines \"what it renders as.\""},
  "states": {"zh":"当方块需要多种内部状态时，使用 `states` 配置部分（例如原木的朝向、树叶的 distance/waterlogged）。`states` 由三个子配置部分组成，按顺序配置: §bproperties§r（定义内部属性）→ §bappearances§r（定义可用视觉外观）→ §bvariants§r（将内部状态映射到外观，可选）。\n§6需要多状态的场景: 方块有朝向、可含水、需要多个变体、或需要红石交互。","en":"Use the `states` section when a block needs multiple internal states (e.g. log orientation, leaves' distance/waterlogging). It consists of three sub-sections configured in order: §bproperties§r (define internal properties) → §bappearances§r (define available visual appearances) → §bvariants§r (map internal states to appearances, optional).\n§6You need multi-state when the block has orientation, can be waterlogged, needs multiple variants, or requires redstone interaction."},
  "state.id": {"zh":"通常不需要手动配置。仅当你需要**固定内部 ID**（如配合数据包使用）时才需要。ID 必须**全局唯一**，不能超出 `config.yml` 中 `serverside-blocks` 的值。","en":"Usually unnecessary. Only configure when you need **fixed internal IDs** (e.g., for data pack compatibility). ID must be **globally unique**; Cannot exceed the `serverside-blocks` limit in `config.yml`."},
  "state.auto_state": {"zh":"插件会从预设的**状态组**中自动选择一个空闲的原版状态。同一组内的所有状态共享关键特性（碰撞箱、渲染属性），你无需关心具体用了哪一个。","en":"The plugin automatically picks an available vanilla state from a preset **state group**. All states in the same group share key characteristics (collision box, rendering properties) — you don't need to care which specific one is used."},
  "state.state": {"zh":"当你需要精确控制使用哪个原版状态时，使用 `state`。\n格式 1: 完整的原版方块状态标识，如 §a`state: \"minecraft:note_block[instrument=hat,note=0,powered=false]\"`§r\n格式 2: 映射简写（需预先配置 `block_state_mappings`），如 §a`state: \"note_block:0\"`§r\n§c注意：一个原版方块状态只能绑定到一个自定义模型，重复绑定会在控制台输出冲突警告。","en":"Use `state` when you need precise control over which vanilla state to use.\nFormat 1: full vanilla state identifier, e.g. §a`state: \"minecraft:note_block[instrument=hat,note=0,powered=false]\"`§r\nFormat 2: mapped shorthand (requires `block_state_mappings` to be pre-configured), e.g. §a`state: \"note_block:0\"`§r\n§cNote: a single vanilla block state can only be bound to one unique custom model; rebinding logs a conflict warning in the console."},
  "state.model": {"zh":"`model` 决定视觉状态在客户端渲染成什么样子，有几种互相冲突的配置形式:\n① 仅 `path`（已有模型）\n② `path`+`generation`（自动生成）\n③ `path`+`textures`（插件推断模型结构）\n④ 仅 `texture`（最简单）\n⑤ `models` 列表（加权随机）\n⑥ `transparent: true`（移除原模型）\n⑦ `blueprint`（.bbmodel 源文件）\n其他子键: `path`/`textures`/`generation`/`blueprint`/`x`/`y`/`z`/`uvlock`/`weight`。","en":"`model` determines what the visual state renders as on the client. It has several mutually exclusive configuration combinations:\n① `path` only (existing model file)\n② `path`+`generation` (auto-generate)\n③ `path`+`textures` (plugin infers model structure)\n④ `texture` only (simplest)\n⑤ `models` list (weighted random)\n⑥ `transparent: true` (remove original model)\n⑦ `blueprint` (.bbmodel source)\nSub-keys: `path` / `textures` / `generation` / `blueprint` / `x` / `y` / `z` / `uvlock` / `weight`."},
  "states.properties": {"zh":"属性定义了方块所有可能的内部状态。插件会计算所有属性可能的值的组合，自动生成全部内部状态。","en":"Properties define all possible internal states of a block. The plugin computes the **Cartesian product** of all properties to automatically generate every internal state."},
  "states.appearances": {"zh":"`appearances` 定义方块所有可能的**视觉外观**。每个外观的配置规则与单状态方块完全一致：`auto_state`/`state` + `model`/`models`/`textures`/`transparent`/`entity_renderer`。**第一个定义的外观是为默认外观**——当某个内部状态未匹配到任何变体的 `appearance` 时，自动使用它。","en":"`appearances` defines all possible **visual appearances** for a block. Each appearance follows the exact same configuration rules as single-state blocks (`auto_state`/`state` + `model`/`models`/`textures`/`transparent`/`entity_renderer`). The first defined appearance is the \"default\" — when an internal state doesn't match any variant's `appearance`, it automatically uses this one."},
  "states.variants": {"zh":"`variants` 将内部状态映射到视觉外观。它的核心是**变体键**的匹配逻辑。变体键为 `属性名=值` 对，多属性用逗号分隔，**排列顺序不影响匹配**。未列出的属性匹配所有可能的取值（通配）。","en":"`variants` maps internal states to visual appearances. Its core is the **variant key** matching logic. Variant key = `property_name=value` pairs, multiple properties separated by commas. **Order does not affect matching**. Properties **not listed** in a variant key match **all possible values** of that property (wildcard)."},
  "variants": {"zh":"家具至少要定义一个**变体**。变体决定了家具长什么样、占用多少空间。变体名称可以随便起——`ground`、`ceiling`、`wall` 只是默认 `furniture_item` 行为的约定（顶面→ground、底面→ceiling、侧面→wall），不是规则。\n每个变体包含 §bloot_spawn_offset§r、§belements§r、§bhitboxes§r 等配置。\n§6默认 `furniture_item` 只能放置 `ground`/`ceiling`/`wall`；自定义变体名需自行注册物品行为，或放置后用 `set_furniture_variant` 切换。","en":"A furniture definition must have at least one **variant**. Each variant describes what the furniture looks like and how it occupies space. Variant names are arbitrary — `ground`, `ceiling`, `wall` are just a convention from the default `furniture_item` behavior (top face → ground, bottom → ceiling, side → wall), not a rule.\nEach variant configures §bloot_spawn_offset§r, §belements§r, §bhitboxes§r, etc.\n§6The default `furniture_item` only places `ground`/`ceiling`/`wall`; custom variant names require your own item behavior, or `set_furniture_variant` to switch after placement."},
  "variants.loot_spawn_offset": {"zh":"掉落物偏移，防止掉落物生成在方块内部。格式为 `x,y,z`。（默认值: §e0,0,0§r）\n示例: §a`loot_spawn_offset: 0,0.5,0`§r","en":"Offset for drops so they don't spawn inside blocks. Format: `x,y,z`. (Default: §e0,0,0§r)\nExample: §a`loot_spawn_offset: 0,0.5,0`§r"},
  "variants.elements": {"zh":"**元素**是组成家具的各个独立渲染部件。大多数家具一个元素就够了。需要复杂设计时，可以组合多个元素。比如一个全息投影仪可以拆成底座和投影两个元素：底座固定朝向，投影始终面朝玩家。","en":"In this system, an **Element** refers to each individual component that makes up a piece of furniture. Most furniture items are simple and require only one element. However, you can create more complex designs by assembling multiple elements together. For example, a hologram projector can be built from two elements: a Base and the Projection itself."},
  "variants.hitboxes": {"zh":"判定箱决定了家具的交互范围——玩家能不能穿过去、点哪里。插件内置了几种类型:\n- §binteraction§r 可穿过；用于点击检测、座位、阻止建造\n- §bshulker§r 不可穿过\n- §bhappy_ghast§r 大型判定箱（scale=1 时 4×4 格）\n- §bcustom§r 任意原版实体类型做碰撞检测（默认 `slime`）\n通用参数: `position` / `width` / `height` / `scale` / `interactive` / `seats` 等。\n§6可用 `/ce debug furniture` 在游戏中预览所有判定箱。","en":"A furniture hitbox defines the interactive volume where players can interact with the object. CraftEngine offers several hitbox types:\n- §binteraction§r walk-through; for click detection, seats, blocking placement\n- §bshulker§r not walk-through\n- §bhappy_ghast§r large hitbox (4×4 blocks at scale=1)\n- §bcustom§r any vanilla entity type for collision (defaults to `slime`)\nCommon params: `position` / `width` / `height` / `scale` / `interactive` / `seats`, etc.\n§6Run `/ce debug furniture` to preview all hitboxes in-game."},
  "variants.blueprint": {"zh":"变体可以引用外部插件的模型（例如 BetterModel、ModelEngine，或通过 API 注册的来源）。值为外部插件的模型 ID。\n示例: §a`blueprint: blueprint_id`§r\n§6注意：外部模型绑定到家具的真实基础实体（服务端追踪），每个变体只能有一个；与 `elements` 下的模型（每玩家数据包渲染、无服务端实体、数量不限）不同。","en":"A variant can reference a model from an external plugin (BetterModel, ModelEngine, or a custom source registered through the API). The value is the model id from the external plugin.\nExample: §a`blueprint: blueprint_id`§r\n§6Note: the external model binds to the furniture's real base entity — only one per variant, unlike element models (rendered per-player via packets, no server entity, unlimited)."},
  "variants.entity_culling": {"zh":"实体剔除会在玩家看不到家具时自动隐藏它，降低客户端渲染线程的开销。默认开启。§6付费版专属。\n可整体关闭: §a`entity_culling: false`§r\n也可精细调节: `aabb`（包围盒覆盖）、`aabb_expansion`（包围盒额外填充，默认 0.25）、`view_distance`（剔除前最大距离，-1 为不限）、`ray_tracing`（是否检测视线，默认 true）。","en":"Entity culling hides furniture from players who can't see it, improving performance. Enabled by default. §6Premium exclusive.\nDisable entirely: §a`entity_culling: false`§r\nOr fine-tune: `aabb` (bounding box override), `aabb_expansion` (extra padding, default 0.25), `view_distance` (max distance before culling, -1 = unlimited), `ray_tracing` (line-of-sight check, default true)."},
  "behavior.attached_stem_block": {"zh":"**附着茎方块**将茎与其果实相连，就像原版附着的南瓜茎或西瓜茎。它朝向果实方块，并在PP更新中检查朝向一侧是否仍为指定的果实方块。当果实被移除时，附着茎会自动退化为普通茎方块。","en":"**Attached Stem Block** connects a stem to its fruit, like a vanilla attached pumpkin or melon stem. It faces the fruit block and validates that the fruit is still there. When the fruit is broken, the attached stem automatically reverts to the regular stem block."},
  "behavior.bouncing_block": {"zh":"**弹跳方块**能将落在其上的实体弹回空中。当实体落到这个方块上时，其下落速度会被反转——`bounce_height` 控制反弹时保留多少速度。处于潜行状态下的实体不会被反弹，而是正常落地。摔落伤害仍会生效，但会按 `fall_damage_multiplier` 等比缩放。","en":"**Bouncing Block** bounces entities that land on it back into the air. When an entity falls onto the block, its downward velocity is reversed — `bounce_height` controls how much of that speed is preserved. Sneaking entities do not bounce and land normally. Fall damage is still applied, scaled by `fall_damage_multiplier`."},
  "behavior.budding_block": {"zh":"**母岩方块**按阶段催生附近的方块，类似紫水晶母岩。每个随机刻选取一个随机相邻面，执行以下检查：若该面为**空气或水**，放置 `blocks` 列表中的**第一个**方块；若该面已是**列表中的方块**（非最后阶段），将其升级为列表中的**下一个**方块。","en":"**Budding Block** grows nearby blocks in stages, like budding amethyst. On each random tick, it picks a random adjacent side and checks: if the side is air or water, it places the first block in the `blocks` list; if the side is already one of the listed blocks (except the last stage), it promotes it to the next block in the list."},
  "behavior.bush_block": {"zh":"**灌木方块**只能生长在特定的支撑方块上——类似花或树苗。若支撑方块被破坏或无效，方块即会破坏。可选择堆叠：开启 `stackable` 后，多个同类型方块可互相堆叠，最多 `max_height` 层。堆叠时会计算下方连续的同类型方块数量，当达到最大高度时，将无法继续向上堆叠。","en":"**Bush Block** can only survive on specific blocks directly beneath it — like flowers or saplings. If the supporting block is destroyed or invalid, the bush breaks. It can optionally stack: when `stackable` is enabled, multiple bushes of the same type can pile on top of each other up to `max_height`. A stacked bush counts the same-type blocks below it."},
  "behavior.button_block": {"zh":"**按钮方块**是一种红石电源。被按下时激活并输出信号，片刻后自动弹起关闭。可由以下方式触发：玩家对着按钮使用；射出去的箭和投掷出的三叉戟落在按钮上；风弹命中产生风暴。","en":"**Button Block** is a redstone power source. When pressed it turns on, emits a signal, then automatically pops back up after a moment. It can be triggered by: player right-click; an arrow sticking into it; a wind charge hitting it. The output is always a full-strength **15** signal, sent toward the surface the button is attached to."},
  "behavior.change_over_time_block": {"zh":"**随时间更改方块**在接受到随机刻后会尝试转化层另一种方块，类似铜的氧化。每个随机刻有 `change_speed` 的概率将方块转化为 `next_block`。原方块的属性会被携带到目标方块，除了 `excluded_properties` 中列出的属性——这些将保持目标方块的默认值。","en":"**Change Over Time Block** slowly transforms into another block on random ticks, like copper oxidation. Each random tick has a `change_speed` chance of converting the block to `next_block`. The original block's properties are carried over, except for those listed in `excluded_properties` — these stay at the target block's defaults."},
  "behavior.chime_block": {"zh":"**震响方块**被弹射物（箭、三叉戟等）击中时发出的音效，类似于紫水晶块。","en":"**Chime Block** plays a sound when struck by a projectile (arrow, trident, fireball, etc.), like an amethyst block."},
  "behavior.concrete_powder_block": {"zh":"**混凝土粉末方块**遇水会硬化成固体方块。硬化发生在以下情况：**放置时**——若放置后与水接触；**下落后**——若落在水中或与水接触（常与可下落方块组合使用）；**PP更新时**——若水流到已放置的粉末方块旁。当方块接触到水时，会触发 `BlockFormEvent` 并用 `solid_block` 替换自身。","en":"**Concrete Powder Block** hardens into a solid block when it touches water. This happens on placement, after falling (common combo with `falling_block`), or on neighbor update. When water is detected on any side, the block fires a `BlockFormEvent` and replaces itself with `solid_block`."},
  "behavior.crop_block": {"zh":"**农作物方块**通过随机刻在年龄阶段中生长，类似小麦或马铃薯。仅在光照等级位于 `light_requirement` 与 `max_light_requirement`（包含两端）之间时生长。骨粉可按配置的值增加 `age` 值，但不会超过最大值。","en":"**Crop Block** grows through age stages on random ticks, like wheat or potatoes. Growth only happens within a light range — between `light_requirement` (low) and `max_light_requirement` (high). Bone meal boosts growth by a configurable amount."},
  "behavior.decay_block": {"zh":"**衰变方块**会随着时间的流逝的逐步增加 `age`，直到到达最大值时转变为另一种方块——例如冰融化为水。","en":"**Decay Block** advances through `age` stages and eventually transforms into another block — like ice melting into water."},
  "behavior.directional_attached_block": {"zh":"**定向附着方块**可以附着在另一个方块的侧面上，类似墙上的火把。若附着的方块变动（移动、破坏、替代等）而不再允许附着时，方块会被破坏。放置时会尝试附着到这块空间内最近的有效附着表面。","en":"**Directional Attached Block** attaches to a side face of another block, like a wall torch or a lever. It breaks automatically if the supporting face is removed. On placement it scans nearby block faces in the player's looking direction and picks the first valid one."},
  "behavior.display_item_block": {"zh":"**物品展示方块**在方块上展示一个掉落的物品。手中持有物品时右键放入；空手右键取出。同一时间只能展示一件物品。比较器在检测方块时若存在物品输出信号 **15**，否则输出 **0**（需启用 `has_signal` 选项）。","en":"**Display Item Block** shows a single dropped item on the block. Right-click with an item in hand to place it; right-click with an empty hand to take it back. Only one item can be displayed at a time. A comparator outputs signal **15** when an item is present and **0** when empty (if `has_signal` is enabled)."},
  "behavior.door_block": {"zh":"**门方块**是由下半部分与上半部分组成的两个方块高的结构。放置一个方块可自动创建两半。门可通过手、红石或风弹开启。`hinge` 侧在放置时根据相邻方块的碰撞形状与附近门自动判定，模拟原版门的铰链逻辑。当门的一半被破坏时，另一半也会同步移除。","en":"**Door Block** is a two-block-tall structure with lower and upper halves. Placing one block automatically creates both halves. The door can be opened by hand, redstone, or wind charge. The `hinge` side is determined automatically on placement based on which adjacent blocks have full collision shapes, mimicking vanilla door hinge logic."},
  "behavior.drawer_block": {"zh":"**抽屉方块**是一种存储容器，只能存放一种物品，但能大量存储该物品。它会记住首次存入的物品类型，此后只接受相同物品。","en":"**Drawer Block** is a storage container that holds a single type of item in bulk. It remembers which item was first put in and only accepts that same item thereafter."},
  "behavior.drop_experience_block": {"zh":"**掉落经验方块**在被破坏时掉落经验球。经验点数和掉落条件均可配置——你可以将经验掉落限制为物品带有特定附魔或任意其他条件。若方块要求正确的工具，而玩家用错误的工具破坏它，则不会掉落经验。","en":"**Drop Experience Block** drops experience orbs when broken. The amount and conditions are fully configurable — you can gate XP behind a correct tool, a specific enchantment, or any other condition. If the block requires a correct tool and the player breaks it with the wrong one, no experience is dropped."},
  "behavior.face_attached_horizontal_directional_block": {"zh":"**水平面定向附着方块**可以附着在另一个方块的侧面上，类似按钮或拉杆。若附着的方块变动（移动、破坏、替代等）而不再允许附着时，方块会被破坏。放置时会尝试附着到这块空间内最近的有效附着表面。","en":"**Face Attached Horizontal Directional Block** attaches to a face of another block — floor, ceiling, or wall — like a button or lever. It breaks automatically if the supporting face is removed. On placement it scans nearby faces in the player's looking direction and picks the first valid one."},
  "behavior.falling_block": {"zh":"**可下落方块**会在失去支撑时变为下落的方块，就像原版沙子或沙砾。方块放置后会在 2 刻后检查下方是否存在支撑方块，若下方为空且未低于世界最小高度，则转换为使用当前方块状态的下落的方块。","en":"**Falling Block** becomes a falling entity when there are no blocks beneath it, like sand or gravel. After placement it schedules a check in 2 ticks; if the block below is free and above the minimum world height, a falling entity spawns with the block's appearance."},
  "behavior.fence_block": {"zh":"**栅栏方块**在四个水平方向自动与相邻方块连接。行为与原版栅栏相同。若启用 `can_leash`，右键可用拴绳系在方块上。","en":"**Fence Block** connects to neighboring blocks in all four horizontal directions. The `north`/`east`/`south`/`west` properties update automatically — they turn on when the adjacent block is a sturdy face, a fence with a matching `connectable_block_tag`, or a fence gate. If `can_leash` is enabled, right-clicking with a lead ties the lead to the fence."},
  "behavior.fence_gate_block": {"zh":"**栅栏门方块**行为与原版栅栏门一致。可通过手、红石或风弹开关。用手打开时，门会根据玩家方向调整朝向——若玩家在门后，`facing` 会自动翻转。`in_wall` 属性会根据门朝向两侧的方块状态自动更新，当两侧存在是 `#minecraft:walls` 标签的方块时，该属性会设置为 `true`。","en":"**Fence Gate Block** behaves like a vanilla fence gate. It opens and closes when toggled by hand, redstone, or wind charge. When opening by hand, the gate swings away from the player — if the player is behind it, `facing` flips automatically. The `in_wall` property is auto-detected."},
  "behavior.grass_block": {"zh":"对着**草方块**使用骨粉后，**草方块**会尝试生成一个已配置的地物，其决定了所生成基本内容，例如 `minecraft:grass_bonemeal` 会尝试在方块上方生成草和花。","en":"**Grass Block** reacts to bone meal by growing grass and flowers on and near it. Internally it resolves a vanilla placed feature — a set of placement rules for what vegetation to spawn and where."},
  "behavior.hangable_block": {"zh":"**可悬挂方块**既可放置于地面，也可悬挂在方块下方，就像原版灯笼。放置时会根据周围环境自动选择有效的放置方式。当对应方向的支撑方块被移除时，该方块会自动破坏。","en":"**Hangable Block** can hang from a ceiling or stand on the floor, like a lantern. On placement it tries both orientations and picks the first valid one. If the supporting block above or below is removed, the block breaks."},
  "behavior.hanging_block": {"zh":"**悬挂方块**附着在另一个方块的下方，类似钟乳石。若上方支撑方块被移除，悬挂方块会破坏。可选择堆叠：开启 `stackable` 后，多个同类型方块可向下悬挂，最多 `max_height` 层。","en":"**Hanging Block** attaches to the underside of another block, like a dripstone. If the supporting block above is removed, the hanging block breaks. It can optionally stack: when `stackable` is enabled, hanging blocks of the same type can chain downward from each other up to `max_height`."},
  "behavior.item_frame_block": {"zh":"**物品展示框方块**是原版物品展示框的高性能替代方案。用于存储和展示单个物品。**右键**手持物品放入。**空主手右键**取出物品。**潜行 + 右键**旋转展示的物品（共 8 个方向）。比较器信号等于 `rotation + 1`（有物品时），空时为 `0`。","en":"**Item Frame Block** is a high-performance replacement for vanilla item frames. It stores and displays a single item. Right-click with an item in hand to place it; right-click with an empty main hand to take the item back; sneak + right-click to rotate the displayed item through 8 directions. The comparator signal equals `rotation + 1` when an item is present."},
  "behavior.lamp_block": {"zh":"**灯方块**根据红石信号切换 `lit` 点亮状态，就像原版红石灯。收到红石信号会立刻被点亮，失去红石信号供给后需要 4 刻才能熄灭。放置时会自动检测附近的红石信号并设置正确的初始状态。","en":"**Lamp Block** toggles its `lit` state in response to redstone power, just like a vanilla redstone lamp. When a neighbor signal arrives it turns on instantly; when the signal disappears it waits 4 ticks before turning off. On placement it automatically checks for nearby redstone power and sets the correct initial state."},
  "behavior.leaves_block": {"zh":"**树叶方块**会在PP更新中计算其到最近原木的距离并作为 `distance` 的值（原木为 0，直接相邻的树叶为 1，以此类推）。达到最大距离（`distance` 属性的 `range` 中的最大值）的树叶会在接收到一个随机刻时会枯萎并掉落物品。当 `persistent` 为 `true` 时树叶不参与距离计算，无论距离多远都不会枯萎。","en":"**Leaves Block** decays when disconnected from a log. Each leaf block continuously computes its `distance` to the nearest log: logs are 0, directly adjacent leaves are 1, and so on. Leaves at the maximum distance (the largest value in the `distance` property's range) will decay on a random tick, dropping their items. Setting `persistent` to `true` prevents decay entirely."},
  "behavior.liquid_flowable_block": {"zh":"**流体推动方块**可被水或熔岩替换，就像矮草丛或火把。当流体流入时，方块会被破坏并替换为对应流体。**水：** 若 `drop_item` 为 `true`，方块会掉落对应物品。**熔岩：** 方块不会掉落物品，而是直接摧毁方块。","en":"**Liquid Flowable Block** can be washed away by water or lava, like grass or torches. When liquid flows into it, the block is destroyed and replaced with the fluid. Water: the block drops as an item if `drop_item` is `true`. Lava: the block is always destroyed without dropping items."},
  "behavior.multi_high_block": {"zh":"**多层方块**会根据指定的 `int` 属性自动生成一个垂直连续的多格结构。属性的取值范围决定结构的层数。放置时会自动在上方生成其余层级，并将每层的属性值设置为对应高度。结构中的每一层都必须与其应连接的上一层或下一层保持连续。","en":"**Multi High Block** places multiple stacked copies of itself on placement, forming a single tall structure — like a door or tall grass. The number of segments is controlled by an `int` property whose `range` (max − min) defines the stack height. The stack is connected: if any middle segment loses its neighbor above or below, the whole column breaks."},
  "behavior.near_liquid_block": {"zh":"**邻液方块**必须放置在靠近水或熔岩的位置才能存活。与液面方块不同，它不要求液体必须是源方块——流动液体也有效。冰视为水源。它检查方块周围的特定相对位置（通过 `positions` 配置）。若启用 `stackable`，方块也可堆叠在同类型方块上存活。","en":"**Near Liquid Block** must be placed near water or lava to survive. Unlike `on_liquid_block`, it does not require the liquid to be a source — flowing liquid also counts. Ice counts as a water source. It checks specific positions relative to the block (configured via `positions`)."},
  "behavior.on_liquid_block": {"zh":"**液面方块**只能放置在液体源表面上，类似睡莲。与 `near_liquid_block` 不同，它要求正下方必须是液体**源**方块——流动液体不算。冰视为水源。启用 `stackable` 后，方块也可堆叠在同类型方块上存活。","en":"**On Liquid Block** sits on the surface of a liquid source, like a lily pad. Unlike `near_liquid_block`, it requires the block directly beneath to be a liquid **source** block — flowing liquid does not count. Ice counts as a water source. When `stackable` is enabled, the block can also survive on another block of the same type."},
  "behavior.pressure_plate_block": {"zh":"**压力板方块**是一种可以用来探测玩家、生物等实体的方块。当实体踩上时，发出 **15** 强度的强充能信号，在实体离开后持续保持 `pressed_time` 刻按下。选项 `sensitivity` 可以控制哪些实体能触发压力板：**`all`（默认）：** 任意实体。**`mob`：** 仅限生物。","en":"**Pressure Plate Block** is a redstone power source triggered by entities standing on it. When an entity steps on the plate, it outputs a full-strength **15** signal and stays pressed for `pressed_time` ticks after the entity leaves. The `sensitivity` controls which entities can activate it: `all` (default) any entity, `mob` only living entities."},
  "behavior.sapling_block": {"zh":"**树苗方块**会随时间生长。每次随机刻，若光照条件满足，则以 `grow_speed` 的概率使 `stage` 增加 1。当 `stage` 达到最大值时，会通过配置的**地物（feature）**或**结构（structure）**生成完整的树木。仅当方块上方位置的亮度位于 `light_requirement`（下限，默认为 9）与 `max_light_requirement`（上限，默认为 15）之间时才会生长。","en":"**Sapling Block** grows through `stage` levels on random ticks and eventually generates a full tree — either from a configured **feature** or from a worldgen **structure**. Growth only happens within a light range — between `light_requirement` (low, default 9) and `max_light_requirement` (high, default 15)."},
  "behavior.seat_block": {"zh":"**座椅方块**让玩家通过右键方块坐在上面。每个 `seats` 配置定义一个座位和一个可选偏航角旋转锁定角度。若配置了 `facing` 属性会自动计算座椅的相对位置——位置随方块朝向旋转，因此同个坐标适用于所有方向。","en":"**Seat Block** lets players sit on it by right-clicking. Each `seats` entry defines a sitting position and an optional yaw rotation lock. The optional `facing` property automatically transforms seat positions — positions rotate with the block's facing direction, so one set of coordinates works for all orientations."},
  "behavior.simple_particle_block": {"zh":"**简单粒子方块**按固定间隔生成粒子效果。每个粒子配置可自定义效果类型、位置偏移、扩散范围、数量与速度。需要特定参数的粒子类型可使用相应子选项。","en":"**Simple Particle Block** spawns particle effects at a fixed interval. Each particle entry defines the effect type, position offset, spread, count, and speed. Type-specific parameters (item, block, dust color, etc.) are available for particles that require them."},
  "behavior.simple_storage_block": {"zh":"**简单存储方块**是类似箱子的容器，可自定义行数。右键可打开容器界面以存储物品。比较器可检测该容器，并根据其填充程度输出 0–15 的红石信号。可选的 `open` 属性用于反映容器的开关状态——适合在方块模型中显示打开或关闭的视觉效果。","en":"**Simple Storage Block** is a chest-like container with a configurable number of rows. Right-click to open its GUI and store items. A built-in 0–15 comparator signal reflects how full the inventory is. The optional `open` property tracks whether the GUI is open — useful for switching to an \"open\" visual state in your block model."},
  "behavior.slab_block": {"zh":"**台阶方块**行为与原版台阶一致。放置在方块下半部分或上半部分可创建下半台阶或上半台阶。将相同台阶放置在已有的单层台阶上会将两者合并为双层台阶。双层台阶无法含水，液体也无法流入双层台阶。","en":"**Slab Block** behaves like a vanilla slab. Placing it on the bottom or top half of a block creates a bottom or top slab. Placing the same slab on an existing single slab converts both into a double slab (full block). Double slabs cannot be waterlogged."},
  "behavior.snowy_block": {"zh":"**覆雪方块**自动检测顶部是否有雪，并据此设置 `snowy` 属性。这与原版草方块切换到覆雪材质的机制相同——当一个带有 `minecraft:snow` 标签的方块直接放在上方时，`snowy` 会被设置为 `true`。放置时也会同步检测上方方块，以确保初始状态正确。","en":"**Snowy Block** automatically detects whether snow sits on top of it and sets the `snowy` flag accordingly. This is the same mechanic vanilla grass blocks use to switch to their snow-covered texture — when a block tagged `minecraft:snow` is placed directly above, `snowy` becomes `true`. It also checks on placement."},
  "behavior.sofa_block": {"zh":"**沙发方块**的行为类似可连接的座椅。`shape` 属性会在PP更新时根据周围沙发的朝向自动计算为直形或内角，从而形成连续的沙发结构。","en":"**Sofa Block** behaves like a connectable seat. Its `shape` is automatically detected — straight or inner corner — based on whether another sofa of the same type sits at a right angle behind it. The `shape` updates whenever a neighboring block changes."},
  "behavior.spreading_block": {"zh":"**扩散方块**会在收到随机刻后尝试向周围扩散。每次尝试都会在附近随机选择一个位置，若该位置的方块类型与 `target_block` 相同，则将其替换为自身。","en":"**Spreading Block** spreads to nearby blocks on random ticks. Each tick it picks a random position nearby and, if that block matches `target_block`, replaces it with itself."},
  "behavior.stackable_block": {"zh":"**可堆叠方块**允许使用指定物品对已有方块进行堆叠，就像海泡菜或蜡烛。使用 `items` 列表中配置的物品对方块放置时，会递增指定 int 属性的值，直到达到该属性的最大值。不同的属性值可用于切换不同的视觉状态。","en":"**Stackable Block** lets you place the same block on top of an existing one to increase a count, like sea pickles or candles. Right-clicking with one of the configured `items` increments the block's internal count, up to the int property's `max` value. Each count level can have its own visual state in the block model."},
  "behavior.stairs_block": {"zh":"**楼梯方块**行为与原版楼梯一致。放置时根据点击位置自动设置 `facing` 与 `half`。`shape` 属性会根据周围楼梯自动计算为直梯、内角或外角，从而形成连续的楼梯结构。","en":"**Stairs Block** behaves like vanilla stairs. On placement it sets the correct `facing` and `half` based on where you click. Its `shape` (straight, inner corner, outer corner) is automatically recalculated whenever neighboring blocks change — the stairs \"connect\" visually by detecting adjacent stairs of the same half."},
  "behavior.stem_block": {"zh":"**茎方块**会随时间生长，就像原版西瓜或南瓜茎。每次随机刻都会进入一个 `age` 阶段。达到最大值后，会随机选择一个水平方向。若目标位置为空气且其下方方块满足条件，则在该位置生成果实，并将自身替换为朝向果实的附着茎方块。骨粉可使茎额外生长多个 `age` 阶段。","en":"**Stem Block** grows over time like a vanilla melon or pumpkin stem. On each random tick it advances one `age` stage. Once fully mature, it picks a random horizontal direction, checks that the block below is valid, and places a fruit there — then transforms itself into the `attached_stem` block facing the fruit."},
  "behavior.strippable_block": {"zh":"**可剥离方块**可用斧右键剥离，就像原版原木。剥离后会转换为 `stripped` 选项指定的方块，并尽可能保留原方块的属性值。若某些属性被列入 `excluded_properties`，则不会继承其值，而是使用目标方块对应属性的默认值。","en":"**Strippable Block** can be stripped by right-clicking with an axe, like vanilla logs. It transforms into the `stripped` block while keeping the original block's property values — except for those listed in `excluded_properties`, which are left at the target block's defaults."},
  "behavior.sturdy_base_block": {"zh":"**稳固基底方块**需要在指定方向上有一个坚固的支撑面。若支撑的方块被移除，方块会被破坏。三种可用的支撑类型：`full`、`rigid` 和 `center`。启用 `stackable` 后，方块也可通过堆叠在同类型方块上存活——在支撑方向上最多可有 `max_height` 个连续堆叠的同类型方块。","en":"**Sturdy Base Block** requires a solid supporting face in a given direction. The block breaks if the support is removed. Three support types are available: `full`, `rigid`, and `center`. When `stackable` is enabled, the block can also survive by stacking on another block of the same type — up to `max_height` consecutive stacked copies."},
  "behavior.surface_spreading_block": {"zh":"**表面扩散方块**会随时间向相邻方块扩散，就像原版草在泥土上蔓延一样。每个随机刻它会尝试把附近的 `base_block` 转化为自身——而如果它所在的位置已无法存活（光照被遮挡或上方有水），就会退化回 `base_block`。只有当目标方块上方光照在配置范围内且无水时，才会向其扩散。","en":"**Surface Spreading Block** spreads to nearby blocks over time, just like vanilla grass spreading across dirt. On each random tick it tries to convert nearby `base_block`s into copies of itself — and if it can no longer survive where it stands (light blocked or water above), it turns back into the `base_block`."},
  "behavior.tint_source_block": {"zh":"**颜色提供器方块**可以将物品作为颜色提供器存入方块实体，使方块实体渲染器元素可根据存储的物品动态着色。若启用 `drop_item`，方块被破坏时存储的物品会掉落。","en":"**Tint Source Block** stores an item as a tint provider for the block's render elements, allowing the block's color to be dynamically tinted based on the stored item. The stored item is returned when the block is broken if `drop_item` is enabled."},
  "behavior.toggleable_lamp_block": {"zh":"**可切换灯方块**通过切换 `lit` 属性控制亮灭状态。可由红石、手动交互或两者共同控制。**红石：** 每当方块从未充能变为充能时，`lit` 状态会翻转一次。**手动交互：** 当 `can_open_with_hand` 启用时，玩家可右键直接切换 `lit` 状态。","en":"**Toggleable Lamp Block** toggles its `lit` state between on and off. It can be switched by redstone, by hand, or both. By redstone: each rising edge of a neighbor signal flips the lamp between lit and unlit. By hand: right-click cycles the lamp on/off when `can_open_with_hand` is enabled."},
  "behavior.trapdoor_block": {"zh":"**活板门方块**是可开合的铰链面板。可通过玩家交互、红石或风弹切换状态。放置时活板门会自动检测周围红石信号与当前位置的水体状态——若被红石信号激活则变为开启状态，若放置在水中则含水。","en":"**Trapdoor Block** is a hinged panel that opens and closes. It can be toggled by hand, redstone, or wind charges. On placement, the trapdoor auto-detects redstone and water — it opens if powered and waterlogs if placed in water."},
  "behavior.vertical_crop_block": {"zh":"**垂直作物方块**会在随机刻中向上或向下生长，类似甘蔗或海带。在垂直方向上，只有最顶端的茎段会增加 `age` 值。每次随机刻触发时，若生长方向的方块为空且总高度未达上限，则增加 `age` 值。当 `age` 值积累至最大值时，会在顶端延伸出一个新茎段。","en":"**Vertical Crop Block** grows upward or downward on random ticks, like sugar cane or kelp. It accumulates an internal `age` and places a new block of the same type once it reaches the maximum. Growth only triggers when the space ahead (above for `up`, below for `down`) is air and fewer than `max_height` segments already exist."},
  "behavior.wall_torch_particle_block": {"zh":"**墙上火把粒子方块**按固定间隔生成粒子效果，类似原版的墙上的火把。`facing` 属性用于确定粒子相对于方块的位置，并随方块朝向自动旋转。","en":"**Wall Torch Particle Block** spawns particle effects at a fixed interval, like a wall torch emitting smoke. The `facing` direction is used to orient particle positions — particles rotate with the block."},
  "behavior.simple_storage_furniture": {"zh":"**简单存储家具**为家具添加一个类似箱子的功能。右键打开容器，玩家可以放入或者取出物品。","en":"**Simple Storage Furniture** adds a chest-like inventory to a piece of furniture. Right-click to open a GUI where players can place and take items."},
  "behavior.glowing_furniture": {"zh":"**发光家具**允许家具在指定位置放置光源方块，从而发出方块光照。注意：此行为**需要**在 `config.yml` 中启用 `furniture.light-system.enable: true`，且使用该功能很可能导致世界上残留光源方块。","en":"**Glowing Furniture** makes furniture emit light by placing `minecraft:light` blocks at configured positions relative to the furniture origin. The light blocks appear on placement, move with the furniture, and vanish on break. This behavior **requires** `furniture.light-system.enable: true` in `config.yml`."},
  "behavior.display_item_furniture": {"zh":"**物品展示家具**允许玩家右键家具将物品放入展示或取回手上。每个变体可以定义自己的展示位置，多个行为可以组合实现多槽位展示。","en":"**Display Item Furniture** lets players right-click to place or take an item displayed on a piece of furniture. Each variant can define its own display position, and multiple behaviors can be combined for multi-slot displays."},
  "type": {"zh":"战利品源类型：block_break / entity_death / fishing / piglin_barter / container / archaeology / entity_drop / harvest / shear_block / vault / advancement。","en":"The loot source type: block_break / entity_death / fishing / piglin_barter / container / archaeology / entity_drop / harvest / shear_block / vault / advancement."},
  "layers": {"zh":"键为层类型（预设模型类型）：humanoid / humanoid_leggings / wings / wolf_body / ... / happy_ghast_body / camel_husk_saddle / nautilus_body。值可为纹理路径字符串或详细配置块，也可用列表组合多个纹理。","en":"Key is the layer type (preset model type): humanoid, humanoid_leggings, wings, wolf_body, ..., happy_ghast_body, camel_husk_saddle, nautilus_body. The value can be a texture path string, a detailed config block, or a list combining multiple textures."},
  "layers.<key>": {"zh":"值可为纹理路径字符串（如 minecraft:entity/equipment/humanoid/topaz），也可通过配置块形式设置额外选项，或使用列表组合多个纹理。","en":"Value can be a texture path string (e.g. minecraft:entity/equipment/humanoid/topaz), a config block for some extra options, or a list to combine multiple textures."},
  "layers.<key>.texture": {"zh":"纹理路径，如 §a`\"minecraft:leather\"`§r。也可作为列表项组合多个纹理（如部分可染色的盔甲）。§6配合 `dyeable` 配置可实现染色效果。","en":"Texture path, e.g. §a`\"minecraft:leather\"`§r. Can also be a list entry to combine multiple textures (e.g. partially dyeable armor). §6Combine with `dyeable` for dyeing."},
  "layers.<key>.dyeable": {"zh":"可染色配置块。存在此配置时该层纹理可被染色（如皮革盔甲）。子选项: §bcolor_when_undyed§r（未染色时的颜色）。\n示例: §a`dyeable:\n  color_when_undyed: -6265536`§r","en":"Dyeable config block. When present, the layer texture can be dyed (e.g. leather armor). Sub-option: §bcolor_when_undyed§r (color when undyed).\nExample: §a`dyeable:\n  color_when_undyed: -6265536`§r"},
  "layers.<key>.dyeable.color_when_undyed": {"zh":"未染色时的颜色，**十进制颜色值**（如 §a`-6265536`§r 为文档示例的皮革原色）。不染色时显示此颜色，染色后由染料覆盖。","en":"The color when the texture is not dyed, as a **decimal color value** (§a`-6265536`§r is the leather color in the docs example). Shown when undyed; overridden by dye colors."},
  "layers.<key>.use_player_texture": {"zh":"是否使用玩家的皮肤纹理（适用于鞘翅等需要玩家纹理的层）。\n示例: §a`use_player_texture: false`§r","en":"Whether to use the player's skin texture (for elytra and other player-texture layers).\nExample: §a`use_player_texture: false`§r"},
  "asset_id": {"zh":"必填参数（装备资源命名空间ID）。","en":"Required Argument (the equipment asset id)."},
  "client_bound_model": {"zh":"可选参数。默认为 config.yml 中的全局 client_bound_model 选项。","en":"Optional Argument. Defaults to the global client_bound_model option in config.yml."},
  "slot": {"zh":"可选参数（1.21.2 及以上）。这些选项需要指定 slot 才能生效：head / chest / legs / feet / body（动物盔甲）/ saddle。","en":"Optional Argument on 1.21.2 and above. Option 'slot' is required for these options to work: head / chest / legs / feet / body (animal armor) / saddle."},
  "camera_overlay": {"zh":"当此项存在且物品被玩家穿戴时，玩家第一人称视角将渲染指定的纹理遮罩。此处的目录指的是 assets/<命名空间>/textures/<路径>。","en":"The resource location of the overlay texture to use when equipped. The directory this refers to is assets/<namespace>/textures/<id>."},
  "dispensable": {"zh":"是否可以使用发射器使生物穿戴此物品。如果物品本身有特殊的发射器行为则此项无效。","en":"Whether the item can be dispensed by using a dispenser."},
  "damage_on_hurt": {"zh":"生物在受到会影响损害盔甲的伤害时此物品是否会受损而减少耐久。","en":"Whether this item is damaged when the wearing entity is damaged."},
  "swappable": {"zh":"物品是否可以直接使用穿戴。","en":"Whether the item can be equipped into the relevant slot by right-clicking."},
  "equip_on_interact": {"zh":"对生物使用此物品时，是否可以让被交互的生物在允许的空槽位上穿戴此物品（1.21.5+）。","en":"Whether this item can be equipped onto a target mob by pressing use on it (1.21.5+)."},
  "file": {"zh":"PNG 文件路径。`.png` 后缀会自动补全。必填。\n示例: §a`file: minecraft:font/image/emojis.png`§r","en":"Path to the PNG. `.png` extension is auto-appended if missing. Required.\nExample: §a`file: minecraft:font/image/emojis.png`§r"},
  "height": {"zh":"图像的每个字形的高度（像素）。不填则自动读取 PNG 实际高度。别名: `scale`、`scale_ratio`。§6注意: height 必须 ≥ ascent，且单个字形不得超过 256×256 像素（指每个格子，不是整张 PNG）。§r\n（画的配置中 `height` 为画的高度，范围 1~16，默认 1。）","en":"Glyph height in pixels. If omitted, the plugin reads the PNG height. Aliases: `scale`, `scale_ratio`.§6Note: height must be ≥ ascent; a glyph must not exceed 256×256 px per cell.§r\n(In painting configs, `height` is the painting height in blocks, 1–16, default 1.)"},
  "ascent": {"zh":"基线偏移量。增大该值会让图像在屏幕上往上移。\n默认值: §eheight - 1§r。别名: `y_position`。§6height 必须 ≥ ascent（Minecraft 硬性限制）。§r","en":"Baseline offset. Increasing this moves the image upward on screen.\nDefault: §eheight - 1§r. Alias: `y_position`.§6height must be ≥ ascent (enforced by Minecraft).§r"},
  "font": {"zh":"图像所属的字体。\n默认值: §e命名空间:default§r。聊天中尽量使用自定义字体（而非 `minecraft:default`）更安全——玩家只能输入 `minecraft:default` 中的字符，无法直接输入自定义字体的字形。","en":"Which font this image belongs to.\nDefault: §enamespace:default§r. Custom fonts (anything other than `minecraft:default`) are safer in chat — players can only type characters in `minecraft:default`, so they cannot directly input glyphs from your custom fonts."},
  "char": {"zh":"映射到此图像的码位。不填时插件会自动挑选一个空闲码位——推荐这样做，完全没有冲突风险。\n可填: 固定码位（§a`char: '\\ub000'`§r）、数字值（§a`char: 1000`§r）或直接写字（§a`char: '我'`§r）。别名: `chars`、`unicode`。","en":"The codepoint mapped to this image. If omitted, the plugin picks a free codepoint — the recommended approach, no risk of conflicts.\nAccepted forms: fixed codepoint (§a`char: '\\ub000'`§r), numeric value (§a`char: 1000`§r), or a direct character (§a`char: '我'`§r). Aliases: `chars`, `unicode`."},
  "chars": {"zh":"精灵图逐行定义：每行是一个字符串，行内字符从左到右依次对应格子。所有行的字符数必须一致。\n示例: §a`chars:\\n  - '\\ub000\\ub001\\ub002'\\n  - '\\ub003\\ub004\\ub005'`§r","en":"Each string is one row; characters within a row map left-to-right. All rows must have the same length.\nExample: §a`chars:\\n  - '\\ub000\\ub001\\ub002'\\n  - '\\ub003\\ub004\\ub005'`§r"},
  "grid_size": {"zh":"不想手动管字符分配的话，直接用 `grid_size` 让插件全自动处理。\n示例: §a`grid_size: 2,3`§r（2 行 × 3 列 → 共 6 格）。","en":"Let the plugin handle character allocation for you.\nExample: §a`grid_size: 2,3`§r (2 rows × 3 columns → 6 cells)."},
  "ref": {"zh":"给精灵图中的某个格子起名字。短格式 ref: default:emojis:0:1；引用不需要 file、height 或 font——它只是指向已有位图的某个格子。","en":"Give a meaningful name to a specific cell from a sprite sheet. Short form ref: default:emojis:0:1; a reference has no file, height, or font of its own — it points to an existing bitmap cell."},
  "row": {"zh":"长格式引用：`ref` 指定精灵图，`row` 指定行（从 0 开始）。\n示例: §a`ref: default:emojis\\nrow: 0\\ncolumn: 2`§r","en":"Long form reference: `ref` names the sprite sheet, `row` picks the row (0-based).\nExample: §a`ref: default:emojis\\nrow: 0\\ncolumn: 2`§r"},
  "column": {"zh":"长格式引用：`ref` 指定精灵图，`column` 指定列（从 0 开始）。\n示例: §a`ref: default:emojis\\nrow: 0\\ncolumn: 2`§r","en":"Long form reference: `ref` names the sprite sheet, `column` picks the column (0-based).\nExample: §a`ref: default:emojis\\nrow: 0\\ncolumn: 2`§r"},
  "name": {"zh":"分类图标的显示名称。支持 MiniMessage。\n默认值: §e分类 ID§r。\n示例: §a`name: \"<!i><green>棕榈树</green>\"`§r","en":"Display name of the category icon. Supports MiniMessage.\nDefault: §ethe category ID§r.\nExample: §a`name: \"<!i><green>Palm Tree</green>\"`§r"},
  "lore": {"zh":"图标上显示的描述行，支持 MiniMessage 与 `l10n` 本地化标签。\n默认值: §e空§r。\n示例: §a`lore: []`§r。","en":"Lore lines shown on the icon. Supports MiniMessage and `l10n` localization tags.\nDefault: §eempty§r.\nExample: §a`lore: []`§r."},
  "icon": {"zh":"分类图标显示的物品，必须是已注册的物品。\n默认值: §e`minecraft:stone`§r。\n示例: §a`icon: default:palm_log`§r。","en":"The item shown as the category icon. Must be a registered item.\nDefault: §e`minecraft:stone`§r.\nExample: §a`icon: default:palm_log`§r."},
  "priority": {"zh":"主菜单中的显示顺序，数值越小越靠前。\n默认值: §e0§r。当两个分类的 `priority` 相同时，按 ID 字母顺序排列。","en":"Display order on the main menu. Lower values appear first.\nDefault: §e0§r. When two categories share the same priority, they are sorted alphabetically by ID."},
  "hidden": {"zh":"为 `true` 时不显示在主菜单——用于子分类。子分类需在父分类的 `list` 中以 `#` 前缀引用（如 §a`#default:palm_tree`§r）。\n默认值: §efalse§r。","en":"If `true`, the category doesn't appear on the main menu — useful for sub-categories. Sub-categories are referenced from the parent's `list` with a `#` prefix (e.g. §a`#default:palm_tree`§r).\nDefault: §efalse§r."},
  "list": {"zh":"有序的物品 ID 和子分类引用列表。子分类引用以 # 为前缀（如 #default:palm_tree），点击后打开该分类的页面；引用的子分类或物品不存在时，该格子显示红色屏障方块并以缺失的 ID 作为名称。","en":"Ordered list of item IDs and sub-category references. Sub-category references are prefixed with #, clicking opens that category's page; if a referenced sub-category or item doesn't exist, the slot displays a red barrier with the missing ID as its name."},
  "all_items": {"zh":"为 `true` 时自动包含所有已注册的自定义物品。\n默认值: §efalse§r。\n示例: §a`all_items: true`§r。","en":"If `true`, automatically includes all registered custom items.\nDefault: §efalse§r.\nExample: §a`all_items: true`§r."},
  "replace": {"zh":"是否替换同名的现有声音事件。文档示例中为 `false`。插件使用与 Minecraft Wiki 相同的配置项名称，各参数对应的效果可查阅 Minecraft Wiki。","en":"Whether to replace an existing sound event with the same name. Shown as `false` in the docs example. CraftEngine uses the same configuration option names as described in the Minecraft Wiki, which explains the effect corresponding to each parameter."},
  "subtitle": {"zh":"声音事件的字幕翻译键，播放时客户端会显示该字幕。\n示例: §a`subtitle: subtitles.custom_block.place`§r","en":"The subtitle translation key for the sound event, shown on the client when it plays.\nExample: §a`subtitle: subtitles.custom_block.place`§r"},
  "sounds": {"zh":"真正的音效文件位于 sounds 列表中。可填路径字符串（如 §a`block/custom_block_1`§r），也可填详细配置（`name` / `volume` / `weight` / `stream` / `attenuation_distance` / `preload` / `type`）。","en":"The actual sounds are located under the sounds list. A path string (e.g. §a`block/custom_block_1`§r) or a detailed config (`name` / `volume` / `weight` / `stream` / `attenuation_distance` / `preload` / `type`)."},
  "sounds.<key>": {"zh":"每个声音条目可写成路径字符串，或含 `name`（文件路径）、`volume`（音量）、`weight`（权重）、`stream`（是否流式播放）、`attenuation_distance`（衰减距离）、`preload`（是否预加载）、`type`（`file` 或 `event`）的配置块。插件使用与 Minecraft Wiki 相同的配置项名称。","en":"Each sound entry can be a path string, or a config block with `name` (file path), `volume`, `weight`, `stream`, `attenuation_distance`, `preload` and `type` (`file` or `event`). CraftEngine uses the same configuration option names as the Minecraft Wiki."},
  "sounds.<key>.name": {"zh":"音效文件路径（不含扩展名）。\n示例: §a`name: \"ambient/custom_biome_1\"`§r。可搭配 `type: file`（默认）或 `type: event` 使用。","en":"The sound file path (without extension).\nExample: §a`name: \"ambient/custom_biome_1\"`§r. Works with `type: file` (default) or `type: event`."},
  "sounds.<key>.volume": {"zh":"音量大小（0~1 范围）。\n示例: §a`volume: 0.4`§r。\n默认值: §e1.0§r（sounds.json 规范）。多个声音条目可设置不同音量。","en":"The volume (range 0–1).\nExample: §a`volume: 0.4`§r.\nDefault: §e1.0§r per the sounds.json spec. Different entries can have different volumes."},
  "sounds.<key>.weight": {"zh":"该声音被选中的权重（概率），权重越大越常被播放。\n示例: §a`weight: 3`§r。\n默认值: §e1§r（sounds.json 规范）。","en":"The weight of the sound (probability of being picked); higher weight = played more often.\nExample: §a`weight: 3`§r.\nDefault: §e1§r per the sounds.json spec."},
  "keywords": {"zh":"一个或多个**触发词**。玩家输入任意一个即被替换。必填。\n示例: §a`keywords:\n  - ':smiley:'\n  - ':)'`§r","en":"One or more **trigger strings**. When a player types one, it gets replaced. Required.\nExample: §a`keywords:\n  - ':smiley:'\n  - ':)'`§r"},
  "content": {"zh":"替换关键词的 MiniMessage 文本。必填。内容中有两个特殊参数：<arg:emoji>（表情的图片字形）与 <arg:keyword>（触发该表情的第一个关键词）。复杂内容可以拆成多行，插件会自动拼接。","en":"The MiniMessage text that replaces the keyword. Required. Two special parameters: <arg:emoji> — the image glyph itself; <arg:keyword> — the first keyword that triggered this emoji. For complex content, split into multiple lines — the plugin auto-joins them."},
  "image": {"zh":"指向图像某个格子的引用，格式为 `命名空间:id:行:列`。单格图像直接写 `命名空间:id` 即可。可选。\n示例: §a`image: default:emojis:0:0`§r","en":"A reference to an image cell in `namespace:id:row:column` format. If your image has a single cell, `namespace:id` is enough. Optional.\nExample: §a`image: default:emojis:0:0`§r"},
  "permission": {"zh":"使用该表情所需的**权限节点**。可选；未配置则所有玩家可用。\n示例: §a`permission: emoji.vip`§r","en":"Permission node required to use this emoji. Optional; everyone can use it when unset.\nExample: §a`permission: emoji.vip`§r"},
  "chat_completion": {"zh":"关键词是否出现在客户端 Tab 补全提示中。（默认值: §etrue§r）\n示例: §a`chat_completion: true`§r","en":"Whether the keywords appear in client-side tab completion. (Default: §etrue§r)\nExample: §a`chat_completion: true`§r"},
  "template": {"zh":"引用模板。以 `templates` 作为 YAML 文件的根键定义模板，`namespace:template_id` 作为模板的唯一标识符，在后续调用时必须使用该完整名称。可设置为列表来组合多个模板。\n§6若两个模板存在相同配置项，下方的模板会覆盖上方配置；但当配置项为列表时，它们将合并为一个列表。§r\n示例: §a`template:\\n  - namespace:my_first_template\\n  - namespace:my_second_template`§r","en":"References a template; `namespace:template_id` is the unique identifier you must use. Set it as a list to combine multiple templates.\n§6Same settings: lower overwrites upper; lists merge into one.§r\nExample: §a`template:\\n  - namespace:my_first_template\\n  - namespace:my_second_template`§r"},
  "overrides": {"zh":"覆写会完全替换指定配置路径下的所有内容（包括列表和映射），不进行合并操作，直接整体替换。","en":"Overrides completely replace whatever's in the specified config path — including lists and maps. No merging, just a full swap."},
  "sound": {"zh":"音乐的声音事件 ID。\n示例: §a`sound: minecraft:music.credits`§r。如需自定义音效，请参考音效配置页。","en":"The sound event of the music.\nExample: §a`sound: minecraft:music.credits`§r. To customize sounds, see the sound configuration page."},
  "length": {"zh":"音乐时长（秒），浮点数。`sound` 指定声音事件。\n示例: §a`length: 100.0`§r（100 秒）。唱片机按此时长持续播放音乐。","en":"Music length in seconds.\nExample: §a`length: 100.0`§r. The jukebox plays the music for this duration."},
  "description": {"zh":"唱片描述文本，可填翻译键或普通文本。\n示例: §a`description: \"Credits\"`§r。显示在唱片物品的提示文本中。","en":"The description of the music disc.\nExample: §a`description: \"Credits\"`§r. Shown in the disc's tooltip."},
  "comparator_output": {"zh":"红石比较器输出强度（0~15）。\n示例: §a`comparator_output: 15`§r。唱片机被比较器检测时输出此强度。","en":"The redstone comparator output strength (0–15).\nExample: §a`comparator_output: 15`§r. The jukebox outputs this strength when detected by a comparator."},
  "range": {"zh":"音乐播放范围（方块），数字越大传播越远。\n示例: §a`range: 32`§r。玩家与唱片机距离超出该范围时听不到音乐。","en":"The playback range in blocks (larger = further reach).\nExample: §a`range: 32`§r. Players further than this from the jukebox won't hear the music."},
  "width": {"zh":"可选；画的宽度，以方块为单位。\n默认值: §e1§r；范围 1~16。\n示例: §a`width: 2`§r。配合 `height` 一起定义画的大小。","en":"Optional; the width of the painting in blocks.\nDefault: §e1§r; between 1 and 16.\nExample: §a`width: 2`§r."},
  "title": {"zh":"可选；画的标题。需要 1.21.2+；低版本固定翻译键 `painting.<命名空间>.<路径>.title`。\n示例: §a`title: <lang:painting.default.momi.title>`§r","en":"Optional; the title of the painting. Requires 1.21.2+; on older versions the translation key is fixed to `painting.<namespace>.<path>.title`.\nExample: §a`title: <lang:painting.default.momi.title>`§r"},
  "author": {"zh":"可选；画的作者。需要 1.21.2+；低版本固定翻译键 `painting.<命名空间>.<路径>.author`。\n示例: §a`author: <lang:painting.default.momi.author>`§r","en":"Optional; the author of the painting. Requires 1.21.2+; on older versions the translation key is fixed to `painting.<namespace>.<path>.author`.\nExample: §a`author: <lang:painting.default.momi.author>`§r"},
  "show_in_op_tab": {"zh":"可选；默认为 false；在 1.21-1.21.1 需要重启服务器才能生效；是否在管理员用品标签页显示，否则在工具与实用物品标签页显示。如需在随机画中生成请设置为 false。","en":"Optional; Default is false; On 1.21–1.21.1 a server restart is required for this to take effect; whether to show the painting in the Operator Utilities tab — if false, it appears in the Tools & Utilities tab instead. Set false to allow random paintings."},
  "globalVariable": {"zh":"全局变量写在 global_variables 节点下，每项都是键值对。Value 为要替换的 MiniMessage 内容，完全支持标签、颜色、图片和其他变量；变量支持索引参数 <arg:0>、<arg:1>，在调用处用冒号分隔传入。","en":"Global variables live under the global_variables section. Each entry is a key-value pair: the value is the MiniMessage content to substitute, fully supporting tags, colors, images, and other variables. Variables support indexed arguments (<arg:0>, <arg:1>) filled in at the call site."},
  "translation": {"zh":"i18n 与 l10n 共享同一套数据源——translations 配置节点。语言键遵循标准格式：en、zh_cn、ko_kr、fr_fr 等；找不到精确匹配时回退到仅语言变体（zh_cn → zh），最后回退到 en。","en":"i18n and l10n share the same data source — the translations config section. The locale key follows standard format: en, zh_cn, ko_kr, fr_fr, etc.; if no exact match exists, the plugin falls back to the language-only variant, then to en."},
  "lang": {"zh":"lang 系统将翻译直接写入资源包（assets/minecraft/lang/*.json），由 Minecraft 客户端原生渲染。语言格式必须匹配 Minecraft 资源包规范（en_us、zh_cn、ko_kr，不能写 en、zh）。使用 all 可应用到每一种语言；en_us 是 Minecraft 的默认回退语言，创建新键时务必配置。","en":"The lang system writes translations directly into the resource pack (assets/minecraft/lang/*.json), rendered natively by the client. The locale format must match Minecraft's resource pack convention (en_us, zh_cn, ko_kr, not en, zh). Use all to apply a translation to every language."},
  "target": {"zh":"可选；单个 id。其含义取决于类型：方块 id、实体 id、战利品表 id 或进度 id。如果省略，此战利品源将作用于该类型的所有对象。fishing 和 piglin_barter 不接受 target。不允许使用 minecraft:wheat[age=7] 这样的方块状态语法。","en":"Optional; a single id. Its meaning depends on the type: block id, entity id, loot table id or advancement id. If omitted, the source applies to every object of that type. fishing and piglin_barter do not accept a target. Block state syntax such as minecraft:wheat[age=7] is not allowed."},
  "targets": {"zh":"同 target，但为 id 列表。","en":"Same as target, but a list of ids."},
  "overwrite": {"zh":"可选，默认 none。从原版结果中移除的内容：items 移除原版掉落的物品；experience 移除原版掉落的经验；all 以上两者；none 不移除任何内容，你的战利品将追加到原版结果之后。","en":"Optional, default none. What to remove from the vanilla result: items — remove the vanilla dropped items; experience — remove the vanilla dropped experience; all — both of the above; none — remove nothing, your loot is appended."},
  "loot": {"zh":"要生成的战利品：可以是内联战利品表，也可以是另一张战利品表的 id。当该 id 不存在对应的 CraftEngine 战利品表时，会回退到同名的数据包战利品表，因此可以直接引用原版战利品表（如 minecraft:chests/simple_dungeon）。","en":"The loot to generate: either an inline loot table, or the id of another loot table. When no CraftEngine loot table with that id exists, it falls back to the datapack loot table with the same id, which allows referencing vanilla tables directly (e.g. minecraft:chests/simple_dungeon)."},
  "feature": {"zh":"即已配置地物。可以是引用其他已配置地物的字符串，也可以是直接定义地物的对象（type + config）。也可在 configured_features 键下单独定义再通过 ID 引用。","en":"The configured feature. It can be a string that references another configured feature, or an object that defines the configured feature directly. You can also define configured features separately under the configured_features key and reference them by ID."},
  "placement": {"zh":"即已放置地物部分。它控制地物如何、在哪里生成。","en":"The placed feature part. It controls how and where the feature is generated."},
  "world": {"zh":"精确的世界名称列表；仅在指定的世界中生成。","en":"List of exact world names; only generate in the listed worlds."},
  "dimension": {"zh":"维度注册键列表，如 minecraft:overworld；仅在指定的维度中生成。","en":"List of dimension registry keys, e.g. minecraft:overworld; only generate in the listed dimensions."},
  "dimension_type": {"zh":"维度类型注册键列表，如 minecraft:overworld、minecraft:the_end；仅在指定的维度类型中生成。","en":"List of dimension-type registry keys, e.g. minecraft:overworld, minecraft:the_end; only generate in the listed dimension types."},
  "biome": {"zh":"生物群系注册键列表，如 minecraft:beach；仅在指定的生物群系中生成。需要在 placement 中包含 minecraft:biome 放置修饰器。","en":"List of biome registry keys, e.g. minecraft:beach; only generate in the listed biomes. Requires the minecraft:biome placement modifier in placement."},
  "arguments": {"zh":"可在模板中使用 ${xxx} 定义参数（如 ${nutrition}），调用模板时用 arguments 部分来设定参数值。模板参数是按顺序应用的，刚定义的参数可以立即在后续参数中使用；支持默认值（${nutrition:-1}）与大小写修饰符（${arg^}、${arg^^}）。","en":"Define parameters in templates using ${xxx}, like ${nutrition}; then set the parameter values via the arguments section. Template parameters are applied sequentially — a parameter you just defined is immediately available for use in subsequent parameters."},
  "merges": {"zh":"合并功能会深度整合两个配置部分（包括所有列表），不遗漏任何内容。本质上，合并功能的工作原理几乎完全等同于使用多个模板。\n示例: §a`merges:\\n  data:\\n    food:\\n      can_always_eat: true`§r","en":"Merges deeply combines two config sections, including all lists — nothing gets left behind. Basically, merges function almost exactly like multiple templates.\nExample: §a`merges:\\n  data:\\n    food:\\n      can_always_eat: true`§r"},
  "config.forced-locale": {"zh":"i18n 使用的服务器语言。\n§e默认§r: 未设置时跟随 JVM 默认语言。\n§a示例§r（config.yml）:\n`forced-locale: zh_CN`\n用于强制本地化语言，与插件/服务端默认语言解耦。","en":"The server language used for i18n.\nDefault: falls back to the JVM default locale when unset.\n§aExample§r (config.yml):\n`forced-locale: en_US`\nForces the localization language, decoupled from the plugin/server default."},
  "config.resource-pack.duplicated-files-handler": {"zh":"资源包冲突解决器：当插件检测到冲突文件时，会搜索第一个符合条件（term）的解决方式（resolution），若无则向控制台发出警告。插件不支持着色器合并。","en":"The conflict resolver for resource packs: when conflicting files are detected, the plugin searches for the first solution that meets the conditions; if none is found, it issues a warning to the console. The plugin does not support the merging of shaders."},
  "config.resource-pack.generate-mod-assets": {"zh":"启用后自动生成与 CraftEngine Fabric 模组兼容的客户端资源。\n§a示例§r（config.yml）:\n`generate-mod-assets: true`\n配合 Axiom 模组使用：还需保证客户端 `server-side-blocks` 配置不小于服务端 `block.serverside-blocks`。","en":"When enabled, automatically generates client-side resources compatible with the CraftEngine Fabric mod.\n§aExample§r (config.yml):\n`generate-mod-assets: true`\nUsed with the Axiom mod: the client's `server-side-blocks` must be no less than the server's `block.serverside-blocks`."},
  "config.resource-pack.delivery.hosting": {"zh":"默认配置就是 self 模式，服务器自带 HTTP 分发功能，不需要额外设置。type: \"self\" 表示服务器自己开一个 HTTP 服务；ip: \"auto\" 和 port: \"auto\" 自动检测地址和端口。更改托管配置后运行 /ce reload all。","en":"The default config uses self mode — the server includes a built-in HTTP server, no extra setup needed. type: \"self\" starts a built-in HTTP server; ip: \"auto\" and port: \"auto\" detect your address automatically. After changing the host config, run /ce reload all."},
  "config.item.client-bound-model": {"zh":"付费版专属。将 CMD 和 item_model 保留在客户端，允许在不影响已有物品的情况下动态更新。默认 true。","en":"Premium. Keep CMD and item_model client-side, enabling dynamic updates without affecting existing items. Default true."},
  "config.item.always-use-item-model": {"zh":"即使 custom_model_data 存在也生成 item_model。默认 true，推荐。","en":"Generate item_model even when custom_model_data is present. Default true. Recommended."},
  "config.item.always-use-custom-model-data": {"zh":"即使仅面向 1.21.2+ 的资源包也强制分配 CMD。默认 false。","en":"Force CMD allocation even for 1.21.2+-only packs. Default false."},
  "config.item.always-generate-model-overrides": {"zh":"即使仅面向 1.21.4+ 的资源包也强制生成 legacy overrides（对基岩版转换器有用）。默认 false。","en":"Force legacy overrides even for 1.21.4+-only packs (useful for Bedrock converters). Default false."},
  "config.item.custom-model-data-starting-value.default": {"zh":"自动分配的第一个 CMD 编号。默认 10000。","en":"First auto-allocated CMD number. Default 10000."},
  "config.item.custom-model-data-starting-value.overrides": {"zh":"按材质覆盖起始值，如 paper: 20000。","en":"Per-material override, e.g. paper: 20000."},
  "config.item.default-material": {"zh":"material 的默认值（config.yml 中可配置），默认 nether_brick。","en":"The default material, configurable in config.yml (defaults to nether_brick)."},
  "config.item.update-triggers": {"zh":"更新器仅在特定事件中激活，默认全部关闭。每个触发器都会带来性能开销——插件需要在每次事件中检查所有受影响的物品，只开启必要的。","en":"The updater only activates during specific events, all disabled by default. Each trigger adds overhead — the plugin checks every affected item on every event. Enable sparingly."},
  "config.item.update-triggers.click-in-inventory": {"zh":"点击物品栏时触发更新。§e默认 false§r（创造模式无效）。\n§6注意§r: 每个触发器都会带来性能开销，只开启必要的。","en":"Update triggers on clicking inside the inventory. Default: false (not in creative mode)."},
  "config.item.update-triggers.drop": {"zh":"丢弃物品时触发更新。§e默认 false§r。\n§6注意§r: 每个触发器都会带来性能开销——插件需在每次事件中检查所有受影响物品，只开启必要的。","en":"Update triggers on dropping an item. Default: false.\n§6Note§r: every trigger adds overhead — the plugin checks every affected item on each event. Enable sparingly."},
  "config.item.update-triggers.pick-up": {"zh":"拾取物品时触发更新。§e默认 false§r。\n§6注意§r: 每个触发器都会带来性能开销——插件需在每次事件中检查所有受影响物品，只开启必要的。","en":"Update triggers on picking up an item. Default: false.\n§6Note§r: every trigger adds overhead — the plugin checks every affected item on each event. Enable sparingly."},
  "config.block.serverside-blocks": {"zh":"服务端方块数量上限：自定义方块 ID 不能超出此值。客户端的 server-side-blocks 配置数量不小于服务端的此值。","en":"The serverside-blocks limit in config.yml: custom block IDs cannot exceed it. The client's server-side-blocks should be no less than the server's block.serverside-blocks."},
  "config.loot.entity-sources": {"zh":"要支持的插件列表（如 MythicMobs）。然后使用该插件提供的 id（如 mythicmobs:skeletal_knight）作为 entity_death 的 target。","en":"List the plugin under loot.entity-sources in config.yml (e.g. MythicMobs) and use the id it provides (e.g. mythicmobs:skeletal_knight) as the entity_death target."},
  "config.emoji.contexts": {"zh":"表情替换在哪些场景生效，均为布尔开关:\n§b`chat`§r - 聊天\n§b`book`§r - 书本\n§b`anvil`§r - 铁砧\n§b`sign`§r - 告示牌\n§a示例§r:\n`contexts:`\n`  chat: true`\n`  book: true`","en":"Where emoji replacement runs, all booleans:\n§b`chat`§r - chat\n§b`book`§r - books\n§b`anvil`§r - anvil\n§b`sign`§r - signs\n§aExample§r:\n`contexts:`\n`  chat: true`\n`  book: true`"},
  "config.emoji.max-emojis-per-parse": {"zh":"每条消息最多替换多少个表情，防止刷屏卡顿（文档示例 16）。","en":"Caps the number of emoji replacements per message to prevent lag (16 in the docs)."},
  "config.image.illegal-characters-filter": {"zh":"阻止玩家直接输入原始码位字符，均为布尔开关: §b`anvil`、`book`、`chat`、`command`、`sign`§r。\n§6提示§r: 自定义字体天然安全（玩家只能输入 `minecraft:default` 字符）；仅在必须使用 `minecraft:default` 时保留启用。\n§a示例§r:\n`illegal-characters-filter:`\n`  chat: true`","en":"Blocks players from typing raw codepoint characters directly; all booleans: §b`anvil`, `book`, `chat`, `command`, `sign`§r.\n§6Tip§r: custom fonts are inherently safe (players can only type `minecraft:default` characters); keep it enabled only when `minecraft:default` is required.\n§aExample§r:\n`illegal-characters-filter:`\n`  chat: true`"},
  "config.image.codepoint-starting-value": {"zh":"自动分配码位的起始值，可按字体分别设置。\n§a示例§r:\n`codepoint-starting-value:`\n`  default: 19968`\n`  overrides:`\n`    minecraft:default: 57344`","en":"Starting codepoint for auto-assignment, per font.\n§aExample§r:\n`codepoint-starting-value:`\n`  default: 19968`\n`  overrides:`\n`    minecraft:default: 57344`"},
  "config.image.offset-characters": {"zh":"定义 <shift:xxx> 定位使用的 Unicode 字符，键为偏移量（-256 到 +256），值为字符。除非你完全理解 Minecraft 字形度量机制，否则不要修改，错误的值会破坏文本布局。","en":"Defines the Unicode chars used by <shift:xxx>; key = offset (-256 to +256), value = char. Do not modify unless you understand Minecraft's glyph metrics — wrong values corrupt text layout."},
  "config.network.intercept-packets": {"zh":"启用后可在网络包层面拦截并替换 <image> 等标签，供不支持 MiniMessage 的插件使用。每个拦截器都会给 Netty 线程增加负担，关闭不需要的通道可以优化 Netty 性能。","en":"CraftEngine can intercept and replace tags at the network level for plugins without MiniMessage support. Each interceptor adds work to the Netty thread — disable any you don't need to optimize Netty performance."},
  "config.recipe.ingredient-sources": {"zh":"与其他插件兼容：将支持的插件添加到 config.yml 中的此列表（如 MythicMobs），即可用其物品作为配方原料。","en":"Compatibility with other plugins: add the supported plugins to this list in config.yml (e.g. MythicMobs) so their items can be used as recipe ingredients."},
  "condition.any_of": {"zh":"满足**任意一个**条件即可。\n参数:\n§b`terms`§r - 必填；条件列表，逐条匹配，任一通过即整体通过\n§a示例§r:\n`type: any_of`\n`terms:`\n`  - type: permission`\n`    permission: \"group.admin\"`\n`  - type: has_item`","en":"Satisfy **any one** of the conditions.\nParameters:\n§b`terms`§r - required; list of conditions; passes if any single one matches\n§aExample§r:\n`type: any_of`\n`terms:`\n`  - type: permission`\n`    permission: \"group.admin\"`\n`  - type: has_item`"},
  "condition.all_of": {"zh":"**所有**条件都必须满足。\n参数:\n§b`terms`§r - 必填；条件列表，全部通过才整体通过\n§a示例§r:\n`type: all_of`\n`terms:`\n`  - type: has_player`\n`  - type: permission`\n`    permission: \"group.admin\"`","en":"**All** conditions must be satisfied.\nParameters:\n§b`terms`§r - required; list of conditions; passes only when every condition passes\n§aExample§r:\n`type: all_of`\n`terms:`\n`  - type: has_player`\n`  - type: permission`\n`    permission: \"group.admin\"`"},
  "condition.inverted": {"zh":"对当前条件的结果值**取反**。\n参数:\n§b`term`§r - 必填；单个条件对象\n§a示例§r:\n`type: inverted`\n`term:`\n`  type: permission`\n`  permission: \"group.admin\"`\n§6提示§r: 也可在类型前加 `!` 取反，如 `type: \"!permission\"`。","en":"**Negates** the result of the current condition.\nParameters:\n§b`term`§r - required; a single condition object\n§aExample§r:\n`type: inverted`\n`term:`\n`  type: permission`\n`  permission: \"group.admin\"`\n§6Tip§r: you can also prefix the type with `!`, e.g. `type: \"!permission\"`."},
  "condition.falling_block": {"zh":"检测掉落物是否由**下落的方块**掉落（如沙子、混凝土粉末）。无参数。\n§a示例§r:\n`type: falling_block`\n常用于方块战利品表，区分\"方块自然下落\"与\"被挖掘\"两种掉落场景。","en":"Checks whether the drop was caused by a **falling block** (sand, concrete powder, etc.). No parameters.\n§aExample§r:\n`type: falling_block`\nCommonly used in block loot tables to tell apart drops from falling blocks vs. mined blocks."},
  "condition.survives_explosion": {"zh":"以 **1/爆炸半径** 的概率返回成功（模拟爆炸后物品是否存活）。需要上下文提供参数进行检测，若未提供则总是通过。\n§a示例§r:\n`type: survives_explosion`\n常用于方块战利品表，配合 §bexplosion_decay§r 模拟原版爆炸衰减。","en":"Succeeds with a probability of **1/explosion radius** (whether the item survives the explosion). Requires context parameters for the check; without them it always passes.\n§aExample§r:\n`type: survives_explosion`\nCommonly used in block loot tables together with `explosion_decay` to mimic vanilla explosion decay."},
  "condition.has_item": {"zh":"检查是否有手持物品。无参数。\n§a示例§r:\n`type: has_item`\n配合 §bmatch_item§r 可进一步判断具体是哪个物品。","en":"Checks if there is any item in hand. No parameters.\n§aExample§r:\n`type: has_item`\nCombine with `match_item` to also check which item it is."},
  "condition.match_item": {"zh":"检查手持物品是否匹配。\n参数:\n§b`id`§r - 必填；物品 ID，可为单个字符串或字符串列表\n§b`regex`§r - §e默认 false§r；是否使用正则匹配\n§a示例§r:\n`type: match_item`\n`id: \"minecraft:iron_pickaxe\"`\n`regex: false`\n列表写法: `id: [\"minecraft:iron_pickaxe\", \"minecraft:stone_pickaxe\"]`","en":"Matches the item in hand.\nParameters:\n§b`id`§r - required; item ID, either a single string or a list of strings\n§b`regex`§r - default `false`; whether to use regex matching\n§aExample§r:\n`type: match_item`\n`id: \"minecraft:iron_pickaxe\"`\n`regex: false`\nList form: `id: [\"minecraft:iron_pickaxe\", \"minecraft:stone_pickaxe\"]`"},
  "condition.match_block_property": {"zh":"检查方块的**方块状态**是否匹配。\n参数:\n§b`properties`§r - 必填；键值对，键为方块属性名，值为期望值\n§a示例§r:\n`type: match_block_property`\n`properties:`\n`  age: 3`","en":"Matches the **block state** of a block.\nParameters:\n§b`properties`§r - required; key-value map of block property name to expected value\n§aExample§r:\n`type: match_block_property`\n`properties:`\n`  age: 3`"},
  "condition.match_block": {"zh":"匹配方块类型。\n参数:\n§b`x`/`y`/`z`§r - 必填；检测坐标，常用 §e`<arg:position.x>`§r 等占位符\n§b`id`§r - 必填；方块 ID\n§b`regex`§r - §e默认 false§r；是否正则匹配\n§a示例§r:\n`type: match_block`\n`x: <arg:position.x>`\n`y: <arg:position.y>`\n`z: <arg:position.z>`\n`id: minecraft:stone`","en":"Matches the block type.\nParameters:\n§b`x`/`y`/`z`§r - required; position to check, usually placeholders like `<arg:position.x>`\n§b`id`§r - required; block ID\n§b`regex`§r - default `false`; whether to use regex matching\n§aExample§r:\n`type: match_block`\n`x: <arg:position.x>`\n`y: <arg:position.y>`\n`z: <arg:position.z>`\n`id: minecraft:stone`"},
  "condition.match_entity": {"zh":"匹配实体类型。\n参数:\n§b`id`§r - 必填；实体 ID（如 `minecraft:enderman`）\n§b`regex`§r - §e默认 false§r；是否正则匹配\n§a示例§r:\n`type: match_entity`\n`id: minecraft:enderman`","en":"Matches the entity type.\nParameters:\n§b`id`§r - required; entity ID (e.g. `minecraft:enderman`)\n§b`regex`§r - default `false`; whether to use regex matching\n§aExample§r:\n`type: match_entity`\n`id: minecraft:enderman`"},
  "condition.match_furniture_variant": {"zh":"匹配家具变体。\n参数:\n§b`variants`§r - 必填；变体名列表\n§a示例§r:\n`type: match_furniture_variant`\n`variants:`\n`  - wall`","en":"Matches the furniture variant.\nParameters:\n§b`variants`§r - required; list of variant names\n§aExample§r:\n`type: match_furniture_variant`\n`variants:`\n`  - wall`"},
  "condition.enchantment": {"zh":"检测手中物品的魔咒等级。\n参数:\n§b`predicate`§r - 必填；魔咒谓词，支持运算符 §e`>`、`>=`、`=`、`<`、`<=`§r\n§a示例§r:\n`type: enchantment`\n`predicate: minecraft:silk_touch>=1`","en":"Detects the enchantments on the item in hand.\nParameters:\n§b`predicate`§r - required; enchantment predicate, operators `>`, `>=`, `=`, `<`, `<=` supported\n§aExample§r:\n`type: enchantment`\n`predicate: minecraft:silk_touch>=1`"},
  "condition.table_bonus": {"zh":"以魔咒等级为索引，从概率列表中挑选通过。\n参数:\n§b`enchantment`§r - 必填；魔咒 ID\n§b`chances`§r - 必填；概率列表，数组下标对应魔咒等级\n§a示例§r（幸运 III）:\n`type: table_bonus`\n`enchantment: minecraft:fortune`\n`chances: [0.1, 0.5, 0.8, 1]`","en":"Picks a success probability from a list, indexed by the enchantment level.\nParameters:\n§b`enchantment`§r - required; enchantment ID\n§b`chances`§r - required; list of probabilities, array index = enchantment level\n§aExample§r (Fortune III):\n`type: table_bonus`\n`enchantment: minecraft:fortune`\n`chances: [0.1, 0.5, 0.8, 1]`"},
  "condition.permission": {"zh":"检查玩家是否拥有权限。\n参数:\n§b`permission`§r - 必填；权限节点\n§a示例§r:\n`type: permission`\n`permission: \"craftengine.admin\"`","en":"Checks if the player has the permission.\nParameters:\n§b`permission`§r - required; permission node\n§aExample§r:\n`type: permission`\n`permission: \"craftengine.admin\"`"},
  "condition.expression": {"zh":"检查表达式是否返回 §e`true`§r。\n参数:\n§b`expression`§r - 必填；EvalEx 表达式（语法见 https://ezylang.github.io/EvalEx/references/references.html），支持 PlaceholderAPI 占位符\n§a示例§r:\n`type: expression`\n`expression: \"<papi:farming_level> >= 10\"`","en":"Checks if the expression returns `true`.\nParameters:\n§b`expression`§r - required; EvalEx expression (syntax: https://ezylang.github.io/EvalEx/references/references.html), PlaceholderAPI placeholders supported\n§aExample§r:\n`type: expression`\n`expression: \"<papi:farming_level> >= 10\"`"},
  "condition.string_equals": {"zh":"判断两个值是否**相等**（字符串比较）。\n参数:\n§b`value1`§r - 必填；值 1\n§b`value2`§r - 必填；值 2\n§a示例§r:\n`type: string_equals`\n`value1: \"<arg:player.name>\"`\n`value2: \"Player_A\"`","en":"Determines if the two values are **equal** (string comparison).\nParameters:\n§b`value1`§r - required; first value\n§b`value2`§r - required; second value\n§aExample§r:\n`type: string_equals`\n`value1: \"<arg:player.name>\"`\n`value2: \"Player_A\"`"},
  "condition.string_contains": {"zh":"判断 value1 是否**包含** value2。\n参数:\n§b`value1`§r - 必填；被检查的值\n§b`value2`§r - 必填；要包含的子串\n§a示例§r:\n`type: string_contains`\n`value1: \"<arg:player.name>\"`\n`value2: \"A\"`","en":"Determines if value1 **contains** value2.\nParameters:\n§b`value1`§r - required; the value to check\n§b`value2`§r - required; the substring to look for\n§aExample§r:\n`type: string_contains`\n`value1: \"<arg:player.name>\"`\n`value2: \"A\"`"},
  "condition.regex": {"zh":"判断 value 是否符合指定**正则表达式**。\n参数:\n§b`value`§r - 必填；被检查的值\n§b`regex`§r - 必填；正则表达式\n§a示例§r:\n`type: regex`\n`value: \"<arg:player.name>\"`\n`regex: \"[a-zA-Z]\"`","en":"Determines if value matches the given **regex pattern**.\nParameters:\n§b`value`§r - required; the value to check\n§b`regex`§r - required; the regex pattern\n§aExample§r:\n`type: regex`\n`value: \"<arg:player.name>\"`\n`regex: \"[a-zA-Z]\"`"},
  "condition.is_null": {"zh":"检查参数是否为空。\n参数:\n§b`argument`§r - 必填；要检查的参数（如 `player.main_hand_item`）\n§a示例§r:\n`type: is_null`\n`argument: \"player.main_hand_item\"`","en":"Checks if the argument is null.\nParameters:\n§b`argument`§r - required; the argument to check (e.g. `player.main_hand_item`)\n§aExample§r:\n`type: is_null`\n`argument: \"player.main_hand_item\"`"},
  "condition.hand": {"zh":"检查交互手。\n参数:\n§b`hand`§r - 必填；枚举 §e`main_hand`§r / §e`off_hand`§r\n§a示例§r:\n`type: hand`\n`hand: main_hand`","en":"Checks the interaction hand.\nParameters:\n§b`hand`§r - required; enum `main_hand` / `off_hand`\n§aExample§r:\n`type: hand`\n`hand: main_hand`"},
  "condition.on_cooldown": {"zh":"检查玩家是否处于冷却（冷却由 §bset_cooldown§r 函数设置）。\n参数:\n§b`id`§r - 必填；冷却 ID（与 set_cooldown 的 id 一致）\n§a示例§r:\n`type: on_cooldown`\n`id: my_cooldown_id`\n§6提示§r: 加 `!` 取反（`!on_cooldown`）可实现\"不在冷却时才执行\"。","en":"Checks if the player is on cooldown (set with the `set_cooldown` function).\nParameters:\n§b`id`§r - required; cooldown ID (must match the `id` of `set_cooldown`)\n§aExample§r:\n`type: on_cooldown`\n`id: my_cooldown_id`\n§6Tip§r: prefix with `!` (`!on_cooldown`) to run only when NOT on cooldown."},
  "condition.worldguard:region": {"zh":"检测当前上下文位置是否位于 WorldGuard 区域内。\n参数:\n§b`mode`§r - 必填；§e`1`§r = 区域并集（任一区域即可），§e`2`§r = 区域交集（所有区域）\n§b`regions`§r - 必填；区域名列表\n§a示例§r:\n`type: worldguard:region`\n`mode: 1`\n`regions: [A, B]`","en":"Checks whether the current context location is within a WorldGuard region.\nParameters:\n§b`mode`§r - required; `1` = union of regions (any), `2` = intersection of regions (all)\n§b`regions`§r - required; list of region names\n§aExample§r:\n`type: worldguard:region`\n`mode: 1`\n`regions: [A, B]`"},
  "condition.distance": {"zh":"检测当前上下文玩家与上下文位置的距离是否在范围内。\n参数:\n§b`min`§r - 最小距离\n§b`max`§r - 最大距离\n§a示例§r:\n`type: distance`\n`min: 0`\n`max: 32`","en":"Checks whether the distance between the player and the context position falls within the specified range.\nParameters:\n§b`min`§r - minimum distance\n§b`max`§r - maximum distance\n§aExample§r:\n`type: distance`\n`min: 0`\n`max: 32`"},
  "condition.has_player": {"zh":"检测当前上下文玩家是否存在。无参数。\n§a示例§r:\n`type: has_player`\n某些事件上下文（如方块事件）可能没有玩家，可先用它兜底判断。","en":"Checks if a player exists in the current context. No parameters.\n§aExample§r:\n`type: has_player`\nSome event contexts (e.g. block events) may have no player; use it as a guard first."},
  "condition.inventory_has_item": {"zh":"检测当前上下文玩家背包中是否有指定物品或数量。\n参数:\n§b`id`§r - 必填；物品 ID\n§b`count`§r - 必填；所需数量\n§a示例§r:\n`type: inventory_has_item`\n`id: \"minecraft:iron_pickaxe\"`\n`count: 1`","en":"Checks whether the current context player's inventory contains the specified item and quantity.\nParameters:\n§b`id`§r - required; item ID\n§b`count`§r - required; required quantity\n§aExample§r:\n`type: inventory_has_item`\n`id: \"minecraft:iron_pickaxe\"`\n`count: 1`"},
  "condition.is_bedrock_player": {"zh":"检测当前上下文玩家是否为**基岩版**玩家（经 Geyser 进入）。无参数。\n§a示例§r:\n`type: is_bedrock_player`","en":"Checks whether the player is a **Bedrock** player (joining via Geyser). No parameters.\n§aExample§r:\n`type: is_bedrock_player`"},
  "condition.test_flag": {"zh":"检查目标位置的权限标志（如 Axiom/领地的标志）。\n参数:\n§b`flag`§r - 必填；标志名: §e`break`、`place`、`interact`、`open_container`§r\n§a示例§r:\n`type: test_flag`\n`flag: break`","en":"Tests flags at the target location.\nParameters:\n§b`flag`§r - required; flag name: `break`, `place`, `interact`, `open_container`\n§aExample§r:\n`type: test_flag`\n`flag: break`"},
  "condition.js": {"zh":"将 JavaScript 函数的返回值作为条件（必须返回**布尔值**）。详见 reference/script。\n参数:\n§b`script`§r - 必填；脚本 id（`<命名空间>:<不含 .js 的相对路径>`）\n§b`function`§r - §e默认 `main`§r；要调用的函数名\n§b`args`§r - 可选；列表（注入为 `args`）或 map（按名注入）\n§a示例§r:\n`type: js`\n`script: \"mypack:combo\"`\n`function: \"canUse\"`\n`args: {min_level: 10}`","en":"Evaluates a JavaScript function as the condition (must return a **boolean**). See reference/script for the full guide.\nParameters:\n§b`script`§r - required; script id (`<namespace>:<path without .js>`)\n§b`function`§r - default `main`; function name to call\n§b`args`§r - optional; list (injected as `args`) or map (injected as named bindings)\n§aExample§r:\n`type: js`\n`script: \"mypack:combo\"`\n`function: \"canUse\"`\n`args: {min_level: 10}`"},
  "function.cancel_event": {"zh":"取消原始事件（如右键点击后不再触发原版行为）。无参数。\n§a示例§r:\n`type: cancel_event`\n§6注意§r: 与 `cancel_event` 相关的条件判断需放在本函数之前。","en":"Cancels the original event (e.g. right-click no longer triggers the vanilla behavior). No parameters.\n§aExample§r:\n`type: cancel_event`"},
  "function.run": {"zh":"按顺序运行一系列函数，适用于共享相同条件的函数。\n参数:\n§b`delay`§r - §e默认 0§r；延迟（tick）\n§b`functions`§r - 必填；函数列表\n§a示例§r:\n`type: run`\n`delay: 0`\n`functions:`\n`  - type: command`\n`    command: say 1`","en":"Runs a list of functions in order. Useful for functions that share the same conditions.\nParameters:\n§b`delay`§r - default `0`; delay in ticks\n§b`functions`§r - required; list of functions\n§aExample§r:\n`type: run`\n`delay: 0`\n`functions:`\n`  - type: command`\n`    command: say 1`"},
  "function.command": {"zh":"以玩家、控制台或事件的形式运行命令。\n参数:\n§b`command`§r - 必填；命令（字符串或列表）\n§b`target`§r - §e默认 `self`§r；`all`/`self`/玩家选择器\n§b`as_player`§r - §e默认 false§r；以玩家身份执行\n§b`as_op`§r - §e默认 false§r；以 OP 身份执行（有安全风险）\n§b`as_event`§r - §e默认 false§r；以事件形式执行（兼容事件驱动插件）\n§a示例§r:\n`type: command`\n`command: \"say 你好 <arg:player.name>\"`","en":"Runs a command as a player, console or event.\nParameters:\n§b`command`§r - required; command (string or list)\n§b`target`§r - default `self`; `all`/`self`/player selector\n§b`as_player`§r - default `false`; execute as the player\n§b`as_op`§r - default `false`; run as OP (security risk)\n§b`as_event`§r - default `false`; fire as an event (compat with event-driven plugins)\n§aExample§r:\n`type: command`\n`command: \"say hello <arg:player.name>\"`"},
  "function.message": {"zh":"发送聊天消息或系统动作栏消息。\n参数:\n§b`message`§r - 必填；消息（字符串或列表）\n§b`target`§r - §e默认 `self`§r；`all`/`self`/玩家选择器\n§b`overlay`§r - §e默认 false§r；§e`false`§r = 聊天框，§e`true`§r = 动作栏\n§a示例§r:\n`type: message`\n`message: \"你好 <papi:player_name>\"`","en":"Sends a chat message or system actionbar message.\nParameters:\n§b`message`§r - required; message (string or list)\n§b`target`§r - default `self`; `all`/`self`/player selector\n§b`overlay`§r - default `false`; `false` = chat box, `true` = actionbar\n§aExample§r:\n`type: message`\n`message: \"Hello <papi:player_name>\"`"},
  "function.actionbar": {"zh":"发送一条动作栏消息。\n参数:\n§b`actionbar`§r - 必填；消息文本\n§b`target`§r - §e默认 `self`§r；`all`/`self`/玩家选择器\n§a示例§r:\n`type: actionbar`\n`actionbar: \"这是一条动作栏消息\"`","en":"Sends an actionbar message.\nParameters:\n§b`actionbar`§r - required; message text\n§b`target`§r - default `self`; `all`/`self`/player selector\n§aExample§r:\n`type: actionbar`\n`actionbar: \"This is an actionbar message\"`"},
  "function.title": {"zh":"发送一条屏幕标题消息。\n参数:\n§b`title`§r - 必填；标题文本\n§b`subtitle`§r - 必填；副标题文本\n§b`fade_in`§r - §e默认 10§r；淡入 tick\n§b`stay`§r - §e默认 20§r；停留 tick\n§b`fade_out`§r - §e默认 5§r；淡出 tick\n§a示例§r:\n`type: title`\n`title: \"<red>标题</red>\"`\n`subtitle: \"<yellow>副标题</yellow>\"`","en":"Sends a title message.\nParameters:\n§b`title`§r - required; title text\n§b`subtitle`§r - required; subtitle text\n§b`fade_in`§r - default `10`; fade-in ticks\n§b`stay`§r - default `20`; stay ticks\n§b`fade_out`§r - default `5`; fade-out ticks\n§aExample§r:\n`type: title`\n`title: \"<red>Title</red>\"`\n`subtitle: \"<yellow>Subtitle</yellow>\"`"},
  "function.open_window": {"zh":"打开一个图形用户界面窗口。\n参数:\n§b`gui_type`§r - 必填；枚举 §e`anvil`、`enchantment`、`grindstone`、`loom`、`smithing`、`crafting`、`cartography`§r\n§b`title`§r - 可选；窗口标题\n§b`target`§r - §e默认 `self`§r\n§a示例§r:\n`type: open_window`\n`gui_type: anvil`\n`title: \"超级铁砧\"`","en":"Opens a GUI window.\nParameters:\n§b`gui_type`§r - required; enum `anvil`, `enchantment`, `grindstone`, `loom`, `smithing`, `crafting`, `cartography`\n§b`title`§r - optional; window title\n§b`target`§r - default `self`\n§aExample§r:\n`type: open_window`\n`gui_type: anvil`\n`title: \"Super Anvil\"`"},
  "function.break_block": {"zh":"破坏一个方块。\n参数:\n§b`x`/`y`/`z`§r - §e默认 `<arg:position.x/y/z>`§r；方块坐标\n§a示例§r:\n`type: break_block`\n`x: <arg:position.x>`\n`y: <arg:position.y>`\n`z: <arg:position.z>`","en":"Breaks a block.\nParameters:\n§b`x`/`y`/`z`§r - default `<arg:position.x/y/z>`; block coordinates\n§aExample§r:\n`type: break_block`\n`x: <arg:position.x>`\n`y: <arg:position.y>`\n`z: <arg:position.z>`"},
  "function.place_block": {"zh":"放置一个方块。\n参数:\n§b`block_state`§r - 必填；方块 ID（如 `default:chinese_lantern`）\n§b`x`/`y`/`z`§r - §e默认 `<arg:position.x/y/z>`§r\n§a示例§r:\n`type: place_block`\n`block_state: \"default:chinese_lantern\"`","en":"Places a block.\nParameters:\n§b`block_state`§r - required; block ID (e.g. `default:chinese_lantern`)\n§b`x`/`y`/`z`§r - default `<arg:position.x/y/z>`\n§aExample§r:\n`type: place_block`\n`block_state: \"default:chinese_lantern\"`"},
  "function.update_block_property": {"zh":"更新某个方块的方块属性。\n参数:\n§b`properties`§r - 必填；键值对（属性名: 值）\n§b`x`/`y`/`z`§r - §e默认 `<arg:position.x/y/z>`§r\n§a示例§r:\n`type: update_block_property`\n`properties:`\n`  axis: x`\n`  age: 7`","en":"Updates the properties of a block.\nParameters:\n§b`properties`§r - required; key-value map (property: value)\n§b`x`/`y`/`z`§r - default `<arg:position.x/y/z>`\n§aExample§r:\n`type: update_block_property`\n`properties:`\n`  axis: x`\n`  age: 7`"},
  "function.transform_block": {"zh":"将当前方块转换为另一个方块并保留全部属性。\n参数:\n§b`block`§r - 必填；新方块 ID\n§b`properties`§r - 可选；键值对\n§b`x`/`y`/`z`§r - §e默认 `<arg:position.x/y/z>`§r\n§a示例§r:\n`type: transform_block`\n`block: default:palm_log`","en":"Transforms the current block into another one, preserving all properties.\nParameters:\n§b`block`§r - required; the new block ID\n§b`properties`§r - optional; key-value map\n§b`x`/`y`/`z`§r - default `<arg:position.x/y/z>`\n§aExample§r:\n`type: transform_block`\n`block: default:palm_log`"},
  "function.drop_loot": {"zh":"根据给定的战利品表掉落物品。\n参数:\n§b`x`/`y`/`z`§r - §e默认 `<arg:position.x/y/z>`§r；掉落位置\n§b`to_inventory`§r - §e默认 false§r；是否直接放入背包\n§b`loot`§r - 必填；战利品表（含 `pools`）\n§a示例§r:\n`type: drop_loot`\n`to_inventory: false`\n`loot:`\n`  pools: ...`","en":"Drops loot based on the given loot table.\nParameters:\n§b`x`/`y`/`z`§r - default `<arg:position.x/y/z>`; drop position\n§b`to_inventory`§r - default `false`; drop directly into inventory\n§b`loot`§r - required; loot table (with `pools`)\n§aExample§r:\n`type: drop_loot`\n`to_inventory: false`\n`loot:`\n`  pools: ...`"},
  "function.update_interaction_tick": {"zh":"更新最后一次交互结束时的游戏刻。无参数。\n§a示例§r:\n`type: update_interaction_tick`\n用于需要刷新交互计时（如自定义长按检测）的场景。","en":"Updates the tick when the last interaction ended. No parameters.\n§aExample§r:\n`type: update_interaction_tick`\nUseful for refreshing interaction timing (e.g. custom hold-duration checks)."},
  "function.set_count": {"zh":"设置此事件中当前物品的数量。\n参数:\n§b`count`§r - 必填；数量\n§b`add`§r - §e默认 false§r；true = 在原有数量上加减\n§b`target`§r - §e默认 `self`§r\n§a示例§r:\n`type: set_count`\n`count: -1`\n`add: true`","en":"Sets the count of the current item in this event.\nParameters:\n§b`count`§r - required; amount\n§b`add`§r - default `false`; true = add/subtract from the current count\n§b`target`§r - default `self`\n§aExample§r:\n`type: set_count`\n`count: -1`\n`add: true`"},
  "function.set_food": {"zh":"设置玩家的饥饿值（0~20）。\n参数:\n§b`food`§r - 必填；饥饿值\n§b`add`§r - §e默认 false§r；true = 加减模式\n§b`target`§r - §e默认 `self`§r\n§a示例§r:\n`type: set_food`\n`food: 4`\n`add: true`","en":"Sets the player's food level (0~20).\nParameters:\n§b`food`§r - required; food value\n§b`add`§r - default `false`; true = add/subtract mode\n§b`target`§r - default `self`\n§aExample§r:\n`type: set_food`\n`food: 4`\n`add: true`"},
  "function.set_saturation": {"zh":"设置玩家的饱和度（0~10）。\n参数:\n§b`saturation`§r - 必填；饱和度\n§b`add`§r - §e默认 false§r\n§b`target`§r - §e默认 `self`§r\n§a示例§r:\n`type: set_saturation`\n`saturation: 2.5`","en":"Sets the player's saturation (0~10).\nParameters:\n§b`saturation`§r - required; saturation value\n§b`add`§r - default `false`\n§b`target`§r - default `self`\n§aExample§r:\n`type: set_saturation`\n`saturation: 2.5`"},
  "function.swing_hand": {"zh":"挥动此事件中涉及的手，或配置中指定的手。\n参数:\n§b`hand`§r - 可选；§e`main_hand`§r / §e`off_hand`§r；不填则从上下文获取需要挥动的手\n§a示例§r:\n`type: swing_hand`\n`hand: main_hand`","en":"Swings the hand involved in this event, or the hand specified in the config.\nParameters:\n§b`hand`§r - optional; `main_hand` / `off_hand`; if omitted, the hand from the context is used\n§aExample§r:\n`type: swing_hand`\n`hand: main_hand`"},
  "function.particle": {"zh":"生成一个粒子效果（完整参数见 reference/particle_effect）。\n参数:\n§b`particle`§r - 必填；粒子 ID\n§b`x`/`y`/`z`§r - §e默认 `<arg:position.x/y/z>`§r\n§b`count`§r - §e默认 1§r；粒子数量\n§b`offset_x/y/z`§r - §e默认 0§r；扩散范围\n§b`speed`§r - §e默认 0§r；速度\n§a示例§r:\n`type: particle`\n`particle: minecraft:end_rod`\n`count: 5`\n`offset_x: 0.3`","en":"Spawns a particle effect (full parameters in reference/particle_effect).\nParameters:\n§b`particle`§r - required; particle ID\n§b`x`/`y`/`z`§r - default `<arg:position.x/y/z>`\n§b`count`§r - default `1`; particle count\n§b`offset_x/y/z`§r - default `0`; spread range\n§b`speed`§r - default `0`; speed\n§aExample§r:\n`type: particle`\n`particle: minecraft:end_rod`\n`count: 5`\n`offset_x: 0.3`"},
  "function.potion_effect": {"zh":"添加一个状态效果。\n参数:\n§b`potion_effect`§r - 必填；效果 ID（如 `minecraft:blindness`）\n§b`duration`§r - §e默认 20§r；持续 tick\n§b`amplifier`§r - §e默认 0§r；等级\n§b`ambient`§r - §e默认 false§r；是否来自信标\n§b`particles`§r - §e默认 true§r；是否渲染粒子\n§b`show_icon`§r - §e默认 true§r；是否显示图标\n§a示例§r:\n`type: potion_effect`\n`potion_effect: minecraft:blindness`\n`duration: 20`","en":"Adds a potion effect.\nParameters:\n§b`potion_effect`§r - required; effect ID (e.g. `minecraft:blindness`)\n§b`duration`§r - default `20`; duration in ticks\n§b`amplifier`§r - default `0`; amplifier level\n§b`ambient`§r - default `false`; whether it comes from a beacon\n§b`particles`§r - default `true`; whether particles render\n§b`show_icon`§r - default `true`; whether the icon shows\n§aExample§r:\n`type: potion_effect`\n`potion_effect: minecraft:blindness`\n`duration: 20`"},
  "function.remove_potion_effect": {"zh":"移除一个状态效果。\n参数:\n§b`potion_effect`§r - 效果 ID（`all: true` 时可选）\n§b`all`§r - §e默认 false§r；true = 移除全部效果\n§a示例§r:\n`type: remove_potion_effect`\n`potion_effect: minecraft:blindness`","en":"Removes a potion effect.\nParameters:\n§b`potion_effect`§r - effect ID (optional when `all: true`)\n§b`all`§r - default `false`; true = remove all effects\n§aExample§r:\n`type: remove_potion_effect`\n`potion_effect: minecraft:blindness`"},
  "function.leveler_exp": {"zh":"添加技能/职业经验（AuraSkills 等插件）。\n参数:\n§b`plugin`§r - 可选；插件名（如 `AuraSkills`）\n§b`leveler`§r - 可选；职业/技能 ID（如 `fishing`）\n§b`count`§r - 可选；经验量\n§a示例§r:\n`type: leveler_exp`\n`plugin: AuraSkills`\n`leveler: fishing`\n`count: 10`","en":"Adds skill/job experience (AuraSkills and similar plugins).\nParameters:\n§b`plugin`§r - optional; plugin name (e.g. `AuraSkills`)\n§b`leveler`§r - optional; job/skill ID (e.g. `fishing`)\n§b`count`§r - optional; amount of experience\n§aExample§r:\n`type: leveler_exp`\n`plugin: AuraSkills`\n`leveler: fishing`\n`count: 10`"},
  "function.set_cooldown": {"zh":"为玩家设置冷却时间。\n参数:\n§b`time`§r - 必填；时长（如 `1m30s`，支持 t/s/m/h/d/w 组合）\n§b`id`§r - 可选；冷却 ID（配合 §bon_cooldown§r 条件使用）\n§b`add`§r - §e默认 false§r；true = 累加冷却\n§a示例§r:\n`type: set_cooldown`\n`time: 1m30s`\n`id: my_cooldown_id`","en":"Sets a cooldown for the player.\nParameters:\n§b`time`§r - required; duration (e.g. `1m30s`; supports t/s/m/h/d/w units)\n§b`id`§r - optional; cooldown ID (used with the `on_cooldown` condition)\n§b`add`§r - default `false`; true = add to the existing cooldown\n§aExample§r:\n`type: set_cooldown`\n`time: 1m30s`\n`id: my_cooldown_id`"},
  "function.remove_cooldown": {"zh":"为玩家移除冷却时间。\n参数:\n§b`id`§r - 冷却 ID（`all: true` 时可选）\n§b`all`§r - §e默认 false§r；true = 移除全部冷却\n§a示例§r:\n`type: remove_cooldown`\n`id: my_cooldown_id`","en":"Removes a cooldown from the player.\nParameters:\n§b`id`§r - cooldown ID (optional when `all: true`)\n§b`all`§r - default `false`; true = remove all cooldowns\n§aExample§r:\n`type: remove_cooldown`\n`id: my_cooldown_id`"},
  "function.play_sound": {"zh":"播放一个音效。\n参数:\n§b`sound`§r - 必填；音效 ID\n§b`x`/`y`/`z`§r - 播放坐标（使用 `target` 时可选）\n§b`target`§r - §e默认 `self`§r\n§b`pitch`§r - §e默认 1§r\n§b`volume`§r - §e默认 1§r\n§b`source`§r - §e默认 `master`§r；枚举 music/master/record/weather/block/hostile/neutral/player/ambient/voice/ui\n§a示例§r:\n`type: play_sound`\n`sound: minecraft:entity.player.levelup`\n`pitch: 1`","en":"Plays a sound.\nParameters:\n§b`sound`§r - required; sound ID\n§b`x`/`y`/`z`§r - play position (optional when `target` is used)\n§b`target`§r - default `self`\n§b`pitch`§r - default `1`\n§b`volume`§r - default `1`\n§b`source`§r - default `master`; enum music/master/record/weather/block/hostile/neutral/player/ambient/voice/ui\n§aExample§r:\n`type: play_sound`\n`sound: minecraft:entity.player.levelup`\n`pitch: 1`"},
  "function.cast_mythic_skill": {"zh":"释放 MythicMobs 技能。\n参数:\n§b`skill`§r - 必填；技能 ID\n§b`power`§r - §e默认 1.0§r；技能强度\n§a示例§r:\n`type: cast_mythic_skill`\n`skill: skill_id`\n`power: 1.0`","en":"Casts a MythicMobs skill.\nParameters:\n§b`skill`§r - required; skill ID\n§b`power`§r - default `1.0`; skill power\n§aExample§r:\n`type: cast_mythic_skill`\n`skill: skill_id`\n`power: 1.0`"},
  "function.spawn_furniture": {"zh":"生成一个家具。\n参数:\n§b`furniture_id`§r - 可选；家具 ID\n§b`x`/`y`/`z`§r - §e默认 `<arg:position.x/y/z>`§r\n§b`pitch`/`yaw`§r - §e默认 `<arg:position.pitch/yaw>`§r\n§b`variant`§r - 可选；变体名（如 `ground`）\n§b`play_sound`§r - §e默认 true§r\n§a示例§r:\n`type: spawn_furniture`\n`furniture_id: \"default:bench\"`","en":"Spawns a furniture.\nParameters:\n§b`furniture_id`§r - optional; furniture ID\n§b`x`/`y`/`z`§r - default `<arg:position.x/y/z>`\n§b`pitch`/`yaw`§r - default `<arg:position.pitch/yaw>`\n§b`variant`§r - optional; variant name (e.g. `ground`)\n§b`play_sound`§r - default `true`\n§aExample§r:\n`type: spawn_furniture`\n`furniture_id: \"default:bench\"`"},
  "function.remove_furniture": {"zh":"移除一个家具。\n参数:\n§b`drop_loot`§r - §e默认 true§r；是否掉落战利品\n§b`play_sound`§r - §e默认 true§r\n§a示例§r:\n`type: remove_furniture`\n`drop_loot: true`","en":"Removes a furniture.\nParameters:\n§b`drop_loot`§r - default `true`; whether to drop loot\n§b`play_sound`§r - default `true`\n§aExample§r:\n`type: remove_furniture`\n`drop_loot: true`"},
  "function.replace_furniture": {"zh":"替换一个家具。\n参数:\n§b`furniture_id`§r - 必填；新家具 ID\n§b`x`/`y`/`z`§r - §e默认 `<arg:furniture.x/y/z>`§r\n§b`pitch`/`yaw`§r - §e默认 `<arg:furniture.pitch/yaw>`§r\n§b`variant`§r - 可选；变体名\n§b`drop_loot`§r - §e默认 true§r\n§b`play_sound`§r - §e默认 true§r\n§a示例§r:\n`type: replace_furniture`\n`furniture_id: \"default:bench\"`","en":"Replaces a furniture.\nParameters:\n§b`furniture_id`§r - required; the new furniture ID\n§b`x`/`y`/`z`§r - default `<arg:furniture.x/y/z>`\n§b`pitch`/`yaw`§r - default `<arg:furniture.pitch/yaw>`\n§b`variant`§r - optional; variant name\n§b`drop_loot`§r - default `true`\n§b`play_sound`§r - default `true`\n§aExample§r:\n`type: replace_furniture`\n`furniture_id: \"default:bench\"`"},
  "function.rotate_furniture": {"zh":"旋转一个家具。家具有时会因碰撞体积无法旋转，此时触发 §bon_failure§r。\n参数:\n§b`degree`§r - 必填；旋转角度（如 90）\n§b`on_success`§r - 成功后的函数列表\n§b`on_failure`§r - 失败后执行的函数列表\n§a示例§r:\n`type: rotate_furniture`\n`degree: 90`\n`on_failure: []`","en":"Rotates a furniture. Sometimes a furniture cannot rotate due to its collision shape, which triggers `on_failure`.\nParameters:\n§b`degree`§r - required; rotation angle (e.g. 90)\n§b`on_success`§r - functions run on success\n§b`on_failure`§r - functions run on failure\n§aExample§r:\n`type: rotate_furniture`\n`degree: 90`\n`on_failure: []`"},
  "function.teleport": {"zh":"传送至指定地点。\n参数:\n§b`x`/`y`/`z`§r - 必填；目标坐标（支持运算，如 `<arg:position.z> + 5`）\n§b`pitch`/`yaw`§r - §e默认 0§r\n§b`world`§r - 可选；世界名\n§a示例§r:\n`type: teleport`\n`x: <arg:position.x>`\n`y: 100`\n`z: <arg:position.z> + 5`","en":"Teleports to a certain location.\nParameters:\n§b`x`/`y`/`z`§r - required; target coordinates (math supported, e.g. `<arg:position.z> + 5`)\n§b`pitch`/`yaw`§r - default `0`\n§b`world`§r - optional; world name\n§aExample§r:\n`type: teleport`\n`x: <arg:position.x>`\n`y: 100`\n`z: <arg:position.z> + 5`"},
  "function.toast": {"zh":"发送一个弹窗（Toast）。\n参数:\n§b`toast`§r - 必填；弹窗文本\n§b`icon`§r - 必填；图标物品 ID\n§b`advancement_type`§r - §e默认 `goal`§r；枚举 §e`goal`/`task`/`challenge`§r\n§a示例§r:\n`type: toast`\n`toast: 这是一个弹窗`\n`icon: minecraft:stone`","en":"Sends a toast notification.\nParameters:\n§b`toast`§r - required; toast text\n§b`icon`§r - required; icon item ID\n§b`advancement_type`§r - default `goal`; enum `goal`/`task`/`challenge`\n§aExample§r:\n`type: toast`\n`toast: This is a toast`\n`icon: minecraft:stone`"},
  "function.damage": {"zh":"伤害目标。\n参数:\n§b`amount`§r - §e默认 1.0§r；伤害量\n§b`damage_type`§r - §e默认 `generic`§r；伤害类型\n§b`target`§r - §e默认 `self`§r\n§a示例§r:\n`type: damage`\n`amount: 5.0`\n`damage_type: generic`","en":"Damages the target.\nParameters:\n§b`amount`§r - default `1.0`; damage amount\n§b`damage_type`§r - default `generic`; damage type\n§b`target`§r - default `self`\n§aExample§r:\n`type: damage`\n`amount: 5.0`\n`damage_type: generic`"},
  "function.set_variable": {"zh":"设置一个变量，可用 §e`<arg:var_[name]>`§r 访问（把 [name] 换成变量名）。\n参数:\n§b`name`§r - 必填；变量名\n§b`number`§r - 数值\n§b`text`§r - 文本\n§b`as_int`§r - §e默认 false§r；number 是否按整数处理\n§a示例§r:\n`type: set_variable`\n`name: my_variable`\n`text: \"你好\"`","en":"Sets a variable, accessible via `<arg:var_[name]>` (replace [name] with the variable name).\nParameters:\n§b`name`§r - required; variable name\n§b`number`§r - a number value\n§b`text`§r - a text value\n§b`as_int`§r - default `false`; whether number is treated as an integer\n§aExample§r:\n`type: set_variable`\n`name: my_variable`\n`text: \"hello\"`"},
  "function.merchant_trade": {"zh":"打开一个自定义村民交易界面。\n参数:\n§b`title`§r - 界面标题\n§b`offers`§r - 必填；交易列表，每个交易含:\n§b`cost_1`§r - 收购物品 1（可带 `components` 精确匹配组件、`count` 数量）\n§b`cost_2`§r - 可选；收购物品 2\n§b`result`§r - 出售物品（可带 `count`）\n§b`experience`§r - §e默认 1§r；交易经验\n§a示例§r:\n`type: merchant_trade`\n`offers:`\n`  - cost_1:`\n`      item: iron_pickaxe`\n`    result:`\n`      item: default:topaz`\n`      count: 4`","en":"Opens a custom villager trading UI.\nParameters:\n§b`title`§r - UI title\n§b`offers`§r - required; list of trades, each with:\n§b`cost_1`§r - buy item 1 (may include `components` for exact matching and `count`)\n§b`cost_2`§r - optional; buy item 2\n§b`result`§r - sell item (may include `count`)\n§b`experience`§r - default `1`; trade experience\n§aExample§r:\n`type: merchant_trade`\n`offers:`\n`  - cost_1:`\n`      item: iron_pickaxe`\n`    result:`\n`      item: default:topaz`\n`      count: 4`"},
  "function.remove_entity": {"zh":"从当前上下文中移除实体（如移除交互中的家具实体）。无参数。\n§a示例§r:\n`type: remove_entity`\n常用于家具/方块事件中的一次性交互逻辑。","en":"Removes the entity from the current context. No parameters.\n§aExample§r:\n`type: remove_entity`"},
  "function.if_else": {"zh":"运行**首个**满足条件的函数（只执行第一个匹配分支，之后即使有满足的也不执行）。\n参数:\n§b`rules`§r - 必填；分支列表，每项含:\n§b`conditions`§r - 可选；该分支的条件\n§b`functions`§r - 必填；该分支的函数\n§a示例§r:\n`type: if_else`\n`rules:`\n`  - conditions:`\n`      - type: permission`\n`        permission: group.admin`\n`    functions:`\n`      - type: command`\n`        command: say 管理员你好`","en":"Runs the **first** function that meets the specified conditions (only the first matching branch executes).\nParameters:\n§b`rules`§r - required; list of branches, each with:\n§b`conditions`§r - optional; conditions of the branch\n§b`functions`§r - required; functions of the branch\n§aExample§r:\n`type: if_else`\n`rules:`\n`  - conditions:`\n`      - type: permission`\n`        permission: group.admin`\n`    functions:`\n`      - type: command`\n`        command: say admin`"},
  "function.when": {"zh":"根据源数值进行匹配，执行首个匹配案例的函数（类似 switch-case）。\n参数:\n§b`source`§r - 必填；要匹配的源值\n§b`cases`§r - 必填；案例列表，每项含 §b`when`§r（值或值列表）与 §b`functions`§r\n§b`fallback`§r - 可选；无匹配时执行的函数\n§a示例§r:\n`type: when`\n`source: <papi:player_world>`\n`cases:`\n`  - when: \"world\"`\n`    functions:`\n`      - type: message`\n`        message: \"您位于主世界\"`\n`  - when: [\"world_nether\", \"world_the_end\"]`\n`    functions: []`\n`fallback:`\n`  - type: message`\n`    message: \"未知世界\"`","en":"Evaluates a source value and executes the functions of the first matching case (like a switch-case statement).\nParameters:\n§b`source`§r - required; the source value to match\n§b`cases`§r - required; list of cases, each with `when` (a value or list of values) and `functions`\n§b`fallback`§r - optional; functions run when nothing matches\n§aExample§r:\n`type: when`\n`source: <papi:player_world>`\n`cases:`\n`  - when: \"world\"`\n`    functions:`\n`      - type: message`\n`        message: \"You are in the overworld\"`\n`  - when: [\"world_nether\", \"world_the_end\"]`\n`    functions: []`\n`fallback:`\n`  - type: message`\n`    message: \"Unknown world\"`"},
  "function.damage_item": {"zh":"消耗当前上下文玩家手持物品的耐久度。\n参数:\n§b`amount`§r - §e默认 1§r；消耗量\n§b`slot`§r - 可选；枚举 §e`mainhand`/`offhand`/`feet`/`legs`/`chest`/`head`§r\n§a示例§r:\n`type: damage_item`\n`amount: 1`","en":"Consumes durability of the item currently held by the player in the current context.\nParameters:\n§b`amount`§r - default `1`; amount to consume\n§b`slot`§r - optional; enum `mainhand`/`offhand`/`feet`/`legs`/`chest`/`head`\n§aExample§r:\n`type: damage_item`\n`amount: 1`"},
  "function.cycle_block_property": {"zh":"循环某个方块的方块属性（如 axis/facing 循环切换）。\n参数:\n§b`property`§r - 必填；方块属性名\n§b`inverse`§r - §e默认 `<arg:player.is_sneaking>`§r；true = 反向循环\n§b`x`/`y`/`z`§r - §e默认 `<arg:position.x/y/z>`§r\n§b`rules`§r - 可选；自定义循环规则（old: new 映射）\n§a示例§r:\n`type: cycle_block_property`\n`property: facing`\n`rules:`\n`  north: east`\n`  east: south`","en":"Cycles the value of a block property (e.g. axis/facing).\nParameters:\n§b`property`§r - required; block property name\n§b`inverse`§r - default `<arg:player.is_sneaking>`; true = cycle backwards\n§b`x`/`y`/`z`§r - default `<arg:position.x/y/z>`\n§b`rules`§r - optional; custom cycle rules (old: new map)\n§aExample§r:\n`type: cycle_block_property`\n`property: facing`\n`rules:`\n`  north: east`\n`  east: south`"},
  "function.set_exp": {"zh":"设置玩家的经验值。\n参数:\n§b`count`§r - 必填；经验值\n§b`add`§r - §e默认 false§r；true = 加减模式\n§b`target`§r - §e默认 `self`§r\n§a示例§r:\n`type: set_exp`\n`count: 10`\n`add: true`","en":"Sets the player's experience points.\nParameters:\n§b`count`§r - required; experience amount\n§b`add`§r - default `false`; true = add/subtract mode\n§b`target`§r - default `self`\n§aExample§r:\n`type: set_exp`\n`count: 10`\n`add: true`"},
  "function.set_level": {"zh":"设置玩家的经验等级。\n参数:\n§b`count`§r - 必填；等级\n§b`add`§r - §e默认 false§r；true = 加减模式\n§b`target`§r - §e默认 `self`§r\n§a示例§r:\n`type: set_level`\n`count: 1`","en":"Sets the player's experience level.\nParameters:\n§b`count`§r - required; level\n§b`add`§r - default `false`; true = add/subtract mode\n§b`target`§r - default `self`\n§aExample§r:\n`type: set_level`\n`count: 1`"},
  "function.play_totem_animation": {"zh":"给玩家播放图腾动画。\n参数:\n§b`item`§r - 必填；动画中显示的物品（如 `default:topaz`）\n§b`sound`§r - 可选；音效\n§b`pitch`§r - §e默认 1§r\n§b`volume`§r - §e默认 1§r\n§b`silent`§r - §e默认 false§r\n§b`target`§r - §e默认 `self`§r\n§a示例§r:\n`type: play_totem_animation`\n`item: \"default:topaz\"`","en":"Plays the totem animation for the player.\nParameters:\n§b`item`§r - required; item shown in the animation (e.g. `default:topaz`)\n§b`sound`§r - optional; sound\n§b`pitch`§r - default `1`\n§b`volume`§r - default `1`\n§b`silent`§r - default `false`\n§b`target`§r - default `self`\n§aExample§r:\n`type: play_totem_animation`\n`item: \"default:topaz\"`"},
  "function.close_inventory": {"zh":"关闭当前打开的容器。\n参数:\n§b`target`§r - §e默认 `self`§r\n§a示例§r:\n`type: close_inventory`","en":"Closes the currently open inventory.\nParameters:\n§b`target`§r - default `self`\n§aExample§r:\n`type: close_inventory`"},
  "function.clear_item": {"zh":"清理玩家背包中的物品。\n参数:\n§b`id`§r - 必填；物品 ID\n§b`count`§r - §e默认 1§r；数量\n§a示例§r:\n`type: clear_item`\n`id: \"default:topaz\"`\n`count: 1`","en":"Clears items from the player's inventory.\nParameters:\n§b`id`§r - required; item ID\n§b`count`§r - default `1`; amount\n§aExample§r:\n`type: clear_item`\n`id: \"default:topaz\"`\n`count: 1`"},
  "function.heal": {"zh":"恢复玩家生命值。\n参数:\n§b`amount`§r - §e默认 1.0§r；回复量\n§b`target`§r - §e默认 `self`§r\n§a示例§r:\n`type: heal`\n`amount: 5.0`","en":"Heals the player.\nParameters:\n§b`amount`§r - default `1.0`; amount to heal\n§b`target`§r - default `self`\n§aExample§r:\n`type: heal`\n`amount: 5.0`"},
  "function.spawn_mythic_mob": {"zh":"生成指定的 MythicMobs 生物。\n参数:\n§b`mob`§r - 必填；生物 ID\n§b`level`§r - §e默认 1.0§r；等级\n§b`world`§r - 可选；世界名\n§b`x`/`y`/`z`§r - §e默认 `<arg:position.x/y/z>`§r\n§b`pitch`/`yaw`§r - §e默认 `<arg:position.pitch/yaw>`§r\n§a示例§r:\n`type: spawn_mythic_mob`\n`mob: \"test_mob\"`","en":"Spawns a MythicMobs mob.\nParameters:\n§b`mob`§r - required; mob ID\n§b`level`§r - default `1.0`; level\n§b`world`§r - optional; world name\n§b`x`/`y`/`z`§r - default `<arg:position.x/y/z>`\n§b`pitch`/`yaw`§r - default `<arg:position.pitch/yaw>`\n§aExample§r:\n`type: spawn_mythic_mob`\n`mob: \"test_mob\"`"},
  "function.set_furniture_variant": {"zh":"设置一个家具的变体。\n参数:\n§b`variant`§r - 必填；变体名\n§a示例§r:\n`type: set_furniture_variant`\n`variant: a_variant`","en":"Sets the variant of a furniture.\nParameters:\n§b`variant`§r - required; variant name\n§aExample§r:\n`type: set_furniture_variant`\n`variant: a_variant`"},
  "function.set_item_cooldown": {"zh":"设置玩家对某个物品的冷却（1.21.2+）。\n参数:\n§b`id`§r - 必填；物品 ID（冷却组）\n§b`time`§r - 必填；时长，支持 §e`t`(tick)`s`(秒)`m`(分)`h`(时)`d`(天)`w`(周)§r 单位组合\n§b`add`§r - §e默认 false§r；true = 累加冷却\n§a示例§r:\n`type: set_item_cooldown`\n`id: \"minecraft:ender_pearl\"`\n`time: \"5s\"`","en":"Sets the cooldown for a specific item for the player (1.21.2+).\nParameters:\n§b`id`§r - required; item ID (cooldown group)\n§b`time`§r - required; duration, supports `t`(tick)`s`(sec)`m`(min)`h`(hour)`d`(day)`w`(week) unit combos\n§b`add`§r - default `false`; true = add to cooldown\n§aExample§r:\n`type: set_item_cooldown`\n`id: \"minecraft:ender_pearl\"`\n`time: \"5s\"`"},
  "function.js": {"zh":"调用一个 JavaScript 函数（完整指南见 reference/script）。\n参数:\n§b`script`§r - 必填；脚本 id（`<命名空间>:<不含 .js 的相对路径>`）\n§b`function`§r - 必填；要调用的函数名\n§b`args`§r - 可选；列表（注入为 `args`）或 map（按名注入）\n§a示例§r:\n`type: js`\n`script: \"mypack:combo\"`\n`function: \"onRightClick\"`\n`args: {combo: \"combo_a\", times: 3}`","en":"Invokes a JavaScript function (full guide in reference/script).\nParameters:\n§b`script`§r - required; script id (`<namespace>:<path without .js>`)\n§b`function`§r - required; function name to call\n§b`args`§r - optional; list (injected as `args`) or map (injected as named bindings)\n§aExample§r:\n`type: js`\n`script: \"mypack:combo\"`\n`function: \"onRightClick\"`\n`args: {combo: \"combo_a\", times: 3}`"},
  "loot.apply_bonus": {"zh":"根据给定的魔咒和公式增加掉落物品的数量。\n参数:\n§b`enchantment`§r - 必填；魔咒 ID（如 `minecraft:fortune`）\n§b`formula`§r - 必填；公式对象，`type` 为 §e`ore_drops`§r 或 §e`binomial_with_bonus_count`§r\n§a示例§r:\n`type: apply_bonus`\n`enchantment: minecraft:fortune`\n`formula:`\n`  type: ore_drops`","en":"Increases the quantity of dropped items based on the given enchantment and formula.\nParameters:\n§b`enchantment`§r - required; enchantment ID (e.g. `minecraft:fortune`)\n§b`formula`§r - required; formula object with `type` of `ore_drops` or `binomial_with_bonus_count`\n§aExample§r:\n`type: apply_bonus`\n`enchantment: minecraft:fortune`\n`formula:`\n`  type: ore_drops`"},
  "loot.apply_data": {"zh":"对物品应用物品数据（item data）。\n参数:\n§b`data`§r - 必填；物品数据对象（字段见 configuration/item/data）\n§a示例§r:\n`type: apply_data`\n`data:`\n`  item_name: \"自定义物品\"`","en":"Applies item data on the item.\nParameters:\n§b`data`§r - required; item data object (fields in configuration/item/data)\n§aExample§r:\n`type: apply_data`\n`data:`\n`  item_name: \"Custom Item\"`"},
  "loot.set_count": {"zh":"设置该物品的数量。\n参数:\n§b`count`§r - 必填；数量\n§b`add`§r - §e默认 false§r；true = 添加而非设置\n§a示例§r:\n`type: set_count`\n`count: 10`\n`add: true`","en":"Sets the count of the item.\nParameters:\n§b`count`§r - required; amount\n§b`add`§r - default `false`; true = add instead of set\n§aExample§r:\n`type: set_count`\n`count: 10`\n`add: true`"},
  "loot.explosion_decay": {"zh":"若物品因方块被爆炸破坏而产生，每个物品有 **1/爆炸半径** 的概率消失；堆叠物品会被拆成单个分别计算；否则此修饰器不做任何处理。无参数。\n§a示例§r:\n`type: explosion_decay`","en":"If the item drops from a block destroyed by an explosion, each item has a **1/explosion radius** chance to disappear; stacked items are split and rolled individually; otherwise this modifier does nothing. No parameters.\n§aExample§r:\n`type: explosion_decay`"},
  "loot.drop_exp": {"zh":"掉落一定数量的经验值。\n参数:\n§b`count`§r - 必填；经验值数量（支持 `uniform` 等随机类型）\n§a示例§r:\n`type: drop_exp`\n`count: 1`\n§c注意§r: 方块掉落经验应使用 Drop Experience Block 行为，而非此函数。","en":"Drops a certain amount of experience.\nParameters:\n§b`count`§r - required; amount of experience (random types like `uniform` supported)\n§aExample§r:\n`type: drop_exp`\n`count: 1`\n§cNote§r: for blocks dropping experience, use the Drop Experience Block behavior instead of this function."},
  "loot.limit_count": {"zh":"限制物品数量。\n参数:\n§b`min`§r - 最小数量\n§b`max`§r - 最大数量\n§a示例§r:\n`type: limit_count`\n`min: 1`\n`max: 5`","en":"Limits the quantity of the item.\nParameters:\n§b`min`§r - minimum count\n§b`max`§r - maximum count\n§aExample§r:\n`type: limit_count`\n`min: 1`\n`max: 5`"},
  "loot.item": {"zh":"设置掉落物品类型，支持自定义物品。\n参数:\n§b`item`§r - 必填；物品 ID\n§b`weight`§r - 可选；相对权重，越大越容易被选中\n§b`functions`/`conditions`§r - 可选；后处理函数与掉落条件\n§a示例§r:\n`type: item`\n`item: \"minecraft:apple\"`\n`weight: 1`","en":"Sets the type of the dropped item, which can be a custom item.\nParameters:\n§b`item`§r - required; item ID\n§b`weight`§r - optional; relative weight, higher = more likely to be chosen\n§b`functions`/`conditions`§r - optional; post-processing functions and drop conditions\n§aExample§r:\n`type: item`\n`item: \"minecraft:apple\"`\n`weight: 1`"},
  "loot.furniture_item": {"zh":"掉落玩家放置家具时使用的**原物品**，保留所有数据（自定义名称、耐久、各种组件等）。\n参数:\n§b`item`§r - 回退物品 ID（家具通过 API 放置且无源物品时使用）\n§6建议§r: 家具战利品务必使用此条目类型，保证玩家拿回放置时的原物。\n§a示例§r:\n`type: furniture_item`\n`item: \"default:fallback_item\"`","en":"Drops the exact item the player used to place the furniture, preserving all its data (custom name, durability, NBT, etc.).\nParameters:\n§b`item`§r - fallback item ID (used when the furniture was placed via API without a source item)\n§6Tip§r: always use this entry type for furniture loot so players get their original placement item back.\n§aExample§r:\n`type: furniture_item`\n`item: \"default:fallback_item\"`"},
  "loot.exp": {"zh":"掉落给定数量的经验值。\n参数:\n§b`count`§r - 必填；经验值数量\n§a示例§r:\n`type: exp`\n`count: 1`","en":"Drops a certain amount of experience.\nParameters:\n§b`count`§r - required; amount of experience\n§aExample§r:\n`type: exp`\n`count: 1`"},
  "loot.alternatives": {"zh":"从给定列表中找到**第一个**满足 `conditions` 的 `entry`。\n参数:\n§b`children`§r - 必填；条目列表，每项可带自己的 `conditions` 与 `functions`\n§a示例§r（精准采集则掉矿物方块，否则掉矿物）:\n`type: alternatives`\n`children:`\n`  - type: item`\n`    item: \"${ore_block}\"`\n`    conditions:`\n`      - type: enchantment`\n`        predicate: minecraft:silk_touch>=1`\n`  - type: item`\n`    item: \"${ore_drop}\"`","en":"Finds the **first** `entry` from the given list that meets the `conditions`.\nParameters:\n§b`children`§r - required; list of entries, each with its own `conditions` and `functions`\n§aExample§r (silk touch drops the ore block, otherwise the ore drop):\n`type: alternatives`\n`children:`\n`  - type: item`\n`    item: \"${ore_block}\"`\n`    conditions:`\n`      - type: enchantment`\n`        predicate: minecraft:silk_touch>=1`\n`  - type: item`\n`    item: \"${ore_drop}\"`"},
  "loot.loot_table": {"zh":"引用另一张战利品表并内联生成其战利品。\n参数:\n§b`id`§r - 必填；战利品表 ID\n§6注意§r: 若不存在对应 CE 战利品表，会回退到同名的原版数据包战利品表，可直接引用原版表。\n§a示例§r:\n`type: loot_table`\n`id: \"minecraft:chests/simple_dungeon\"`","en":"References another loot table and generates its loot inline.\nParameters:\n§b`id`§r - required; loot table ID\n§6Note§r: if no CraftEngine loot table with that id exists, it falls back to the datapack table with the same id, so vanilla tables can be referenced directly.\n§aExample§r:\n`type: loot_table`\n`id: \"minecraft:chests/simple_dungeon\"`"},
  "loot.ore_drops": {"zh":"和原版 Minecraft 一样的**矿物掉落随机算法**。无参数。\n用作 §bapply_bonus§r 的公式类型:\n`type: apply_bonus`\n`enchantment: minecraft:fortune`\n`formula:`\n`  type: ore_drops`","en":"The same ore drop algorithm used in vanilla Minecraft. No parameters.\nUsed as a formula type for `apply_bonus`:\n`type: apply_bonus`\n`enchantment: minecraft:fortune`\n`formula:`\n`  type: ore_drops`"},
  "loot.binomial_with_bonus_count": {"zh":"和原版相同的**二项分布**随机数算法。\n参数:\n§b`extra`§r - 额外计算的次数\n§b`probability`§r - 二项分布中的概率 p\n§6说明§r: n = 魔咒等级 + extra，魔咒等级会提升抽取次数。\n§a示例§r:\n`type: binomial_with_bonus_count`\n`extra: 3`\n`probability: 0.5`","en":"The same binomial drop algorithm used in vanilla Minecraft.\nParameters:\n§b`extra`§r - a few extra attempts to drop the item\n§b`probability`§r - probability p of the binomial distribution\n§6Note§r: n = enchantment level + extra; higher enchantment levels increase the number of attempts.\n§aExample§r:\n`type: binomial_with_bonus_count`\n`extra: 3`\n`probability: 0.5`"},
  "settings.repairable.map.crafting_table": {"zh":"是否可以通过**工作台**（合成）修复物品。此详细配置会覆盖上方简单的布尔写法。\n示例: §a`crafting_table: true`§r 允许工作台修复。","en":"Whether the item can be repaired through the **crafting table**. This detailed config overrides the simple boolean above.\nExample: §a`crafting_table: true`§r allows crafting-table repairs."},
  "settings.repairable.map.anvil_repair": {"zh":"是否可以在**铁砧**中用材料修复物品。此详细配置会覆盖上方简单的布尔写法。\n示例: §a`anvil_repair: false`§r 禁止铁砧材料修复。","en":"Whether the item can be repaired with materials in an **anvil**. This detailed config overrides the simple boolean above.\nExample: §a`anvil_repair: false`§r disables anvil material repair."},
  "settings.repairable.map.anvil_combine": {"zh":"是否可以在**铁砧**中合并（将两件同类型受损物品合并成一件）。此详细配置会覆盖上方简单的布尔写法。\n示例: §a`anvil_combine: true`§r 允许铁砧合并。","en":"Whether the item can be **combined in an anvil** (merging two damaged items of the same type into one). This detailed config overrides the simple boolean above.\nExample: §a`anvil_combine: true`§r allows anvil combining."},
  "settings.anvil_repair_item.<n>.amount": {"zh":"列表中的每一项指定一个目标物品（`target`）及其修复效果。`amount` 为该物品在铁砧修复时恢复的**固定耐久度**。\n示例: §a`target: \"#topaz_tools\"`、`amount: 20`§r 表示标签内的每件物品恢复 20 点耐久。\n与 `percent` 互斥，二者填其一。","en":"Each entry in the list pairs a target item (`target`) with its repair effect. `amount` restores a **fixed durability** when repairing.\nExample: §a`target: \"#topaz_tools\"`, `amount: 20`§r — each tagged item restores 20 durability.\nMutually exclusive with `percent`; fill in only one."},
  "settings.anvil_repair_item.<n>.percent": {"zh":"列表中的每一项指定一个目标物品（`target`）及其修复效果。`percent` 为该物品在铁砧修复时恢复的**总耐久度百分比**。\n示例: §a`percent: 0.25`§r = 25%，恢复 n% 总耐久度。\n与 `amount` 互斥，二者填其一。","en":"Each entry in the list pairs a target item (`target`) with its repair effect. `percent` restores **n% of total durability** when repairing.\nExample: §a`percent: 0.25`§r = 25% of total durability.\nMutually exclusive with `amount`; fill in only one."},
  "settings.renameable.map.anvil_requires_level": {"zh":"在铁砧中重命名此物品所需的最低经验等级。\n示例: §a`anvil_requires_level: 5`§r 表示需要 5 级经验。","en":"The minimum experience level required to rename this item in an anvil.\nExample: §a`anvil_requires_level: 5`§r requires level 5."},
  "settings.projectile.display": {"zh":"弹射物实体的**显示配置**：指定显示的物品、位置偏移、旋转、显示变换与缩放。\n示例: §a`item: default:topaz_trident`、`translation: 0,0,0`、`rotation: 1,1,1,1`、`display_transform: NONE`、`scale: 0.5`§r。","en":"The **display config** of the projectile entity: which item to display, translation, rotation, display transform and scale.\nExample: §a`item: default:topaz_trident`, `translation: 0,0,0`, `rotation: 1,1,1,1`, `display_transform: NONE`, `scale: 0.5`§r."},
  "settings.projectile.display.item": {"zh":"弹射物显示的物品（即被抛出的物品外观）。\n示例: §a`item: default:topaz_trident`§r。","en":"The item to display as the projectile.\nExample: §a`item: default:topaz_trident`§r."},
  "settings.projectile.display.translation": {"zh":"弹射物显示的位置偏移，格式为 `x,y,z`。\n示例: §a`translation: 0,0,0`§r。","en":"Position offset of the displayed projectile, in `x,y,z` format.\nExample: §a`translation: 0,0,0`§r."},
  "settings.projectile.display.rotation": {"zh":"弹射物显示的旋转（四元数），格式为 `x,y,z,w`。\n**你的建模方式将直接影响此参数**——无论使用哪种建模方法，最关键的是将武器尖端指向正确的位置，以确保最佳的命中点。\n示例: §a`rotation: 1,1,1,1`§r。","en":"Rotation of the displayed projectile (quaternion), in `x,y,z,w` format.\n**Your modeling method directly affects this argument** — whatever modeling method you use, the most important thing is to keep the sharp part of the projectile pointed correctly to ensure the best hit point.\nExample: §a`rotation: 1,1,1,1`§r."},
  "settings.projectile.display.display_transform": {"zh":"弹射物显示的变换类型。\n示例: §a`display_transform: NONE`§r。","en":"The display transform applied to the projectile.\nExample: §a`display_transform: NONE`§r."},
  "settings.projectile.display.scale": {"zh":"弹射物显示的缩放倍数。\n示例: §a`scale: 0.5`§r 即缩放到 50%。","en":"Scale of the displayed projectile.\nExample: §a`scale: 0.5`§r = 50% size."},
  "settings.projectile.sounds.throw": {"zh":"抛出弹射物时播放的音效（声音事件 ID）。\n示例: §a`throw: minecraft:item.trident.throw`§r。\n支持高级配置格式: 可填 `id`、`pitch`（如 `0.9~1` 随机区间）、`volume`。","en":"Sound played when the projectile is thrown (sound event id).\nExample: §a`throw: minecraft:item.trident.throw`§r.\nAdvanced format supported: an object with `id`, `pitch` (e.g. `0.9~1` random range) and `volume`."},
  "settings.projectile.sounds.hit_entity": {"zh":"弹射物命中实体时播放的音效（声音事件 ID）。\n示例: §a`hit_entity: minecraft:item.trident.hit`§r。\n支持根据命中目标改变音效类型: 填 `default` 加 `overrides`（键为目标方块/实体，值为音效 ID）。","en":"Sound played when the projectile hits an entity (sound event id).\nExample: §a`hit_entity: minecraft:item.trident.hit`§r.\nSupports changing the sound by hit target: `default` plus `overrides` mapping the target to a sound id."},
  "settings.projectile.sounds.hit_block": {"zh":"弹射物命中方块时播放的音效（声音事件 ID）。\n示例: §a`hit_block: minecraft:item.trident.hit_ground`§r。\n支持根据命中目标改变音效类型，如 §a`overrides: {minecraft:stone: minecraft:item.trident.hit_stone}`§r。","en":"Sound played when the projectile hits a block (sound event id).\nExample: §a`hit_block: minecraft:item.trident.hit_ground`§r.\nSupports changing the sound by hit target, e.g. §a`overrides: {minecraft:stone: minecraft:item.trident.hit_stone}`§r."},
  "settings.projectile.ignore_infinity_enchantment": {"zh":"作为弹药时是否忽略**无限附魔**。（默认值: §efalse§r）\n为 §a`true`§r 时，即使弓/弩带有无限附魔，弹射物射出后也不会返还。","en":"Whether to ignore the **Infinity enchantment** when used as ammunition. (Default: §efalse§r)\nWhen §a`true`§r, the projectile is not returned even if the bow/crossbow has Infinity."},
  "settings.projectile.pickupable": {"zh":"射出命中后是否可以被捡起来。（默认值: §etrue§r）","en":"Whether the projectile can be picked up after hitting a target. (Default: §etrue§r)"},
  "settings.projectile.remove_on_hit": {"zh":"是否在命中后移除弹射物。（默认值: §efalse§r）","en":"Whether to remove the projectile upon impact. (Default: §efalse§r)"},
  "settings.projectile.gravity": {"zh":"弹射物是否受重力影响。（默认值: §etrue§r）\n为 §a`false`§r 时弹射物沿直线飞行。","en":"Whether the projectile is affected by gravity. (Default: §etrue§r)\nSet to §a`false`§r for a straight trajectory."},
  "settings.projectile.velocity": {"zh":"弹射物速度。\n示例: §a`velocity: 1`§r，数值越大飞得越快越远。","en":"Projectile velocity.\nExample: §a`velocity: 1`§r — higher values fly faster and farther."},
  "settings.projectile.damage": {"zh":"弹射物的**基础伤害**。\n示例: §a`damage: 10`§r。","en":"Base damage of the projectile.\nExample: §a`damage: 10`§r."},
  "settings.projectile.pierce_level": {"zh":"穿透等级——弹射物可以穿透多少个实体。\n示例: §a`pierce_level: 5`§r 表示可穿透 5 个实体。","en":"The number of times this projectile can pierce through an entity.\nExample: §a`pierce_level: 5`§r pierces 5 entities."},
  "settings.food.nutrition": {"zh":"食用后恢复的饥饿值。范围 §e0~20§r，**整数**。\n示例: §a`nutrition: 5`§r。","en":"Hunger restored when eaten. Range §e0~20§r, **integer**.\nExample: §a`nutrition: 5`§r."},
  "settings.food.saturation": {"zh":"食用后恢复的饱和度。范围 §e0~10§r，**单精度浮点数**。\n示例: §a`saturation: 3.5`§r。","en":"Saturation restored when eaten. Range §e0~10§r, **float**.\nExample: §a`saturation: 3.5`§r."},
  "settings.craft_remainder.fixed.item": {"zh":"`type: fixed`（返回固定物品）模式下返还的物品 ID。\n示例: §a`item: bucket`§r——用桶参与合成后返还桶。","en":"The item id returned when `type: fixed` is used.\nExample: §a`item: bucket`§r — the bucket is returned after crafting."},
  "settings.craft_remainder.fixed.count": {"zh":"`type: fixed` 模式下返还的物品数量。\n示例: §a`count: 1`§r。","en":"The number of items returned when `type: fixed` is used.\nExample: §a`count: 1`§r."},
  "settings.craft_remainder.hurt_and_break.damage": {"zh":"`type: hurt_and_break`（消耗耐久）模式下每次合成消耗的耐久度。（默认值: §e1§r）\n示例: §a`damage: 1`§r。","en":"Durability consumed per craft when `type: hurt_and_break` is used. (Default: §e1§r)\nExample: §a`damage: 1`§r."},
  "settings.craft_remainder.recipe_based.terms": {"zh":"`type: recipe_based`（根据配方选择）模式下的条件条目列表。\n列表中的每一项将一组 `recipes`（配方 ID 列表）映射到一个 `craft_remainder`——可以是物品 ID 简写，也可以是 `type: fixed` 或 `hurt_and_break` 配置。","en":"The term list for `type: recipe_based` mode.\nEach entry in the list maps a set of `recipes` (recipe id list) to a `craft_remainder` — either a plain item id, or a `type: fixed` / `hurt_and_break` config."},
  "settings.craft_remainder.recipe_based.terms.<n>.recipes": {"zh":"列表中的每一项的 `recipes` 为**配方 ID 列表**——合成命中其中任一配方时，使用该条目指定的 `craft_remainder`。\n示例: §a`recipes: [test:test1, test:test3]`§r。","en":"`recipes` in each entry is the **list of recipe ids** — when the craft matches any of them, that entry's `craft_remainder` applies.\nExample: §a`recipes: [test:test1, test:test3]`§r."},
  "settings.invulnerable": {"zh":"指定此物品不会被哪些**伤害类型**摧毁。（译者注: 与数据组件 `damage_resistant` 不同，此设置通过取消事件实现）\n可选项: §a`lava`§r 熔岩、§a`fire`§r 火焰、§a`fire_tick`§r 火焰刻、§a`block_explosion`§r 方块爆炸（如重生锚）、§a`entity_explosion`§r 实体爆炸（苦力怕、TNT）、§a`lightning`§r 闪电、§a`contact`§r 接触（如仙人掌）。\n示例: §a`invulnerable: [lava, fire]`§r。","en":"Damage types that cannot destroy this item. (Note: unlike the `damage_resistant` data component, this is implemented by cancelling events)\nOptions: §a`lava`§r, §a`fire`§r, §a`fire_tick`§r, §a`block_explosion`§r (respawn anchor), §a`entity_explosion`§r (creeper, TNT), §a`lightning`§r, §a`contact`§r (cactus).\nExample: §a`invulnerable: [lava, fire]`§r."},
  "data.appearance.custom_name": {"zh":"玩家为物品指定的名称，通常通过铁砧设置。显示优先级最高，默认带斜体（可用 `<!i>` 关闭斜体）。\n示例: §a`\"<!i><#FF8C00>Topaz Sword\"`§r（支持 MiniMessage 格式）。","en":"A player-assigned name for the item, typically set via an anvil. Has highest priority for display and appears italicized by default (disable with `<!i>`).\nExample: §a`\"<!i><#FF8C00>Topaz Sword\"`§r (MiniMessage formatting supported)."},
  "data.appearance.lore.complex.<n>.advanced.operation": {"zh":"高级 lore 行的附加方式：`APPEND`（默认，追加到末尾）或 `PREPEND`（插到开头）。\n用于条件行、分行文本或基于优先级的排序场景，配合 `content`、`priority`、`split_lines`、`conditions` 使用。","en":"How an advanced lore line is added: `APPEND` (default, appended to the end) or `PREPEND` (inserted at the top).\nUsed for conditional lines, split text, or priority-based ordering, together with `content`, `priority`, `split_lines`, and `conditions`."},
  "data.appearance.lore.complex.<n>.advanced.split_lines": {"zh":"设为 `true` 时，`content` 中的换行会被拆分为多行显示。\n示例: §a`content: \"Split\\nThis Line\"`§r → 显示为两行。","en":"When `true`, newlines in `content` are split into multiple lines.\nExample: §a`content: \"Split\\nThis Line\"`§r → renders as two lines."},
  "data.appearance.insert_lore.position": {"zh":"插入位置，四选一：§b`HEAD`§r（开头）/ §b`TAIL`§r（末尾）/ §b`BEFORE`§r（匹配行之前）/ §b`AFTER`§r（匹配行之后）。\n§6`BEFORE`/`AFTER` 需要配合 `pattern` 正则定位匹配行。","en":"Insertion position, one of: §b`HEAD`§r / §b`TAIL`§r / §b`BEFORE`§r / §b`AFTER`§r.\n§6`BEFORE`/`AFTER` require the `pattern` regex to locate the matching line."},
  "data.appearance.insert_lore.pattern": {"zh":"§b`BEFORE`/`AFTER`§r 位置时使用的正则表达式，用于定位插入点——匹配到的行之前或之后插入 `lore` 中定义的行。\n未匹配到任何行时使用 `fallback` 回落配置。","en":"Regex used to locate the insertion point for §b`BEFORE`/`AFTER`§r positions — lines from `lore` are inserted before/after the matching line.\nIf no line matches, the `fallback` config is used."},
  "data.appearance.insert_lore.fallback": {"zh":"可选。当 `pattern` 未匹配到任何行时使用的回落配置，含 `position`（回落插入位置）与 `lore`（要插入的行）。\n示例: §a`position: TAIL`§r + 一条 `<red>回落行`。","en":"Optional. Fallback config used when `pattern` doesn't match any line — contains `position` and `lore`.\nExample: §a`position: TAIL`§r plus a `<red>Fallback` line."},
  "data.appearance.insert_lore.fallback.position": {"zh":"回落时的插入位置，取值同 `position`：§b`HEAD`§r / §b`TAIL`§r / §b`BEFORE`§r / §b`AFTER`§r。\n示例: §a`position: TAIL`§r（未匹配时插到末尾）。","en":"Insertion position for the fallback, same values as `position`: §b`HEAD`§r / §b`TAIL`§r / §b`BEFORE`§r / §b`AFTER`§r.\nExample: §a`position: TAIL`§r (insert at the end when nothing matches)."},
  "data.appearance.remove_lore": {"zh":"按正则移除匹配的描述行。\n字符串简写: §a`remove_lore: \"Remove this line\"`§r\n也可用对象形式精细控制：`pattern`（匹配内容/正则）、`count`（移除数量上限）、`regex`（是否按正则匹配）。","en":"Removes lore lines matching a regex.\nString shorthand: §a`remove_lore: \"Remove this line\"`§r\nAn object form is also available: `pattern` (content/regex to match), `count` (max lines to remove), `regex` (whether to match as regex)."},
  "data.appearance.remove_lore.object.pattern": {"zh":"对象形式中要匹配并移除的行内容。默认按正则解释，可通过 `regex` 字段切换为字面匹配。","en":"The line content to match and remove in the object form. Interpreted as a regex by default; switch to literal matching with the `regex` field."},
  "data.appearance.remove_lore.object.count": {"zh":"移除的匹配行数量上限。\n省略时移除所有匹配行。","en":"Maximum number of matching lines to remove.\nIf omitted, all matching lines are removed."},
  "data.appearance.remove_lore.object.regex": {"zh":"设为 `true` 时 `pattern` 按正则匹配；设为 `false` 时按字面文本精确匹配。","en":"When `true`, `pattern` is matched as a regex; when `false`, it's matched as literal text."},
  "data.appearance.tooltip_style": {"zh":"工具提示背景纹理（1.21.2+）。\n示例: §a`tooltip_style: minecraft:topaz`§r（原版纹理），也可指向资源包自定义纹理。","en":"The tooltip background texture (1.21.2+).\nExample: §a`tooltip_style: minecraft:topaz`§r (vanilla), or a resource pack custom texture."},
  "data.appearance.hide_tooltip": {"zh":"隐藏特定组件的工具提示。封装了原版 `minecraft:tooltip_display`，支持跨版本（原 `HideFlags`）。\n列表项填组件名，如 §a`dyed_color`、`enchantments`、`attribute_modifiers`§r。","en":"Hides tooltips from specific components. Wraps vanilla `minecraft:tooltip_display` with cross-version support (formerly `HideFlags`).\nList the component names, e.g. §a`dyed_color`, `enchantments`, `attribute_modifiers`§r."},
  "data.appearance.dyed_color.object.rgb": {"zh":"对象形式的 RGB 颜色值，可写十进制整数或 `255,128,64` 形式。\n示例: §a`rgb: 16744512`§r（即 0xFF8040）。","en":"RGB color for the object form — a decimal integer or `255,128,64` syntax.\nExample: §a`rgb: 16744512`§r (i.e. 0xFF8040)."},
  "data.appearance.dyed_color.object.show_in_tooltip": {"zh":"是否在工具提示中显示该颜色信息。\n默认: §etrue§r。","en":"Whether the color shows in the tooltip.\nDefault: §etrue§r."},
  "data.appearance.trim.pattern": {"zh":"盔甲纹饰图案。\n原版图案: §b`coast`、`dune`、`eye`、`host`、`raiser`、`rib`、`sentinel`、`shaper`、`silence`、`snout`、`spire`、`tide`、`vex`、`ward`、`wayfinder`、`wild`、`flow`、`bolt`§r，也支持自定义。\n示例: §a`pattern: eye`§r","en":"Armor trim pattern.\nVanilla patterns: §b`coast`, `dune`, `eye`, `host`, `raiser`, `rib`, `sentinel`, `shaper`, `silence`, `snout`, `spire`, `tide`, `vex`, `ward`, `wayfinder`, `wild`, `flow`, `bolt`§r, or custom.\nExample: §a`pattern: eye`§r"},
  "data.appearance.trim.material": {"zh":"盔甲纹饰材料，决定纹饰颜色。\n原版材料: §b`quartz`、`iron`、`netherite`、`redstone`、`copper`、`gold`、`emerald`、`diamond`、`amethyst`、`lapis`、`resin`§r，也支持自定义。\n示例: §a`material: iron`§r","en":"Armor trim material, determines the trim color.\nVanilla materials: §b`quartz`, `iron`, `netherite`, `redstone`, `copper`, `gold`, `emerald`, `diamond`, `amethyst`, `lapis`, `resin`§r, or custom.\nExample: §a`material: iron`§r"},
  "data.appearance.profile.map.url": {"zh":"头颅纹理 URL，例如 `http://textures.minecraft.net/texture/ed83db5c...`。\n可从皮肤网站（如 Minecraft Heads）复制对应的纹理链接。","en":"Head texture URL, e.g. `http://textures.minecraft.net/texture/ed83db5c...`.\nCopy the texture link from skin sites (e.g. Minecraft Heads)."},
  "data.appearance.profile.map.base64": {"zh":"Base64 编码的头颅纹理数据，以 `eyJ0ZXh0dXJlcyI6...` 开头。\n需从皮肤网站获取。","en":"Base64-encoded head texture data, starting with `eyJ0ZXh0dXJlcyI6...`.\nObtain it from skin sites."},
  "data.behavior.food.nutrition": {"zh":"恢复的饥饿值。\n取值范围 §e0~20§r，整数。\n示例: §a`nutrition: 5`§r","en":"Hunger points restored.\nRange §e0~20§r, integer.\nExample: §a`nutrition: 5`§r"},
  "data.behavior.food.saturation": {"zh":"恢复的饱和度。\n取值范围 §e0~10§r，浮点数。\n示例: §a`saturation: 3.5`§r","en":"Saturation restored.\nRange §e0~10§r, float.\nExample: §a`saturation: 3.5`§r"},
  "data.behavior.food.can_always_eat": {"zh":"饥饿值满时是否仍可食用。\n默认: §efalse§r\n示例: §a`can_always_eat: true`§r（金苹果类食物常用）。","en":"Whether the item can be eaten even when hunger is full.\nDefault: §efalse§r\nExample: §a`can_always_eat: true`§r (typical for golden-apple style food)."},
  "data.behavior.food.eat_seconds": {"zh":"吃完整件食物所需的时间（秒）。\n原版食物的默认值约为 §e1.6§r 秒。","en":"Seconds it takes to eat the food.\nVanilla food takes about §e1.6§r seconds by default."},
  "data.behavior.food.using_converts_to": {"zh":"吃完后返还的物品，如碗、空瓶。\n示例: §a`using_converts_to: minecraft:bowl`§r","en":"Item returned after eating, e.g. a bowl or empty bottle.\nExample: §a`using_converts_to: minecraft:bowl`§r"},
  "data.behavior.food.effects.<n>.effect": {"zh":"列表中的每一项描述吃下后施加的一个状态效果：`effect` 为效果 ID。\n示例: §a`effect: minecraft:speed`§r\n配合 `probability`、`duration`、`amplifier`、`ambient`、`show_particles`、`show_icon` 使用。","en":"Each list entry describes a status effect applied when eaten: `effect` is the effect id.\nExample: §a`effect: minecraft:speed`§r\nCombine with `probability`, `duration`, `amplifier`, `ambient`, `show_particles`, and `show_icon`."},
  "data.behavior.food.effects.<n>.probability": {"zh":"该效果触发的概率，取值 §e0~1§r。\n示例: §a`probability: 0.5`§r 表示 50% 概率。","en":"Probability the effect applies, §e0~1§r.\nExample: §a`probability: 0.5`§r = 50% chance."},
  "data.behavior.food.effects.<n>.duration": {"zh":"效果持续时间（刻，§e20 刻 = 1 秒§r）。\n示例: §a`duration: 200`§r = 10 秒。","en":"Effect duration in ticks (§e20 ticks = 1 second§r).\nExample: §a`duration: 200`§r = 10 seconds."},
  "data.behavior.food.effects.<n>.amplifier": {"zh":"效果等级，§e0 = I 级§r。\n示例: §a`amplifier: 1`§r = II 级。","en":"Effect amplifier, §e0 = level I§r.\nExample: §a`amplifier: 1`§r = level II."},
  "data.behavior.food.effects.<n>.ambient": {"zh":"是否为环境效果（粒子更淡、不降低玩家视角亮度，类似信标给予的效果）。\n默认: §efalse§r","en":"Whether it's an ambient effect (fainter particles, no screen darkness — like beacon effects).\nDefault: §efalse§r"},
  "data.behavior.food.effects.<n>.show_particles": {"zh":"是否显示该效果的粒子。\n默认: §etrue§r","en":"Whether to show effect particles.\nDefault: §etrue§r"},
  "data.behavior.food.effects.<n>.show_icon": {"zh":"是否在 HUD 中显示该效果的图标。\n默认: §etrue§r","en":"Whether to show the effect icon on the HUD.\nDefault: §etrue§r"},
  "data.behavior.equippable": {"zh":"使物品可穿戴在装备槽位中（1.21.2+）。\n字段: `slot`（槽位）、`asset_id`（装备模型）、`camera_overlay`（叠加纹理）、`swappable`（右键装备）、`damage_on_hurt`（受伤损耐久）、`dispensable`（发射器）、`equip_on_interact`（对生物使用，1.21.5+）、`allowed_entities`、`equip_sound`。","en":"Lets the item be worn in an equipment slot (1.21.2+).\nFields: `slot`, `asset_id` (equipment model), `camera_overlay`, `swappable`, `damage_on_hurt`, `dispensable`, `equip_on_interact` (1.21.5+), `allowed_entities`, `equip_sound`."},
  "data.behavior.equippable.allowed_entities": {"zh":"允许装备此物品的实体类型列表。\n示例: §a`[minecraft:horse, minecraft:llama]`§r\n省略时仅限玩家装备。","en":"List of entity types allowed to equip this item.\nExample: §a`[minecraft:horse, minecraft:llama]`§r\nIf omitted, only players can equip it."},
  "data.behavior.equippable.equip_sound": {"zh":"装备时播放的音效事件。\n示例: §a`minecraft:item.armor.equip_iron`§r","en":"Sound event played when equipped.\nExample: §a`minecraft:item.armor.equip_iron`§r"},
  "data.behavior.use_remainder.object.id": {"zh":"使用后替换此物品的剩余物 ID。\n示例: §a`default:chicken_bone`§r 或 `minecraft:bowl`。","en":"The item id this stack is replaced with after use.\nExample: §a`default:chicken_bone`§r or `minecraft:bowl`."},
  "data.behavior.use_remainder.object.count": {"zh":"替换后的剩余物数量。\n默认: §e1§r（可选）。","en":"Count of the remainder item.\nDefault: §e1§r (optional)."},
  "data.behavior.unbreakable.object.show_in_tooltip": {"zh":"是否在工具提示中显示\"无法破坏\"字样。\n默认: §etrue§r\n简写形式 §a`unbreakable: true`§r 与之等效。","en":"Whether \"Unbreakable\" shows in the tooltip.\nDefault: §etrue§r\nShorthand §a`unbreakable: true`§r is equivalent."},
  "data.behavior.max_damage": {"zh":"物品的最大耐久度（1.20.5+）。\n示例: §a`max_damage: 100`§r\n§6注意: 需搭配有耐久度的材质（如 `material: wooden_sword`）才有效。","en":"The item's maximum durability (1.20.5+).\nExample: §a`max_damage: 100`§r\n§6Note: pair it with a durable material (e.g. `material: wooden_sword`) for it to take effect."},
  "data.behavior.attribute_modifiers.<n>.amount": {"zh":"属性修饰符的数值。\n示例: §a`amount: 1.0`§r（+1 攻击速度）。","en":"The modifier amount.\nExample: §a`amount: 1.0`§r (+1 attack speed)."},
  "data.behavior.attribute_modifiers.<n>.operation": {"zh":"运算方式，三选一：§b`add_value`§r（加固定值）/ §b`add_multiplied_base`§r（按基础值百分比加）/ §b`add_multiplied_total`§r（按总值百分比加）。\n示例: §a`operation: add_value`§r","en":"Operation, one of: §b`add_value`§r (add fixed amount) / §b`add_multiplied_base`§r (percent of base value) / §b`add_multiplied_total`§r (percent of total value).\nExample: §a`operation: add_value`§r"},
  "data.behavior.attribute_modifiers.<n>.id": {"zh":"修饰符的唯一标识符（命名空间格式），用于识别修饰符、避免重复叠加。\n示例: §a`id: namespace:custom_attribute`§r\n可选。","en":"Unique modifier id (namespaced), used to identify the modifier and prevent duplicate stacking.\nExample: §a`id: namespace:custom_attribute`§r\nOptional."},
  "data.behavior.enchantment.merge.merge": {"zh":"设为 `true` 时，新附魔会与物品已有的附魔**合并**，而不是整体覆盖。\n示例: §a`merge: true`§r，配合 `enchantments` 映射使用。","en":"When `true`, the new enchantments **merge** with the item's existing enchantments instead of overwriting them.\nExample: §a`merge: true`§r, combined with the `enchantments` map."},
  "data.behavior.enchantment.merge.enchantments": {"zh":"要应用的附魔映射，键为附魔 ID、值为等级。\n示例: §a`minecraft:sharpness: 3`§r","en":"Map of enchantment id → level to apply.\nExample: §a`minecraft:sharpness: 3`§r"},
  "data.behavior.painting_variant": {"zh":"画作变体（物品为画时显示的图案）。\n示例: §a`painting_variant: default:painting_custom`§r","en":"The painting variant shown when this item is a painting.\nExample: §a`painting_variant: default:painting_custom`§r"},
  "data.behavior.jukebox_playable.object.song": {"zh":"唱片机曲目 ID（1.21+）。\n示例: §a`song: default:credits_music`§r 或 `minecraft:13`\n曲目需已在 CraftEngine 中注册（见唱片曲目配置）。","en":"The jukebox song id (1.21+).\nExample: §a`song: default:credits_music`§r or `minecraft:13`\nThe song must be registered in CraftEngine (see the jukebox song config)."},
  "data.behavior.jukebox_playable.object.show_in_tooltip": {"zh":"是否在工具提示中显示曲目名。\n默认: §etrue§r","en":"Whether the song name shows in the tooltip.\nDefault: §etrue§r"},
  "data.behavior.block_state": {"zh":"放置此物品为方块时应用的方块状态属性。同时能改善高延迟玩家的放置体验。别名: `blockstate`。\n两种形式：详细属性映射（如 §a`note: \"1\"`§r、`powered: \"false\"`）或简写 §a`default:palm_sapling[stage=0]`§r（从已定义的自定义方块复制状态）。\n§6注意: 材质必须在视觉上与方块状态匹配——方块类物品用 `note_block`/`mushroom_stem` 而非 `paper`。","en":"Block state properties applied when placing this item as a block. Also improves placement responsiveness for high-latency players. Alias: `blockstate`.\nTwo forms: a detailed property map (e.g. §a`note: \"1\"`§r, `powered: \"false\"`) or shorthand §a`default:palm_sapling[stage=0]`§r (copies state from a defined custom block).\n§6Note: the material must visually match the block state — use `note_block`/`mushroom_stem`, not `paper`, for block items."},
  "data.storage.pdc": {"zh":"存储自定义键值数据供其他插件读取（持久数据容器）。\n示例: §a`key: \"value\"`§r、§a`number: 42`§r、§a`list: [1, 2]`§r。","en":"Stores custom key-value data for other plugins to read (Persistent Data Container).\nExample: §a`key: \"value\"`§r, §a`number: 42`§r, §a`list: [1, 2]`§r."},
  "data.storage.nbt": {"zh":"底层 NBT 访问。在物品上设置任意 NBT 标签。对键名使用 `@` 前缀可展平嵌套结构。\n示例: §a`CustomTag: \"value\"`§r、§a`\"@nested.path\": 42`§r\n别名: `tags`。","en":"Low-level NBT access. Sets arbitrary NBT tags on the item. Use `@` prefix on keys to flatten nested structures.\nExample: §a`CustomTag: \"value\"`§r, §a`\"@nested.path\": 42`§r\nAlias: `tags`."},
  "data.storage.written_book_content": {"zh":"设置成书的内容——标题、作者、版本与页面（1.20.5+）。需要物品材质为 `written_book`。\n字段: `title`（也支持 `raw`/`filtered` 对象形式）、`author`、`generation`、`resolved`、`pages`。\n文本支持 MiniMessage，`<arg:...>` 占位符基于构建上下文（如查看物品的玩家）解析。","en":"Sets the content of a written book — title, author, generation, and pages (1.20.5+). Apply it to an item whose material is `written_book`.\nFields: `title` (also accepts the `raw`/`filtered` map form), `author`, `generation`, `resolved`, `pages`.\nText supports MiniMessage; `<arg:...>` placeholders resolve against the build context (e.g. the player viewing the item)."},
  "data.storage.written_book_content.pages.<n>.raw_filtered.raw": {"zh":"页面对象形式的原始文本（支持 MiniMessage 格式）。\n示例: §a`raw: \"<red>Advanced page\"`§r","en":"Raw text of the page in the object form (MiniMessage formatting supported).\nExample: §a`raw: \"<red>Advanced page\"`§r"},
  "data.storage.written_book_content.pages.<n>.raw_filtered.filtered": {"zh":"过滤后的文本，仅对开启聊天过滤的玩家显示。","en":"Filtered version of the text, shown only to players with chat filter enabled."},
  "data.storage.written_book_content.resolved": {"zh":"文本是否已解析。\n示例为 §a`false`§r；设为 `true` 表示文本已预先解析为组件。","en":"Whether the text is already resolved.\n`false` in the docs example; `true` means the text is pre-resolved into components."},
  "data.storage.written_book_content.generation": {"zh":"成书版本: §a`0`§r 原著、§a`1`§r 原稿的副本、§a`2`§r 副本的副本、§a`3`§r 破烂不堪。","en":"Book generation: §a`0`§r original, §a`1`§r copy of original, §a`2`§r copy of a copy, §a`3`§r tattered."},
  "data.external.external": {"zh":"继承其他插件物品的数据。\n字段: `plugin`（外部插件名，如 §a`neigeitems`§r 或 `source`）与 `id`（该插件中的物品 ID）。\n支持的插件见\"外部物品来源\"文档。","en":"Inherit data from another plugin's item.\nFields: `plugin` (the external plugin, e.g. §a`neigeitems`§r or `source`) and `id` (the item id in that plugin).\nSee \"External Item Sources\" for supported plugins."},
  "data.external.external.plugin": {"zh":"外部插件名称。\n示例: §a`neigeitems`§r，或 `source`。","en":"The external plugin name.\nExample: §a`neigeitems`§r, or `source`."},
  "data.external.external.id": {"zh":"外部插件中的物品 ID。\n示例: §a`example_item`§r","en":"The item id inside the external plugin.\nExample: §a`example_item`§r"},
  "data.components.components": {"zh":"自定义组件（1.20.5+）——不由 CraftEngine 维护或进行版本检查，格式可能随 Minecraft 更新而变动。\n键为组件 ID，如 §a`minecraft:max_damage`、`minecraft:food`、`minecraft:instrument`、`minecraft:fireworks`§r。\n组件仅需存在（无需值）时写 §a`minecraft:unbreakable: {}`§r。完整参考见 Minecraft Wiki 数据组件。","en":"Custom components (1.20.5+) — not maintained or version-checked by CraftEngine. Format may break across Minecraft updates.\nKey = component id, e.g. §a`minecraft:max_damage`, `minecraft:food`, `minecraft:instrument`, `minecraft:fireworks`§r.\nFor presence-only components use §a`minecraft:unbreakable: {}`§r. See the Minecraft Wiki data component format for the full reference."},
  "data.components.remove_components": {"zh":"从物品上移除指定的组件。\n示例: §a`- minecraft:equippable`§r（移除原版可装备组件）。","en":"Removes the listed components from the item.\nExample: §a`- minecraft:equippable`§r (removes the vanilla equippable component)."},
  "settings.destroy_stages.items": {"zh":"用于替换原版挖掘**裂纹**的自定义物品列表，如 `minecraft:destroy_stage_0`。可以指定**任意数量**的物品，按顺序在挖掘过程中依次显示。\n示例: §a`items:\n  - minecraft:destroy_stage_0\n  - minecraft:destroy_stage_1\n  - minecraft:destroy_stage_2`§r","en":"List of custom items that replace the vanilla crack textures, e.g. `minecraft:destroy_stage_0`. Any number of items works, shown in order as the block is mined. # ... Any number of items\nExample: §a`items:\n  - minecraft:destroy_stage_0`§r"},
  "settings.destroy_stages.position": {"zh":"**绝对位置** (x,y,z)，默认方块中心。§6推荐优先使用 `translation`（偏移量）调整位置——它不改变坐标，可避免发送位置同步数据包，保证最佳视觉表现。\n示例: §a`position: 0.5,0.5,0.5`§r（默认方块中心）","en":"**Absolute position** (x,y,z), defaults to the block center. §6Using `translation` (offset) is recommended over `position` — it shifts the entity without changing its coordinate, avoiding position sync packets.\nExample: §a`position: 0.5,0.5,0.5`§r (default block center)"},
  "settings.destroy_stages.scale": {"zh":"缩放 (x,y,z)，如 `1,1,1`。也支持**单个数字**（如 `scale: 1.5`），三个轴等比缩放。\n示例: §a`scale: 1,1,1`§r","en":"Scale (x,y,z), e.g. `1,1,1`. A single number like `scale: 1.5` also works (uniform scaling on all axes).\nExample: §a`scale: 1,1,1`§r"},
  "settings.destroy_stages.yaw": {"zh":"绕 **Y 轴**旋转的角度。\n示例: §a`yaw: 0`§r\n§6提示：优先使用 `rotation` 代替 `yaw`/`pitch`，可避免发送位置同步数据包，保证最佳视觉表现。","en":"Rotation angle around the **Y axis**.\nExample: §a`yaw: 0`§r\n§6Tip: prefer `rotation` over `yaw`/`pitch` to avoid sending position sync packets and ensure the best visual performance."},
  "settings.destroy_stages.pitch": {"zh":"绕 **X 轴**旋转的角度。\n示例: §a`pitch: 0`§r\n§6提示：优先使用 `rotation` 代替 `yaw`/`pitch`，可避免发送位置同步数据包，保证最佳视觉表现。","en":"Rotation angle around the **X axis**.\nExample: §a`pitch: 0`§r\n§6Tip: prefer `rotation` over `yaw`/`pitch` to avoid sending position sync packets and ensure the best visual performance."},
  "settings.destroy_stages.rotation": {"zh":"旋转设置，三种写法：\n- 单个数字 → 绕 **Y 轴**旋转\n- 欧拉角 (x,y,z)\n- 四元数 (x,y,z,w)\n示例: §a`rotation: 45`§r / §a`rotation: 45,45,0`§r / §a`rotation: 0,0,0.707,0.707`§r\n§6推荐使用 `rotation` 代替 `yaw`/`pitch`，可避免发送位置同步数据包。可配合 Wiki 页面中的旋转工具直观调整。","en":"Rotation setting in three forms:\n- A single number → rotation around the **Y axis**\n- Euler angles (x,y,z)\n- Quaternion (x,y,z,w)\nExamples: §a`rotation: 45`§r / §a`rotation: 45,45,0`§r / §a`rotation: 0,0,0.707,0.707`§r\n§6Prefer `rotation` over `yaw`/`pitch`. See the rotation tool linked on the wiki page."},
  "settings.destroy_stages.display_transform": {"zh":"物品展示变换模式，用于再次变换物品模型。可选取值: §bnone§r / §bthird_person_left_hand§r / §bthird_person_right_hand§r / §bfirst_person_left_hand§r / §bfirst_person_right_hand§r / §bhead§r / §bgui§r / §bground§r / §bfixed§r\n示例: §a`display_transform: none`§r","en":"Item display transform mode used to transform the item model again. Valid values: §bnone§r / §bthird_person_left_hand§r / §bthird_person_right_hand§r / §bfirst_person_left_hand§r / §bfirst_person_right_hand§r / §bhead§r / §bgui§r / §bground§r / §bfixed§r\nExample: §a`display_transform: none`§r"},
  "settings.destroy_stages.billboard": {"zh":"广告牌显示模式：\n- §bfixed§r 固定垂直和水平轴\n- §bvertical§r 固定垂直轴\n- §bhorizontal§r 固定水平轴\n- §bcenter§r 按照中心旋转跟随玩家视角\n示例: §a`billboard: fixed`§r","en":"Billboard mode:\n- §bfixed§r locks both vertical and horizontal axes\n- §bvertical§r locks the vertical axis\n- §bhorizontal§r locks the horizontal axis\n- §bcenter§r rotates around the center to follow the player's view\nExample: §a`billboard: fixed`§r"},
  "settings.destroy_stages.view_range": {"zh":"可视距离系数，控制裂纹在远处是否可见，数值越大可见距离越远。\n示例: §a`view_range: 1.0`§r","en":"View distance coefficient controlling how far away the crack display stays visible; larger values extend the visible range.\nExample: §a`view_range: 1.0`§r"},
  "settings.destroy_stages.brightness": {"zh":"渲染亮度覆盖，包含子选项 `block_light` 与 `sky_light`。§6两者必填，否则该配置无效。\n示例: §a`brightness:\n  block_light: 15\n  sky_light: 15`§r","en":"Brightness override with `block_light` and `sky_light` sub-options. §6Both are required or the option has no effect.\nExample: §a`brightness:\n  block_light: 15\n  sky_light: 15`§r"},
  "settings.destroy_stages.brightness.block_light": {"zh":"方块光照亮度值（0-15）。与 `sky_light` 配合使用；§6两者必填否则 `brightness` 无效。\n示例: §a`block_light: 15`§r","en":"Block light brightness value (0-15). Used together with `sky_light`; §6both are required or `brightness` has no effect.\nExample: §a`block_light: 15`§r"},
  "settings.destroy_stages.brightness.sky_light": {"zh":"天空光照亮度值（0-15）。与 `block_light` 配合使用；§6两者必填否则 `brightness` 无效。\n示例: §a`sky_light: 15`§r","en":"Sky light brightness value (0-15). Used together with `block_light`; §6both are required or `brightness` has no effect.\nExample: §a`sky_light: 15`§r"},
  "settings.jump_factor": {"zh":"跳跃乘数。§6Wiki 仅给出示例 `jump_factor: 1.0`，未提供详细说明。属于**不稳定设置**，只对非玩家实体生效。对应原版方块的跳跃高度倍率（如蜂蜜块为 0.5，普通方块为 1.0）。","en":"Jump multiplier. §6The wiki only shows the example `jump_factor: 1.0` with no further explanation. It's an unstable setting that only works for entities other than players. Maps to the vanilla jump factor (honey block 0.5, normal blocks 1.0)."},
  "settings.speed_factor": {"zh":"速度乘数。§6Wiki 仅给出示例 `speed_factor: 1.0`，未提供详细说明。属于**不稳定设置**，只对非玩家实体生效。对应原版方块的速度倍率（如灵魂沙为 0.4）。","en":"Speed multiplier. §6The wiki only shows the example `speed_factor: 1.0` with no further explanation. It's an unstable setting that only works for entities other than players. Maps to the vanilla speed factor (soul sand 0.4)."},
  "content_overrides": {"zh":"**按场景切换内容**：不同场景（聊天、书、铁砧、告示牌、指令等）可能需要不同的显示效果，用 `content_overrides` 分别指定，键为场景名。某个场景没有 override 时，会使用默认的 `content`。\n示例: §a`content_overrides:\n  chat: \"<hover:show_text:'<arg:keyword>'><!shadow><white><arg:emoji></white></!shadow></hover>\"\n  book: \"<!shadow><white><arg:emoji></white></!shadow>\"`§r","en":"**Context-specific overrides**: different chat contexts (chat, book, anvil, sign, command) may need different formatting, specified via `content_overrides` with the context name as the key. When a context has no override, the default `content` is used.\nExample: §a`content_overrides:\n  chat: \"<hover:show_text:'<arg:keyword>'><!shadow><white><arg:emoji></white></!shadow></hover>\"\n  book: \"<!shadow><white><arg:emoji></white></!shadow>\"`§r"},
  "pattern": {"zh":"有序配方（`shaped` / `shaped_transform`）的合成图案。列表中的每个字符串是一行，行内每个字符对应一个原料键（如 `A`、`B`、`C`），空格表示空格子。\n示例: §a`- \"ABA\"\\n- \"BCB\"\\n- \"ABA\"`§r\n§6注意: smithing_trim 配方中 `pattern` 是纹饰图案 ID（如 `minecraft:bolt`），1.21.5+ 必填。§r","en":"The pattern for shaped recipes (`shaped`/`shaped_transform`): each string is one row; each character is an ingredient key (e.g. `A`, `B`, `C`); spaces are empty.\nExample: §a`- \"ABA\"\\n- \"BCB\"\\n- \"ABA\"`§r\n§6In `smithing_trim`, `pattern` is the trim pattern id, required on 1.21.5+.§r"},
  "ingredients.map.<k>.details.item": {"zh":"单个物品 ID。\n示例: §a`item: minecraft:crossbow`§r。与 `items` 用法相同，但更常与 `source: true` 搭配，用于标记转化配方中的源物品。","en":"A single item id.\nExample: §a`item: minecraft:crossbow`§r. Same usage as `items`, but more commonly paired with `source: true` to mark the source item in transform recipes."},
  "ingredients.map.<k>.details.items": {"zh":"物品 ID 或标签（如 §a`minecraft:cobblestone`§r 或 §a`#default:palm_logs`§r）。可与 `count` 组合要求指定数量，如 §a`items: \"minecraft:cobblestone\"\\ncount: 32`§r。","en":"Item id or tag (e.g. §a`minecraft:cobblestone`§r or §a`#default:palm_logs`§r). Combine with `count` to require a specific amount, e.g. §a`items: \"minecraft:cobblestone\"\\ncount: 32`§r."},
  "ingredients.map.<k>.details.count": {"zh":"该原料所需的数量。\n示例: §a`items: \"minecraft:cobblestone\"\\ncount: 32`§r（要求 32 个圆石）。","en":"How many of this ingredient are required.\nExample: §a`items: \"minecraft:cobblestone\"\\ncount: 32`§r (requires 32 cobblestone)."},
  "ingredients.map.<k>.details.source": {"zh":"设为 `true` 时将该原料标记为**源物品**（仅转化配方：`shaped_transform`、`shapeless_transform`）。源物品的数据会被合并到最终结果中，适合用于升级已有物品。\n示例: §a`item: minecraft:crossbow\\nsource: true`§r","en":"When `true`, marks this ingredient as the **source item** (transform recipes only: `shaped_transform`, `shapeless_transform`). The source item's data is merged into the final result, making it ideal for upgrading existing items.\nExample: §a`item: minecraft:crossbow\\nsource: true`§r"},
  "ingredients.map.<k>.details.predicate": {"zh":"谓词允许你为配方原料设置除物品 ID 或标签之外的额外条件，例如特定魔咒或数据组件。\n可用类型: §b`enchantment`§r（检查魔咒）与 §b`exact`§r（精确数据组件匹配，高级）。","en":"Predicates allow you to require additional conditions on ingredients beyond just their item ID or tag, such as specific enchantments or data components.\nAvailable types: §b`enchantment`§r (check enchantments) and §b`exact`§r (exact data component match, advanced)."},
  "ingredients.map.<k>.details.predicate.<n>.enchantment.enchantments": {"zh":"魔咒等级映射：键为魔咒 ID，值为所需等级。\n示例: §a`enchantments:\\n  minecraft:sharpness: 5`§r（要求锋利 V）。","en":"Enchantment level map: the key is the enchantment id, the value is the required level.\nExample: §a`enchantments:\\n  minecraft:sharpness: 5`§r (requires Sharpness V)."},
  "ingredients.map.<k>.details.predicate.<n>.exact.component": {"zh":"要精确匹配的数据组件 ID（高级）。\n示例: §a`- type: exact\\n  component: minecraft:custom_name`§r。需配合 `value` 填写 NBT 标签值。","en":"The data component id to match exactly (advanced).\nExample: §a`- type: exact\\n  component: minecraft:custom_name`§r. Pair it with `value` for the NBT tag value."},
  "ingredients.map.<k>.details.predicate.<n>.exact.value": {"zh":"组件精确匹配时的 NBT 标签值。\n示例: §a`- type: exact\\n  component: minecraft:custom_name\\n  value: ...`§r（NBT 标签值）。","en":"The NBT tag value the component must have for an exact match.\nExample: §a`- type: exact\\n  component: minecraft:custom_name\\n  value: ...`§r (NBT tag value)."},
  "ingredients.list.<n>.details.item": {"zh":"单个物品 ID。\n示例: §a`item: minecraft:crossbow`§r。与 `items` 用法相同，但更常与 `source: true` 搭配，用于标记转化配方中的源物品。","en":"A single item id.\nExample: §a`item: minecraft:crossbow`§r. Same usage as `items`, but more commonly paired with `source: true` to mark the source item in transform recipes."},
  "ingredients.list.<n>.details.items": {"zh":"物品 ID 或标签（如 §a`minecraft:cobblestone`§r 或 §a`#default:palm_logs`§r）。可与 `count` 组合要求指定数量，如 §a`items: \"minecraft:cobblestone\"\\ncount: 32`§r。\n无序配方还支持嵌套列表（元素是一组原料，任意满足其一即可）。","en":"Item id or tag (e.g. §a`minecraft:cobblestone`§r or §a`#default:palm_logs`§r). Combine with `count` to require a specific amount, e.g. §a`items: \"minecraft:cobblestone\"\\ncount: 32`§r.\nShapeless recipes also support nested lists."},
  "ingredients.list.<n>.details.count": {"zh":"该原料所需的数量。\n示例: §a`items: \"minecraft:cobblestone\"\\ncount: 32`§r（要求 32 个圆石）。","en":"How many of this ingredient are required.\nExample: §a`items: \"minecraft:cobblestone\"\\ncount: 32`§r (requires 32 cobblestone)."},
  "ingredients.list.<n>.details.source": {"zh":"设为 `true` 时将该原料标记为**源物品**（仅转化配方：`shapeless_transform`）。源物品的数据会被合并到最终结果中，适合用于升级已有物品。\n示例: §a`items: minecraft:diamond_sword\\nsource: true`§r","en":"When `true`, marks this ingredient as the **source item** (transform recipes only: `shapeless_transform`). The source item's data is merged into the final result, making it ideal for upgrading existing items.\nExample: §a`items: minecraft:diamond_sword\\nsource: true`§r"},
  "ingredients.list.<n>.details.predicate": {"zh":"谓词允许你为配方原料设置除物品 ID 或标签之外的额外条件，例如特定魔咒或数据组件。\n可用类型: §b`enchantment`§r（检查魔咒）与 §b`exact`§r（精确数据组件匹配，高级）。","en":"Predicates allow you to require additional conditions on ingredients beyond just their item ID or tag, such as specific enchantments or data components.\nAvailable types: §b`enchantment`§r (check enchantments) and §b`exact`§r (exact data component match, advanced)."},
  "ingredient": {"zh":"单个原料物品 ID（烧炼、切石机、酿造配方使用）。\n示例: §a`ingredient: \"default:topaz_ore\"`§r\n§6注意: 切石机配方不建议使用自定义物品作为原料，极可能导致严重的客户端显示问题。§r","en":"A single ingredient item id (used by cooking, stonecutting, and brewing recipes).\nExample: §a`ingredient: \"default:topaz_ore\"`§r\n§6Note: for stonecutting recipes, using custom items as ingredients is not recommended — it is highly likely to cause significant client-side visual issues.§r"},
  "experience": {"zh":"烧炼配方（`smelting` / `blasting` / `smoking` / `campfire_cooking`）产生的经验值。\n示例: §a`experience: 1.0`§r","en":"The experience produced by cooking recipes (`smelting` / `blasting` / `smoking` / `campfire_cooking`).\nExample: §a`experience: 1.0`§r"},
  "time": {"zh":"烧炼配方所需的时间，单位: 游戏刻（20 刻 = 1 秒）。四种烧炼类型（`smelting` / `blasting` / `smoking` / `campfire_cooking`）格式相同。\n示例: §a`time: 200`§r（即 10 秒）。","en":"How long the cooking recipe takes, in ticks (20 ticks = 1 second). All four cooking types use the same format.\nExample: §a`time: 200`§r (10 seconds)."},
  "template_type": {"zh":"锻造模板槽（槽位 1，可选）。\n示例: §a`template_type: default:topaz`§r。盔甲纹饰（`smithing_trim`）配方中为纹饰模板 ID，如 §a`minecraft:bolt_armor_trim_smithing_template`§r。","en":"The smithing template slot (slot 1, optional).\nExample: §a`template_type: default:topaz`§r. For `smithing_trim` recipes it is the trim template id, e.g. §a`minecraft:bolt_armor_trim_smithing_template`§r."},
  "container": {"zh":"酿造配方的容器物品 ID（1.20.2+）。\n示例: §a`container: tea_art:cup`§r。酿造配方还需 `ingredient`（原料）与 `result`（产物）。","en":"The container item id for brewing recipes (1.20.2+).\nExample: §a`container: tea_art:cup`§r. A brewing recipe also needs `ingredient` and `result`."},
  "result": {"zh":"配方产物。包含 `id`（产物物品 ID）、`count`（数量）与 `post_processors`（结果后处理器）。\n示例: §a`result:\\n  id: default:topaz\\n  count: 1`§r\n§6注意: 重载数据包后请重载配方，否则注册的配方会失效。§r","en":"The recipe result. Contains `id` (the result item id), `count` (quantity) and `post_processors` (result post processors).\nExample: §a`result:\\n  id: default:topaz\\n  count: 1`§r\n§6Note: after reloading datapacks, reload the recipes, otherwise the registered recipes become invalid.§r"},
  "result.id": {"zh":"产物物品的 ID（自定义物品或原版物品），采用 `namespace:path` 格式。\n示例: §a`id: default:topaz_sword`§r","en":"The id of the result item (custom or vanilla), in `namespace:path` form.\nExample: §a`id: default:topaz_sword`§r"},
  "result.count": {"zh":"产物数量。\n示例: §a`count: 4`§r（一次合成产出 4 个）。合成配方（`shaped` / `shapeless`）可产出多于 1 个的产物。","en":"How many items the recipe produces.\nExample: §a`count: 4`§r (a single craft yields 4 items). Crafting recipes (`shaped` / `shapeless`) can output more than one item."},
  "result.post_processors.<n>.apply_data.data": {"zh":"应用到产物上的物品数据（与物品 data 格式相同）。\n示例: §a`enchantment:\\n  minecraft:efficiency: 5`§r（给产出的镐附上效率 V）。\n§6目前只有 apply_data 一种后处理器，可通过 API 注册新的。§r","en":"Item data applied to the result (same format as item data).\nExample: §a`enchantment:\\n  minecraft:efficiency: 5`§r (give the crafted pickaxe Efficiency V).\n§6So far only the apply_data type exists; you can register new ones via the API.§r"},
  "template.material": {"zh":"模板条目的基础材质（原版物品 ID），与物品配置中的 `material` 语义相同：默认值为 config.yml 中配置的默认材质（默认 §e`nether_brick`§r），对原版物品 ID 无效，其余内容按需添加。","en":"The vanilla material this template entry is built on, same semantics as the item-level `material`: it defaults to the value configured in config.yml (defaults to §e`nether_brick`§r), is ignored for vanilla item IDs — everything else is added when needed."},
  });
})();
